    internal static async Task RunTask10HeadlessRoute(SceneTree tree, Task10RouteVariant variant,
        bool riftWallOnly = false)
    {
        TestAssert.True(DisplayServer.GetName() == "headless" && KeyboardRouteInputDriver.Current == null,
            "whole-route physics diagnostic never impersonates the visible realtime runner");
        PrologueContinuousRouteResult result = await RunTask10(tree, variant,
            gearEntryWindowOnly: false, headlessNormalPlan: true, riftWallOnly: riftWallOnly);
        if (riftWallOnly)
        {
            TestAssert.True(result.Variant == "RiftWallDiagnostic" && result.StartedFromTitle &&
                result.PersistentPlayer && result.PlayerInstanceId != 0 &&
                result.RecoveryRequests == 0 && result.RecoveryCompletions == 0,
                "localized Rift wall receipt retains the original keyboard route's start and player with zero recovery");
            return;
        }
        result.AssertComplete(variant.ToString());
        TestAssert.True(result.NormalRangedExerciseRequired &&
            result.RecoveryRequests == 0 && result.RecoveryCompletions == 0,
            "headless complete diagnostic keeps the original actual ranged and zero-recovery gates");
        AssertNormalRangedExercise(variant.ToString(), result.NormalRangedInstances);
        GD.Print("RANGED_HEADLESS_DIAGNOSTIC_INSTANCE_RECEIPTS " +
            System.Text.Json.JsonSerializer.Serialize(result.NormalRangedInstances));
        string path = Task10RouteResultArtifact.Persist(result, variant.ToString(),
            IsolatedPrologueFixture.ValidateStorageRoot(), syntheticFixture: false);
        GD.Print($"THRUSTER_ROUTE_DIAGNOSTIC_OK variant={variant} headless=true normal_plan=true " +
            $"actual_ranged_gates=true boss_and_supported_exit=true artifact={path} " +
            "normal_display=false human=false performance_certification=false whole_goal=false");
    }

    private static async Task<PrologueContinuousRouteResult> RunTask10(SceneTree tree,
        Task10RouteVariant variant, bool gearEntryWindowOnly, NaturalFragmentRouteContext naturalRoute = null,
        bool descentHandoffOnly = false, bool headlessNormalPlan = false, bool riftWallOnly = false)
    {
        TestAssert.True(!headlessNormalPlan || (DisplayServer.GetName() == "headless" &&
            !gearEntryWindowOnly && !descentHandoffOnly && naturalRoute == null &&
            Array.Exists(OS.GetCmdlineUserArgs(), value => value == "--keyboard-route")),
            "explicit headless normal plan only belongs to a keyboard-route diagnostic");
        TestAssert.True(!riftWallOnly || headlessNormalPlan && variant == Task10RouteVariant.Main,
            "Rift wall receipt only branches from the actual headless keyboard Main prefix");
        ReleaseAll(Vector2.Zero);
        Task10ApplicationPersistenceGuard persistence =
            Task10ApplicationPersistenceGuard.CreateFromArguments();
        PackedScene packed = GD.Load<PackedScene>(MainPath) ??
            throw new InvalidOperationException($"exact generated main scene is missing: {MainPath}");
        PrologueLevelController level = packed.Instantiate<PrologueLevelController>();
        level.Name = $"Task10{variant}RouteProof";
        PrologueGameFlowController flow = ConfigureTask10Persistence(level, persistence);
        flow.HeadlessAutoStart = false;
        flow.AutomationAutoStart = false;
        CharacterBody2D player = level.GetNode<CharacterBody2D>("PlayerRoot/Player");
        KeyboardRouteInputDriver keyboardDriver=null;
        Task10NormalRangedEvidence rangedEvidence=null;
        Task10NormalOrdinaryJumpEvidence ordinaryJumps=null;
        Task10NormalKeyGateEvidence keyGates=null;
        Task10GroundSeamEvidence groundSeam=null;
        RouteMonitor monitor=null;
        Exception routeFailure=null;
        bool mounted=false;
        try
        {
            // Own each disposable from the first acquisition, including setup
            // errors; no implicit using unwind may replace the final chain.
            keyboardDriver = Array.Exists(OS.GetCmdlineUserArgs(), value=>value=="--keyboard-route")
                ? KeyboardRouteInputDriver.Begin(player) : null;
            TestAssert.Equal(new Vector2(160f, 600f), player.Position,
                "Task10 uses the authored normal spawn without a pre-tree override");
            ulong playerId = player.GetInstanceId();
            Camera2D camera = player.GetNode<Camera2D>("Camera2D");
            camera.Enabled = true;
            SeamlessPrologueWorld world = level.GetNode<SeamlessPrologueWorld>("WorldRoot/Sectors");
            // Only NORMAL owns this exercise; scoped/recovery contracts remain.
            rangedEvidence = (tree is Knight.Tests.RunRealtimePrologueProbe || headlessNormalPlan) &&
                !gearEntryWindowOnly && naturalRoute == null
                ? new Task10NormalRangedEvidence(tree, level, world, player, variant) : null;
            if (headlessNormalPlan)
            {
                ordinaryJumps = new Task10NormalOrdinaryJumpEvidence(level, flow, world, player, variant.ToString());
                keyGates = new Task10NormalKeyGateEvidence(level, flow, world, player, variant.ToString());
            }
            tree.Root.AddChild(level);
            mounted=true;
            var evidence = new Task10RouteEvidence(level, world, player);
            monitor = new RouteMonitor(level, player, camera, world, playerId,
                allowRouteBacktracking: true, additionalObservation: () =>
                {
                    evidence.Observe();
                    rangedEvidence?.AssertObserverHealthy();
                });
            if (rangedEvidence != null) monitor.CombatDecisionObserved = rangedEvidence.ObserveCombatDecision;
            await tree.ToSignal(tree, SceneTree.SignalName.ProcessFrame);
            await tree.ToSignal(tree, SceneTree.SignalName.ProcessFrame);
            TestAssert.True(flow.State == PrologueGameFlowState.Title &&
                level.GetNode<CanvasLayer>("ProductUi").Visible,
                "normal full route begins at the visible title state");
            Button start = level.GetNode<Button>("ProductUi/MainMenu/Panel/Buttons/Start");
            TestAssert.True(start.HasFocus(), "normal title gives keyboard focus to Start");
            SendUiAccept(level, pressed: true);
            await tree.ToSignal(tree, SceneTree.SignalName.ProcessFrame);
            SendUiAccept(level, pressed: false);
            for (int frame = 0; frame < 12 && flow.State != PrologueGameFlowState.Playing; frame++)
            {
                await tree.ToSignal(tree, SceneTree.SignalName.PhysicsFrame);
                await tree.ToSignal(tree, SceneTree.SignalName.ProcessFrame);
            }
            TestAssert.Equal(PrologueGameFlowState.Playing, flow.State,
                "actual ui_accept on focused Start enters normal gameplay");
            TestAssert.True(level.GetNode("PlayerRoot").GetChildCount() == 1,
                "normal Start retains exactly one Player under PlayerRoot");
            groundSeam = headlessNormalPlan &&
                !gearEntryWindowOnly && !descentHandoffOnly && !riftWallOnly && naturalRoute == null
                ? new Task10GroundSeamEvidence(level, world, player, variant.ToString()) : null;

            void ObserveTask10()
            {
                monitor.Observe();
            }
            await DriveTask10NormalRoute(tree, level, world, player, monitor, evidence,
                ObserveTask10, variant, gearEntryWindowOnly,
                persistence.ResolveWritablePath("temple-pre-boss-save.json"), naturalRoute,
                descentHandoffOnly: descentHandoffOnly, headlessNormalPlan: headlessNormalPlan, riftWallOnly: riftWallOnly);
            if (riftWallOnly)
            {
                return new PrologueContinuousRouteResult
                {
                    Variant = "RiftWallDiagnostic", StartedFromTitle = true,
                    PersistentPlayer = player.GetInstanceId() == playerId && player.GetParent()?.Name == "PlayerRoot",
                    PlayerInstanceId = player.GetInstanceId(),
                    RecoveryRequests = monitor.RecoveryRequested,
                    RecoveryCompletions = monitor.RecoveryCompleted
                };
            }
            if (descentHandoffOnly)
            {
                TestAssert.True(monitor.RecoveryRequested == 0 && monitor.RecoveryCompleted == 0 &&
                    player.GetNode<HealthComponent>("Health").CurrentHealth == 5,
                    "scoped descent never substitutes recovery, death or healing for its original route");
                return new PrologueContinuousRouteResult
                {
                    Variant = "DescentHandoffDiagnostic", StartedFromTitle = true,
                    PersistentPlayer = player.GetInstanceId() == playerId &&
                        player.GetParent()?.Name == "PlayerRoot"
                };
            }
            if (gearEntryWindowOnly)
            {
                GD.Print($"TASK10_GEAR_ENTRY_WINDOW_OK request=" +
                    $"{Task10GearEntryLaunchRequest(required: true):0} " +
                    $"player={player.GlobalPosition} recoveries={monitor.RecoveryCompleted}");
                return new PrologueContinuousRouteResult
                {
                    Variant = "GearEntryWindow",
                    StartedFromTitle = true,
                    PersistentPlayer = player.GetInstanceId() == playerId &&
                        player.GetParent()?.Name == "PlayerRoot"
                };
            }
            monitor.AssertComplete();
            keyboardDriver?.AssertComplete();
            rangedEvidence?.AssertComplete(monitor.RecoveryRequested, monitor.RecoveryCompleted);
            ordinaryJumps?.AssertComplete(evidence.TerminalProof?.CompletionPhysics ?? 0UL);
            keyGates?.AssertComplete(evidence.TerminalProof?.CompletionPhysics ?? 0UL);
            groundSeam?.AssertComplete();
            return new PrologueContinuousRouteResult
            {
                Variant = variant.ToString(),
                StartedFromTitle = true,
                PersistentPlayer = player.GetInstanceId() == playerId &&
                    player.GetParent()?.Name == "PlayerRoot",
                PlayerInstanceId = playerId,
                TerminalProof = evidence.TerminalProof,
                RouteNodes = evidence.RouteNodes,
                ChallengeKinds = evidence.ChallengeKinds,
                EncounterActivations = evidence.EncounterActivations,
                EncounterDefeats = evidence.EncounterDefeats,
                MechanismsActivated = evidence.MechanismsActivated,
                ShortcutDirections = evidence.ShortcutDirections,
                CheckpointsActivated = evidence.CheckpointsActivated,
                BossDefeated = level.Progress.BossDefeated,
                SafeExitReached = CanyonWorldLayout.Nodes.Single(node =>
                    node.Id == CanyonRouteNodeId.SafeExit).WorldBounds.HasPoint(player.GlobalPosition),
                FlowState = flow.State,
                RecoveryRequests = monitor.RecoveryRequested,
                RecoveryCompletions = monitor.RecoveryCompleted,
                NormalRangedExerciseRequired = rangedEvidence != null,
                NormalRangedInstances = rangedEvidence?.Snapshot() ?? Array.Empty<Task10NormalRangedInstance>()
            };
        }
        catch(Exception error)
        {
            routeFailure=error; ordinaryJumps?.ReportFailure(); keyGates?.ReportFailure(); throw;
        }
        finally
        {
            await Task10FinalizeRoute(routeFailure,new Func<Task>[]
            {
                ()=>{groundSeam?.Dispose();return Task.CompletedTask;},
                ()=>{monitor?.Dispose();return Task.CompletedTask;},
                ()=>{rangedEvidence?.Dispose();return Task.CompletedTask;},
                ()=>{ordinaryJumps?.Dispose();return Task.CompletedTask;},
                ()=>{keyGates?.Dispose();return Task.CompletedTask;},
                ()=>{ReleaseAll(player.GlobalPosition);return Task.CompletedTask;},
                async()=>
                {
                    if (!mounted) return; // No new off-tree native release/fallback.
                    await TestSceneTeardown.FreeSceneAfterAudioDrain(tree,level);
                    await tree.ToSignal(tree,SceneTree.SignalName.PhysicsFrame);
                },
                ()=>{persistence.AssertProtectedDefaultsUnchanged();return Task.CompletedTask;},
                ()=>{keyboardDriver?.Dispose();return Task.CompletedTask;}
            });
        }
    }

    internal static async Task Task10FinalizeRoute(Exception primary,IReadOnlyList<Func<Task>> cleanupSteps)
    {
        var failures=new List<Exception>();
        if (primary!=null) failures.Add(primary);
        if (cleanupSteps==null) failures.Add(new ArgumentNullException(nameof(cleanupSteps)));
        else foreach (var cleanup in cleanupSteps)
        {
            try { await cleanup(); }
            catch(Exception error) { failures.Add(error); }
        }
        if (failures.Count==1)
            System.Runtime.ExceptionServices.ExceptionDispatchInfo.Capture(failures[0]).Throw();
        if (failures.Count>1)
            throw new AggregateException("Task10 route/finalization failed; primary then ordered cleanup failures",failures);
    }

    private static float Task10GearEntryLaunchRequest(bool required)
    {
        string argument = Array.Find(OS.GetCmdlineUserArgs(), value =>
            value.StartsWith("--gear-entry-launch=", StringComparison.Ordinal));
        if (argument == null)
        {
            TestAssert.True(!required,
                "focused GearEntry window proof requires launch2335,2350 or2360");
            return 2350f;
        }
        return argument switch
        {
            "--gear-entry-launch=2335" => 2335f,
            "--gear-entry-launch=2350" => 2350f,
            "--gear-entry-launch=2360" => 2360f,
            _ => throw new InvalidOperationException(
                $"unsupported Task10 GearEntry launch request {argument}")
        };
    }

    private static async Task DriveTask10NormalRoute(SceneTree tree,
        PrologueLevelController level, SeamlessPrologueWorld world, CharacterBody2D player,
        RouteMonitor monitor, Task10RouteEvidence evidence, Action observe,
        Task10RouteVariant variant, bool gearEntryWindowOnly, string templeCheckpointSnapshotPath,
        NaturalFragmentRouteContext naturalRoute = null, bool fragmentReturnFromCamp = false,
        Func<Task> atNaturalDeathCheckpoint = null, bool descentHandoffOnly = false,
        bool headlessNormalPlan = false, bool riftWallOnly = false)
    {
        PrologueSector Sector(PrologueSectorId id) => world.TryGetMountedSector(id, out var sector)
            ? sector
            : throw new InvalidOperationException($"Task10 required mounted sector {id}; " +
                $"current={world.CurrentSector} mounted={string.Join(',', world.MountedSectorIds)}");
        StaticBody2D Body(PrologueSectorId id, string name) =>
            Sector(id).GetNode<StaticBody2D>("Gameplay/Collision/" + name);

        Task10AscentGrip1Diagnostic ascentDiagnostic = null;
        Task10LandingGuard landingGuard = null;
        Task10PendulumEntryDiagnostic pendulumDiagnostic = null;
        Action grip9ControlApproachGuard = null;
        Action SwapGrip9ControlApproachGuard(Action guard)
        {
            Action previous = grip9ControlApproachGuard;
            grip9ControlApproachGuard = guard;
            return previous;
        }
        Action templeEntryPreObserverGuard = null;
        Action SwapTempleEntryPreObserverGuard(Action guard)
        {
            Action previous = templeEntryPreObserverGuard;
            templeEntryPreObserverGuard = guard;
            return previous;
        }
        // Keep the original observer and input-drive initialization exactly once. In particular,
        // BeginTask10InputDrive releases input, so it must not be used to install this scope.
        void ObserveWithAscentDiagnostic()
        {
            templeEntryPreObserverGuard?.Invoke();
            observe();
            ascentDiagnostic?.ObserveDriver();
            landingGuard?.Refresh();
            pendulumDiagnostic?.ObserveDriver();
            grip9ControlApproachGuard?.Invoke();
        }
        PrologueCanyonTraversalTests.BeginTask10InputDrive(tree, player,
            ObserveWithAscentDiagnostic);
        try
        {
            if (!fragmentReturnFromCamp)
            {
            await WaitForFloor(tree, monitor, 180);
            evidence.Observe();
            await PrologueCanyonTraversalTests.Task10EntrancePlateApproach(tree,player,
                Sector(PrologueSectorId.CanyonEntrance).GetNode<CanyonSpringboard>("Gameplay/Mechanisms/CombinationSpringboard"),80);
            await PrologueCanyonTraversalTests.Task4CrossEntranceGap(tree, player,
                Body(PrologueSectorId.CanyonEntrance, "BridgeFarBank"));
            await PrologueCanyonTraversalTests.Task4WalkTo(tree, player, 520f, 80);
            TestAssert.True(HasFloorContact(player, Body(PrologueSectorId.CanyonEntrance, "BridgeFarBank")),
                "normal route begins its first real encounter on the supported horizontal bank");
            await DefeatTask10Encounter(tree, level, world, player, monitor,
                "canyon.v2.encounter.low-ceiling-bridge");
            // Previously the seven stair hops already carried the actor near1200.
            // Now this is an~886px supported walk from the first battle (~475):
            // 60*886/260≈205 ticks, plus bounded acceleration/settling margin.
            await PrologueCanyonTraversalTests.Task4WalkTo(tree, player, 1360f, 230);
            await PrologueCanyonTraversalTests.Task4WaitSupport(tree, player,
                Sector(PrologueSectorId.CanyonDescent), "RiftUpperFloor");
            await DefeatTask10Encounter(tree, level, world, player, monitor,
                "canyon.v2.encounter.staggered-rift");
            await PrologueCanyonTraversalTests.Task4WalkTo(tree, player, 1940f, 180);
            StaticBody2D middleRiftCatch = Body(PrologueSectorId.CanyonDescent, "RiftMiddleCatch");
            await WaitForStoppedRiftCatch(tree, player, monitor, middleRiftCatch);
            if (riftWallOnly)
            {
                await VerifyRiftAlternationWall(tree, level, player, monitor, middleRiftCatch);
                return;
            }
            await PrologueCanyonTraversalTests.Task4WalkTo(tree, player, 1460f, 180);
            await WaitForStoppedRiftCatch(tree, player, monitor,
                Body(PrologueSectorId.CanyonDescent, "RiftLowerCatch"));
            if (descentHandoffOnly)
            {
                StaticBody2D lower = Body(PrologueSectorId.CanyonDescent, "RiftLowerCatch");
                TestAssert.True(HasFloorContact(player, lower) &&
                    TryTask10CapsuleCorridor(player, lower.GetNode<CollisionShape2D>("Collision"),
                        out _, out _, out _, out _),
                    $"descent handoff retains the full capsule on RiftLowerCatch before choosing a route; " +
                    $"player={player.GlobalPosition} velocity={player.Velocity} floor={DescribeFloorCollider(player)}");
                GD.Print($"THRUSTER_RIFT_HANDOFF_OK player={player.GlobalPosition} velocity={player.Velocity} full_support=true");
            }

            if (variant == Task10RouteVariant.Main)
            {
                await TraverseTask10ControlledAbyss(tree, level, world, player, monitor,
                    Body(PrologueSectorId.CanyonDescent, "AbyssCommitment"),
                    Body(PrologueSectorId.CanyonDescent, "AbyssSafeBottom"),
                    stopAfterLanding: descentHandoffOnly);
                if (descentHandoffOnly) return;
            }
            else
            {
                await DropFromSupportToLowerShelf(tree, player, monitor,
                    Body(PrologueSectorId.CanyonDescent, "RiftLowerCatch"),
                    Body(PrologueSectorId.CanyonDescent, "ArchiveEntry"));
                await PrologueCanyonTraversalTests.Task4ReachSupport(tree, player,
                    Body(PrologueSectorId.CanyonDescent, "ArchiveShelf"), clawRequired: false);
                await DropFromSupportToLowerShelf(tree, player, monitor,
                    Body(PrologueSectorId.CanyonDescent, "ArchiveShelf"),
                    Body(PrologueSectorId.CanyonDescent, "ArchiveFloor"));
                if (descentHandoffOnly) return;
                await DefeatTask10Encounter(tree, level, world, player, monitor,
                    "canyon.v2.encounter.archive-side-cave");
                await TraverseArchiveFloorToFrozenLeft(tree, player, monitor,
                    Body(PrologueSectorId.CanyonDescent, "ArchiveFloor"),
                    Body(PrologueSectorId.CanyonDescent, "FrozenCeiling"),
                    Body(PrologueSectorId.CanyonDescent, "FrozenLeftCatch"));
                await DefeatTask10Encounter(tree, level, world, player, monitor,
                    "canyon.v2.encounter.frozen-upper");
                await ObserveFrozenRightDrop(tree, player, monitor,
                    Sector(PrologueSectorId.CanyonDescent),
                    Body(PrologueSectorId.CanyonDescent, "FrozenRightCatch"));
                await DropFromSupportToLowerShelf(tree, player, monitor,
                    Body(PrologueSectorId.CanyonDescent, "FrozenRightCatch"),
                    Body(PrologueSectorId.CanyonDescent, "FrozenExit"));
                // Enter the same real activation bounds without the legacy route's
                // extra close approach inside Rust's forward attack-origin offset.
                await PrologueCanyonTraversalTests.Task4WalkTo(tree, player,
                    KeyboardRouteInputDriver.Current != null ? 1518f : 1500f, 40);
                await DefeatTask10Encounter(tree, level, world, player, monitor,
                    "canyon.v2.encounter.frozen-lower");
                await DropRightFromSupportToBasin(tree, player, monitor,
                    Body(PrologueSectorId.CanyonDescent, "FrozenExit"),
                    KeyboardRouteInputDriver.Current != null
                        ? Body(PrologueSectorId.CanyonBasin, "BasinCampFloor") : null);
            }

            await PrologueCanyonTraversalTests.Task4WalkTo(tree, player, 1860f, 140);
            await PrologueCanyonTraversalTests.Task4WaitSupport(tree, player,
                Sector(PrologueSectorId.CanyonBasin), "BasinCampFloor");
            if (!gearEntryWindowOnly)
            {
                int campHealth = player.GetNode<HealthComponent>("Health").CurrentHealth;
                int campRecoveries = monitor.RecoveryCompleted;
                await PrologueCanyonTraversalTests.Task4WalkTo(tree, player, 1680f, 100);
                CheckpointTrigger campTrigger = Sector(PrologueSectorId.CanyonBasin)
                    .GetNode<CheckpointTrigger>("Gameplay/BasinCheckpoint");
                for (int frame = 0; frame < 12 &&
                     !level.Progress.RestoreCheckpoint().HasActivatedCheckpoint; frame++)
                    await PhysicsFrames(tree, monitor, 1);
                PrologueCheckpointSnapshot campCheckpoint = level.Progress.RestoreCheckpoint();
                TestAssert.True(campCheckpoint.HasActivatedCheckpoint &&
                    campCheckpoint.CheckpointId == "canyon.v2.basin-camp" &&
                    campCheckpoint.SectorId == PrologueSectorId.CanyonBasin &&
                    campCheckpoint.WorldPosition == new Vector2(1680f, 3960f),
                    "Task10 normal route physically activates the basin checkpoint before the gear lane");
                TestAssert.True(world.CheckpointId == "canyon.v2.basin-camp" &&
                    world.CurrentSector == PrologueSectorId.CanyonBasin &&
                    campTrigger.GetOverlappingBodies().Contains(player) &&
                    HasFloorContact(player, Body(PrologueSectorId.CanyonBasin, "BasinCampFloor")),
                    "basin checkpoint proof requires actual trigger overlap and supported camp contact");
                PrologueGameFlowController campFlow = level.GetNode<PrologueGameFlowController>("GameFlow");
                TestAssert.True(campFlow.Save.HasActivatedCheckpoint &&
                    campFlow.Save.CheckpointId == "canyon.v2.basin-camp" &&
                    campFlow.Save.CheckpointSector == "CanyonBasin" &&
                    campFlow.Save.CheckpointWorldPosition == new Vector2(1680f, 3960f),
                    "normal checkpoint signal updates the live save without test persistence calls");
                using (System.Text.Json.JsonDocument savedCamp =
                       System.Text.Json.JsonDocument.Parse(File.ReadAllText(campFlow.SavePath)))
                {
                    System.Text.Json.JsonElement saved = savedCamp.RootElement;
                    TestAssert.True(saved.GetProperty("version").GetInt32() == PrologueSaveData.CurrentVersion &&
                        saved.GetProperty("layoutVersion").GetInt32() == 2 &&
                        saved.GetProperty("hasActivatedCheckpoint").GetBoolean() &&
                        saved.GetProperty("checkpointId").GetString() == "canyon.v2.basin-camp" &&
                        saved.GetProperty("checkpointSector").GetString() == "CanyonBasin" &&
                        saved.GetProperty("checkpointWorldX").GetSingle() == 1680f &&
                        saved.GetProperty("checkpointWorldY").GetSingle() == 3960f,
                        "basin checkpoint is persisted in the actual isolated save file");
                }
                TestAssert.True(campHealth > 0 &&
                    player.GetNode<HealthComponent>("Health").CurrentHealth == campHealth &&
                    monitor.RecoveryCompleted == campRecoveries,
                    "checkpoint activation neither heals nor hides a recovery");
                GD.Print($"TASK10_BASIN_CHECKPOINT_OK player={player.GlobalPosition} " +
                    $"checkpoint={campCheckpoint.CheckpointId} health={campHealth} " +
                    $"recovery={campRecoveries} actual_overlap=True disk_saved=True");
                // Dedicated death proof reuses the unchanged Title-to-camp route and
                // stops here. Ordinary full-route callers never enter this branch.
                if (atNaturalDeathCheckpoint != null)
                {
                    await atNaturalDeathCheckpoint();
                    return;
                }
                await PrologueCanyonTraversalTests.Task4WalkTo(tree, player, 1860f, 100);
            }
            }
            else
            {
                TestAssert.True(variant == Task10RouteVariant.Exploration && naturalRoute == null &&
                    !gearEntryWindowOnly && KeyboardRouteInputDriver.Current != null &&
                    HasFloorContact(player, Body(PrologueSectorId.CanyonBasin, "BasinCampFloor")),
                    "regional continuation starts only from the same keyboard player's actual camp support");
                observe();
            }
            await PrologueCanyonTraversalTests.Task4WalkTo(tree, player, 1940f, 60);
            await PrologueCanyonTraversalTests.Task4WalkTo(tree, player, 2090f, 60);
            StaticBody2D gearEntry = Body(PrologueSectorId.CanyonBasin, "GearEntry");
            CanyonShieldLaneHazard shieldLane = Sector(PrologueSectorId.CanyonBasin)
                .GetNode<CanyonShieldLaneHazard>("Gameplay/ShieldLane");
            HealthComponent routeHealth = player.GetNode<HealthComponent>("Health");
            PlayerShieldController routeShield = player.GetNode<PlayerShieldController>("Shield");
            float gearEntryLaunch = Task10GearEntryLaunchRequest(gearEntryWindowOnly);
            int shieldLaneHealth = routeHealth.CurrentHealth;
            int shieldLanePulses = shieldLane.PulseCount;
            List<string> shieldLaneGuardEvents = new();
            List<string> shieldLaneDamageEvents = new();
            Action<PlayerShieldResult, ulong> shieldResolved = (result, transition) =>
                shieldLaneGuardEvents.Add($"physics={Engine.GetPhysicsFrames()} transition={transition} " +
                    $"guarded={result.Guarded} damage={result.DamageAmount} " +
                    $"pulses={shieldLane.PulseCount} player={player.GlobalPosition} " +
                    $"direction={routeShield.GuardDirection} " +
                    $"overlap={shieldLane.GetOverlappingBodies().Contains(player)}");
            HealthComponent.DamagedEventHandler laneDamaged = (remaining, impulse) =>
                shieldLaneDamageEvents.Add(
                $"physics={Engine.GetPhysicsFrames()} remaining={remaining} " +
                $"pulses={shieldLane.PulseCount} player={player.GlobalPosition} " +
                $"direction={routeShield.GuardDirection} active={routeShield.IsActive} " +
                $"overlap={shieldLane.GetOverlappingBodies().Contains(player)} impulse={impulse}");
            routeShield.ShieldResolved += shieldResolved;
            routeHealth.Damaged += laneDamaged;
            try
            {
                var shieldObservation = new Task24ShieldLaneObservation(tree, level, player,
                    routeShield, routeHealth, gearEntry,
                    () => monitor.RecoveryRequested, () => monitor.RecoveryCompleted);
                try
                {
                    shieldObservation.Begin();
                    SendMouse(MouseButton.Right, true, player,
                        player.GlobalPosition + Vector2.Right * 240f);
                    shieldObservation.Record("raise_issued");
                    await PhysicsFrames(tree, monitor, 3);
                    TestAssert.True(routeShield.IsActive,
                        "Task10 raises the real right-facing shield before entering the basin pulse lane");
                    await PrologueCanyonTraversalTests.Task4WalkTo(tree, player,
                        gearEntryLaunch, 120);
                    TestAssert.True(HasFloorContact(player, gearEntry),
                        $"Task10 walks across the continuous camp floor onto GearEntry under shield; " +
                        $"player={player.GlobalPosition}");
                }
                finally
                {
                    shieldObservation.End();
                }
                await ShieldJumpToSupport(tree, player, monitor, shieldLane,
                    Body(PrologueSectorId.CanyonBasin, "GearPistonOne"));
                SendMouse(MouseButton.Right, false, player,
                    player.GlobalPosition + Vector2.Right * 240f);
            }
            finally
            {
                routeShield.ShieldResolved -= shieldResolved;
                routeHealth.Damaged -= laneDamaged;
                GD.Print($"TASK10_SHIELD_LANE_RESULT pulses={shieldLanePulses}->" +
                    $"{shieldLane.PulseCount} health={shieldLaneHealth}->{routeHealth.CurrentHealth} " +
                    $"guard_events=[{string.Join(";", shieldLaneGuardEvents)}] " +
                    $"damage_events=[{string.Join(";", shieldLaneDamageEvents)}] " +
                    $"player={player.GlobalPosition} direction={routeShield.GuardDirection} " +
                    $"active={routeShield.IsActive} " +
                    $"overlap={shieldLane.GetOverlappingBodies().Contains(player)}");
            }
            TestAssert.True(shieldLane.PulseCount > shieldLanePulses &&
                            routeHealth.CurrentHealth == shieldLaneHealth &&
                            shieldLaneGuardEvents.Count > 0 &&
                            shieldLaneGuardEvents.All(value => value.Contains("guarded=True")),
                "real shield input blocks the basin lane while the capsule advances to PistonOne");
            AssertTask10GearPistonOneContract(Sector(PrologueSectorId.CanyonBasin));
            if (gearEntryWindowOnly)
            {
                if (KeyboardRouteInputDriver.Current != null)
                {
                    int before = monitor.RecoveryCompleted;
                    await BasinCounterweightRuntimeTests.TraverseForFullRoute(player,
                        Sector(PrologueSectorId.CanyonBasin), count => PhysicsFrames(tree,monitor,count));
                    TestAssert.Equal(before,monitor.RecoveryCompleted,"keyboard gear window does not recover across lift route");
                    return;
                }
                PlayerMotor windowMotor = player.GetNode<PlayerMotor>("Motor");
                MechanicalClawController windowClaw =
                    player.GetNode<MechanicalClawController>("MechanicalClaw");
                int jumpsBeforeSecond = windowMotor.AcceptedJumpCount;
                int dashesBeforeSecond = windowMotor.AcceptedDashCount;
                ulong castBeforeSecond = windowClaw.CurrentFrame.CastId;
                int recoveriesBeforeSecond = monitor.RecoveryCompleted;
                StaticBody2D pistonTwo = Body(PrologueSectorId.CanyonBasin,
                    "GearPistonTwo");
                await PrologueCanyonTraversalTests.Task4ReachSupport(tree, player,
                    pistonTwo, clawRequired: false);
                TestAssert.True(windowMotor.AcceptedJumpCount == jumpsBeforeSecond + 1 &&
                                windowMotor.AcceptedDashCount == dashesBeforeSecond &&
                                windowClaw.CurrentFrame.CastId == castBeforeSecond &&
                                monitor.RecoveryCompleted == recoveriesBeforeSecond &&
                                HasFloorContact(player, pistonTwo),
                    $"Task10 GearEntry window continues across the unchanged80px gap to " +
                    $"PistonTwo by one ordinary jump; request={gearEntryLaunch:0} " +
                    $"player={player.GlobalPosition} jumps={jumpsBeforeSecond}->" +
                    $"{windowMotor.AcceptedJumpCount} dashes={dashesBeforeSecond}->" +
                    $"{windowMotor.AcceptedDashCount} cast={castBeforeSecond}->" +
                    $"{windowClaw.CurrentFrame.CastId} recoveries={recoveriesBeforeSecond}->" +
                    $"{monitor.RecoveryCompleted}");
                GD.Print($"TASK10_GEAR_ENTRY_NEXT_SUPPORT_OK request={gearEntryLaunch:0} " +
                    $"player={player.GlobalPosition} jumps={jumpsBeforeSecond}->" +
                    $"{windowMotor.AcceptedJumpCount} dashes={windowMotor.AcceptedDashCount} " +
                    $"cast={windowClaw.CurrentFrame.CastId} recoveries=" +
                    $"{monitor.RecoveryCompleted}");
                return;
            }
            Task10GearHandoff gearHandoff = Task10GearHandoff.None;
            if (!fragmentReturnFromCamp)
                gearHandoff = await DefeatTask10GearSafeEncounter(tree, level, world, player, monitor,
                    gearEntry, Body(PrologueSectorId.CanyonBasin, "GearPistonOne"),
                    Body(PrologueSectorId.CanyonBasin, "GearPistonTwo"), shieldLane,
                    finishOnGallery: variant == Task10RouteVariant.Main &&
                        KeyboardRouteInputDriver.Current != null,
                    useResidentCounter: variant == Task10RouteVariant.Exploration);
            else if (KeyboardRouteInputDriver.Current != null)
                await BasinCounterweightRuntimeTests.TraverseForFullRoute(player,
                    Sector(PrologueSectorId.CanyonBasin), count => PhysicsFrames(tree,monitor,count));
            if ((fragmentReturnFromCamp || gearHandoff == Task10GearHandoff.PistonTwo) && KeyboardRouteInputDriver.Current != null)
                TestAssert.True(HasFloorContact(player,Body(PrologueSectorId.CanyonBasin,"GearPistonTwo")),
                    "keyboard return uses the lift's established PistonTwo support without an extra jump");
            else if (gearHandoff == Task10GearHandoff.Gallery)
                TestAssert.True(HasFloorContact(player,Body(PrologueSectorId.CanyonBasin,"UpperGearGalleryOne")) &&
                    player.GlobalPosition.X is >= 3060f and <= 3260f && player.Velocity.Length() <= 2f,
                    "post-Bell Gallery terminal is the actual current fully supported neutral player, not a prior visit");
            else await PrologueCanyonTraversalTests.Task4ReachSupport(tree, player,
                Body(PrologueSectorId.CanyonBasin, "GearPistonTwo"), clawRequired: false);

            if (fragmentReturnFromCamp)
            {
                await PrologueCanyonTraversalTests.Task4ReachSupport(tree, player,
                    Body(PrologueSectorId.CanyonBasin, "UpperGearGalleryOne"), clawRequired: false);
                await PrologueCanyonTraversalTests.Task4WalkTo(tree, player, 3160f, 100);
                await PrologueCanyonTraversalTests.Task4ReachSupport(tree, player,
                    Body(PrologueSectorId.CanyonBasin, "GearPistonTwo"), clawRequired: false);
            }
            if (variant == Task10RouteVariant.Main)
            {
                if (naturalRoute == null)
                {
                    foreach (string name in new[]
