                    ascentTransferStart = Engine.GetPhysicsFrames();
                    ascentClaw = player.GetNode<MechanicalClawController>("MechanicalClaw");
                    var ascentHealth = player.GetNode<HealthComponent>("Health");
                    var ascentMotor = player.GetNode<PlayerMotor>("Motor");
                    ulong ascentPlayerId = player.GetInstanceId();
                    ascentNextCast = ascentClaw.CurrentFrame.NextCastId;
                    int ascentHp = ascentHealth.CurrentHealth, ascentRequests = monitor.RecoveryRequested,
                        ascentRecoveries = monitor.RecoveryCompleted, ascentJumps = ascentMotor.AcceptedJumpCount,
                        ascentDashes = ascentMotor.AcceptedDashCount;
                    ascentExpectedJumps = ascentJumps + (index == 2 ? 1 : 0);
                    ascentTransferGuard = () => TestAssert.True(
                        Engine.GetPhysicsFrames() - ascentTransferStart <= 300UL &&
                        GodotObject.IsInstanceValid(player) && level.Player == player && monitor.Player == player &&
                        player.GetInstanceId() == ascentPlayerId && player.GlobalPosition.IsFinite() && player.Velocity.IsFinite() &&
                        ascentHealth.CurrentHealth == ascentHp && ascentHp > 0 &&
                        monitor.RecoveryRequested == ascentRequests && monitor.RecoveryCompleted == ascentRecoveries &&
                        (ascentMotor.AcceptedJumpCount == ascentJumps || index == 2 && ascentGroundJumpArmed &&
                            ascentMotor.AcceptedJumpCount == ascentJumps + 1) && ascentMotor.AcceptedDashCount == ascentDashes &&
                        ascentClaw.CurrentFrame.NextCastId >= ascentNextCast &&
                        ascentClaw.CurrentFrame.NextCastId <= ascentNextCast + 1UL,
                        $"Task10 Explore {ascentSupport.Name} preparation/transfer/tail share300 with unchanged player/HP/recovery/dash, only Grip2's explicitly armed ground jump, and at most one cast; " +
                        $"physics={Engine.GetPhysicsFrames() - ascentTransferStart}/300 " +
                        $"hp={ascentHp}->{ascentHealth.CurrentHealth} requests={ascentRequests}->{monitor.RecoveryRequested} " +
                        $"recoveries={ascentRecoveries}->{monitor.RecoveryCompleted} jumps={ascentJumps}->{ascentMotor.AcceptedJumpCount} " +
                        $"dashes={ascentDashes}->{ascentMotor.AcceptedDashCount} next_cast={ascentNextCast}->{ascentClaw.CurrentFrame.NextCastId} " +
                        (fragmentReturnFromCamp ? FragmentSixLatestAttackFact(player) : string.Empty));
                    previousAscentTransferGuard = SwapTempleEntryPreObserverGuard(ascentTransferGuard);
                }
                try
