                            ascent.GetNode<Node>("Gameplay/Actors"), ascentSupport,
                            Body(PrologueSectorId.CanyonAscent, $"AscentGrip{index}Grip")
                                .GetNode<GrappleSurface2D>("GrappleSurfaceProfile"), phase: $"ascent-grip{index}");
                    ascentTransferGuard?.Invoke();
                    if (variant == Task10RouteVariant.Exploration && index == 2 &&
                        KeyboardRouteInputDriver.Current != null)
                        await ReachTask10KeyboardAscentGrip2(tree, player, monitor,
                            ObserveWithAscentDiagnostic, SwapGrip9ControlApproachGuard,
                            Body(PrologueSectorId.CanyonAscent, "AscentGrip1"), ascentSupport, () =>
                            {
                                ascentTransferGuard();
                                TestAssert.True(!ascentGroundJumpArmed,
                                    "only the full-support Grip2 helper may arm its one grounded Space once");
                                ascentGroundJumpArmed = true;
                            });
                    else
                        await PrologueCanyonTraversalTests.Task4ReachSupport(tree, player,
                            ascentSupport, clawRequired: true);
                    ascentTransferGuard?.Invoke();
                    if (ascentTransferGuard != null)
                    {
                        TestAssert.Equal(ascentExpectedJumps,
                            player.GetNode<PlayerMotor>("Motor").AcceptedJumpCount,
                            "only Grip2 completes exactly one armed ordinary ground jump; every other ascent adds zero jumps");
                        TestAssert.Equal(ascentNextCast + 1UL, ascentClaw.CurrentFrame.NextCastId,
                            "Task10 Explore original above-post transfer admits exactly one cast, including preparation and tail");
                        GD.Print($"TASK10_EXPLORE_ASCENT_SHARED_BUDGET_OK support={ascentSupport.Name} " +
                            $"physics={Engine.GetPhysicsFrames() - ascentTransferStart}/300 next_cast={ascentNextCast}->{ascentClaw.CurrentFrame.NextCastId}");
                    }
                }
                finally
                {
                    landingGuard?.Dispose();
                    if (ascentTransferGuard != null) SwapTempleEntryPreObserverGuard(previousAscentTransferGuard);
                }
                if (landingGuard != null)
                {
                    TestAssert.True(landingGuard.Fault == null && landingGuard.Started && landingGuard.Landed,
                        $"Grip{index} landing guard requires actual matching release and original full floor; fault={landingGuard.Fault}");
                    landingGuard = null;
                }
                if (mainGrip8LandingProbe)
                {
                    int hp = player.GetNode<HealthComponent>("Health").CurrentHealth;
                    TestAssert.True(mainGrip8EntryHp > 0 && hp == mainGrip8EntryHp,
                        $"Main Grip8 real landing guard preserves HP through original floor: {mainGrip8EntryHp}->{hp}");
                    GD.Print($"TASK10_MAIN_GRIP8_GUARD_HP_OK hp={mainGrip8EntryHp}->{hp} physics={Engine.GetPhysicsFrames()} test_only=true");
                }
#if CLAW_OBSTRUCTION_IDENTITY
                if (index == 8 && variant == Task10RouteVariant.Exploration &&
                    KeyboardRouteInputDriver.Current != null)
                    ObserveTask10Grip8CombatInventory(world, player, ascentSupport);
#endif
                if (Task10Grip8GhostClearanceRoute(KeyboardRouteInputDriver.Current != null,
                    variant == Task10RouteVariant.Main, variant == Task10RouteVariant.Exploration, index))
                    await ClearTask10Grip8Ghost(tree,level,world,player,monitor,ascentSupport,
                        ObserveWithAscentDiagnostic,SwapTempleEntryPreObserverGuard);
                if (index == 1)
                {
                    ascentDiagnostic?.Boundary("ascent-grip1", "Task4ReachSupport-return");
                    ascentDiagnostic?.Dispose();
                    ascentDiagnostic = null; // Original observer resumes; Grip2 owns its scoped launch guard.
                }
                if (index == 5)
                {
                    pendulumDiagnostic = new Task10PendulumEntryDiagnostic(tree, player, monitor,
                        world, Body(PrologueSectorId.CanyonAscent, "AscentGrip5"), variant);
                    try
                    {
                        await DefeatTask10Encounter(tree, level, world, player, monitor,
                            "canyon.v2.encounter.pendulum-gallery", headlessNormalPlan);
                        pendulumDiagnostic.Boundary("original-return");
                    }
                    catch (Exception error)
                    {
                        pendulumDiagnostic.Failure(error);
                        throw;
                    }
                    finally
                    {
                        pendulumDiagnostic.Dispose();
                        pendulumDiagnostic = null;
                    }
                }
                if (index == 9 && !fragmentReturnFromCamp)
                {
                    var gallery = Body(PrologueSectorId.CanyonAscent, "SplitUpperGallery");
                    await PrologueCanyonTraversalTests.Task4ReachSupport(tree, player,
                        gallery, clawRequired: false);
                    await DefeatTask10Encounter(tree, level, world, player, monitor,
                        "canyon.v2.encounter.split-level");
                    if (variant == Task10RouteVariant.Main && KeyboardRouteInputDriver.Current != null &&
                        OS.GetEnvironment("KNIGHT_MAIN_GALLERY_RETURN_PROBE") == "1" && !HasFloorContact(player, gallery))
                    {
                        var barrier = ascent.GetNode<StaticBody2D>("Gameplay/Mechanisms/UpperBasinShortcutWinch/Barrier");
                        var motor = player.GetNode<PlayerMotor>("Motor");
                        var health = player.GetNode<HealthComponent>("Health");
                        var claw = player.GetNode<MechanicalClawController>("MechanicalClaw");
                        var galleryFloor = gallery.GetNode<CollisionShape2D>("Collision");
                        var jumps = motor.AcceptedJumpCount;
                        var dashes = motor.AcceptedDashCount;
                        var cast = claw.CurrentFrame.NextCastId;
                        int hp = health.CurrentHealth, requested = monitor.RecoveryRequested, recovered = monitor.RecoveryCompleted;
                        ulong start = Engine.GetPhysicsFrames();
                        TestAssert.True(player.IsOnFloor() && HasFloorContact(player, barrier),
                            "Main Gallery return starts only on the real postcombat Barrier support");
                        GD.Print($"TASK10_MAIN_GALLERY_RETURN_BEGIN physics={start} position={player.GlobalPosition} jumps={jumps}");
                        await PrologueCanyonTraversalTests.Task4ReachSupport(tree, player, gallery, clawRequired: false);
                        TestAssert.True(player.IsOnFloor() && HasFloorContact(player, gallery) &&
                            TryTask10CapsuleCorridor(player, galleryFloor, out float left, out float right,
                                out float floorLeft, out float floorRight) && left >= floorLeft && right <= floorRight &&
                            motor.AcceptedJumpCount == jumps + 1 && motor.AcceptedDashCount == dashes &&
                            claw.CurrentFrame.NextCastId == cast && health.CurrentHealth == hp &&
                            monitor.RecoveryRequested == requested && monitor.RecoveryCompleted == recovered,
                            "Main postcombat return uses exactly one ordinary jump, no cast/dash/HP loss/recovery, and full original Gallery support");
                        GD.Print($"TASK10_MAIN_GALLERY_RETURN_OK physics={Engine.GetPhysicsFrames()} elapsed={Engine.GetPhysicsFrames()-start} " +
                            $"position={player.GlobalPosition} jumps={jumps}->{motor.AcceptedJumpCount} hp={hp}->{health.CurrentHealth}");
                    }
                }
            }

            if (variant == Task10RouteVariant.Exploration && !fragmentReturnFromCamp)
                await TraverseTask10ShortcutBothDirections(tree, player, monitor, ascent,
                    Sector(PrologueSectorId.CanyonBasin), level, ObserveWithAscentDiagnostic,
                    SwapGrip9ControlApproachGuard);

            CanyonSteamValve linkage = ascent.GetNode<CanyonSteamValve>(
                "Gameplay/Mechanisms/CourtyardSealLinkage");
            GrappleSurface2D linkageControl = ascent.GetNode<GrappleSurface2D>(
                "Gameplay/GrappleSurfaces/CourtyardSealLinkageControl");
            bool keyboardLinkageRoute = KeyboardRouteInputDriver.Current != null &&
                linkageControl == ascent.GetNode<GrappleSurface2D>(
                    "Gameplay/GrappleSurfaces/CourtyardSealLinkageControl");
            if (fragmentReturnFromCamp)
            {
                await ReachFinalCatchFromGrip9();
            }
            else
            {
            await StageTask10Grip9ControlApproach(tree, level, player, monitor, ascent,
                linkageControl, ObserveWithAscentDiagnostic,
                SwapGrip9ControlApproachGuard,
                keyboardLinkageRoute ? ReachFinalCatchFromGrip9 : null);
            using (var diagnostic = new Task10PostSplitControlDiagnostic(tree, player, monitor,
                linkageControl, linkage))
            {
                try
                {
                    await CastAt(tree, monitor, player, linkageControl, () => linkage.IsActivated, 120);
                    diagnostic.Boundary("CastAt-return");
                    TestAssert.True(linkage.IsActivated,
                        "Task10 operates the real courtyard linkage after completing split-level combat");
                }
                catch (Exception error) { diagnostic.Failure(error); throw; }
            }
            // Keyboard reaches the same actual FinalCatch before operating the
            // linkage. Legacy keeps its original control-then-transfer order.
            if (!keyboardLinkageRoute) await ReachFinalCatchFromGrip9();
            }
            async Task ReachFinalCatchFromGrip9()
            {
                using (var diagnostic = new Task10PostControlHandoffDiagnostic(tree, player, monitor,
                    level, ascent, exploration: false))
                {
                    try
                    {
                        StaticBody2D grip9 = Body(PrologueSectorId.CanyonAscent, "AscentGrip9");
                        CollisionShape2D grip9Shape = grip9.GetNode<CollisionShape2D>("Collision");
                        PlayerInputReader input = player.GetNode<PlayerInputReader>("Input");
                        PrologueGameFlowController flow = level.GetNode<PrologueGameFlowController>("GameFlow");
                        ulong playerId = player.GetInstanceId();
                        bool Live(Node node) => node != null && GodotObject.IsInstanceValid(node) &&
                            node.IsInsideTree();
                        void CheckFinalCatchReadiness()
                        {
                            TestAssert.True(Live(player) && Live(monitor.Player) && Live(input) &&
                                Live(level) && Live(flow) && Live(grip9) && Live(grip9Shape),
                                "Task10 FinalCatch readiness requires live player, flow and Grip9 support");
                            PlayerInputFrame sampled = input.CurrentFrame;
                            bool contained = TryTask10CapsuleCorridor(player, grip9Shape,
                                out float left, out float right, out float supportLeft, out float supportRight);
                            TestAssert.True(player.GetInstanceId() == playerId &&
                                monitor.Player.GetInstanceId() == playerId &&
                                flow.State == PrologueGameFlowState.Playing &&
                                contained && HasFloorContact(player, grip9) &&
                                player.Velocity.IsFinite() && player.Velocity.Length() <= 2f &&
                                sampled.MoveAxis == 0f && !sampled.JumpPressed && !sampled.JumpHeld &&
                                !sampled.DashPressed && !sampled.PrimaryPressed && !sampled.PrimaryHeld &&
                                !sampled.PrimaryReleased,
                                $"Task10 FinalCatch readiness preserves same stationary Playing player, " +
                                $"full upward Grip9 support and neutral input; physics={Engine.GetPhysicsFrames()} " +
                                $"player_id={playerId} capsule_x={left}/{right} support_x={supportLeft}/{supportRight} " +
                                $"full_containment={contained} velocity={player.Velocity} " +
                                $"move={sampled.MoveAxis} jump={sampled.JumpPressed}/{sampled.JumpHeld} " +
                                $"dash={sampled.DashPressed} primary={sampled.PrimaryPressed}/" +
                                $"{sampled.PrimaryHeld}/{sampled.PrimaryReleased}");
                        }
                        CheckFinalCatchReadiness();
                        await WaitTask10SupportedClawReady(tree, player, monitor, () =>
                        {
                            ObserveWithAscentDiagnostic();
                            CheckFinalCatchReadiness();
                        }, grip9, "FinalCatch", "TASK10_FINAL_CATCH_READY");
                        CheckFinalCatchReadiness();
                        await PrologueCanyonTraversalTests.Task4ReachSupport(tree, player,
                            Body(PrologueSectorId.CanyonAscent, "AscentFinalCatch"), clawRequired: true);
                        diagnostic.Boundary("ReachSupport-return");
                    }
                    catch (Exception error) { diagnostic.Failure(error); throw; }
                }
            }
            // Explicit pre-observer INPUT consumer, not the passive route observer.
            // Use the existing per-physics boundary; add no waits or new traversal
            // inputs. L's real keyboard direction/movement effects remain intact.
            var courtyardTransferLeaves = new List<AttackTelegraphVisual>();
            var courtyardTransferShield = player.GetNode<PlayerShieldController>("Shield");
            var courtyardTransferCombat = player.GetNode<PlayerCombat>("Combat");
            var courtyardTransferHealth = player.GetNode<HealthComponent>("Health");
            bool courtyardTransferKeyboard = KeyboardRouteInputDriver.Current != null;
            int courtyardTransferHp = courtyardTransferHealth.CurrentHealth;
            int courtyardTransferSamples = 0, courtyardTransferRequests = 0, courtyardTransferBlocks = 0;
            ulong courtyardTransferStart = Engine.GetPhysicsFrames();
            bool courtyardTransferLastGuard = false;
            Action courtyardPreviousInput = null;
            Action<PlayerShieldResult, ulong> courtyardGuardResult = (result, _) =>
            { if (result.Guarded) courtyardTransferBlocks++; };
            void PrepareCourtyardTransferInput()
            {
                courtyardPreviousInput?.Invoke();
                Task10EncounterDanger danger = default;
                if (world.TryGetMountedSector(PrologueSectorId.LostTemple, out var mountedTemple) &&
                    mountedTemple.GetNodeOrNull<Node>("Gameplay/Actors") is { } actorRoot)
                    danger = Task10ObserveEncounterDanger(actorRoot,
                        "canyon.v2.encounter.sealed-courtyard", null, false, courtyardTransferLeaves);
                bool defend = !courtyardTransferCombat.IsAttacking &&
                    Task10MixedDefendWindow(courtyardTransferShield, danger);
                monitor.CombatDecisionObserved?.Invoke(danger.SourceActorId, danger, defend);
                KeyboardRouteInputDriver.Current.PointerButton(MouseButton.Right, defend,
                    player, danger.GuardSource, stopForGuard: true);
                courtyardTransferSamples++;
                if (defend) courtyardTransferRequests++;
                if (defend != courtyardTransferLastGuard)
                    GD.Print($"TASK10_COURTYARD_TRANSFER_GUARD physics={Engine.GetPhysicsFrames()} " +
                        $"sample={player.GetNode<PlayerInputReader>("Input").CurrentFrameSequence} requested={defend} " +
                        $"actor={danger.SourceActorId} attack={danger.AttackId} phase={danger.Phase} " +
                        $"remaining={danger.RemainingSeconds:R} source={danger.GuardSource} player={player.GlobalPosition} " +
                        $"guard={courtyardTransferShield.IsActive}/{courtyardTransferShield.GuardDirection} " +
                        "phase_boundary_before_node_processing=true additional_wait=false");
                courtyardTransferLastGuard = defend;
            }
            if (courtyardTransferKeyboard)
            {
                courtyardPreviousInput = SwapTempleEntryPreObserverGuard(PrepareCourtyardTransferInput);
                courtyardTransferShield.ShieldResolved += courtyardGuardResult;
            }
            try
            {
            await PrologueCanyonTraversalTests.Task4ReachSupport(tree, player,
                Body(PrologueSectorId.CanyonAscent, "CourtyardApproach"), clawRequired: false);
            await PrologueCanyonTraversalTests.Task4WalkTo(tree, player, 5220f, 100);
            await PrologueCanyonTraversalTests.Task4WaitSupport(tree, player,
                Sector(PrologueSectorId.LostTemple), "CourtyardFloor");
            StaticBody2D courtyardStep = Body(PrologueSectorId.LostTemple, "CourtyardStep");
            CollisionShape2D courtyardStepShape = courtyardStep.GetNode<CollisionShape2D>("Collision");
            CanyonEncounterGroup courtyardEncounter = world.FindChildren("*", "", true, false)
                .OfType<CanyonEncounterGroup>().Single(group => group.EncounterId ==
                    "canyon.v2.encounter.sealed-courtyard");
            CanyonSealGate courtyardSeal = Sector(PrologueSectorId.LostTemple)
                .GetNode<CanyonSealGate>("Gameplay/Mechanisms/CourtyardSeal");
            CollisionShape2D courtyardSealCollision = courtyardSeal.GetNode<CollisionShape2D>("Collision");
            PrologueGameFlowController courtyardFlow = level.GetNode<PrologueGameFlowController>("GameFlow");
            PlayerMotor courtyardMotor = player.GetNode<PlayerMotor>("Motor");
            int acceptedJumpsBeforeStep = courtyardMotor.AcceptedJumpCount;
            int acceptedDashesBeforeStep = courtyardMotor.AcceptedDashCount;
            int recoveriesRequestedBeforeStep = monitor.RecoveryRequested;
            int recoveriesCompletedBeforeStep = monitor.RecoveryCompleted;
            ulong courtyardPlayerId = player.GetInstanceId();
            TestAssert.True(player.IsOnFloor() && HasFloorContact(player,
                    Body(PrologueSectorId.LostTemple, "CourtyardFloor")),
                "Task10 courtyard ordinary step begins from confirmed grounded CourtyardFloor support");
            PlayerInputReader courtyardInput = player.GetNode<PlayerInputReader>("Input");
            static bool IsCourtyardDiagnosticNodeLive(GodotObject value) => GodotObject.IsInstanceValid(value);
            void AssertCourtyardBoundary(string boundary)
            {
                TestAssert.True(IsCourtyardDiagnosticNodeLive(player) && player.IsInsideTree() &&
                    player.GetInstanceId() == courtyardPlayerId && IsCourtyardDiagnosticNodeLive(level) && level.IsInsideTree() &&
                    IsCourtyardDiagnosticNodeLive(courtyardFlow) && courtyardFlow.State == PrologueGameFlowState.Playing,
                    $"Task10 {boundary} requires the same live player and Playing game flow");
                TestAssert.Equal(recoveriesRequestedBeforeStep, monitor.RecoveryRequested,
                    $"Task10 {boundary} must not request recovery during courtyard step transfer");
                TestAssert.Equal(recoveriesCompletedBeforeStep, monitor.RecoveryCompleted,
                    $"Task10 {boundary} must not complete recovery during courtyard step transfer");
            }
            bool TryGetCourtyardContainment(out float playerLeft, out float playerRight,
                out float stepLeft, out float stepRight)
            {
                playerLeft = playerRight = stepLeft = stepRight = 0f;
                if (!IsCourtyardDiagnosticNodeLive(player) || !IsCourtyardDiagnosticNodeLive(courtyardStep) ||
                    !IsCourtyardDiagnosticNodeLive(courtyardStepShape) ||
                    !IsCourtyardDiagnosticNodeLive(courtyardStepShape.Shape)) return false;
                CollisionShape2D playerShapeNode = player.GetNodeOrNull<CollisionShape2D>("BodyCollider");
                if (!IsCourtyardDiagnosticNodeLive(playerShapeNode) || !IsCourtyardDiagnosticNodeLive(playerShapeNode.Shape) ||
                    courtyardStepShape.Shape is not RectangleShape2D supportRect) return false;
                float playerHalfWidth = playerShapeNode.Shape switch
                {
                    CapsuleShape2D capsule => capsule.Radius,
                    RectangleShape2D rectangle => rectangle.Size.X / 2f,
                    CircleShape2D circle => circle.Radius,
                    _ => 0f
                };
                if (playerHalfWidth <= 0f) return false;
                playerLeft = player.GlobalPosition.X - playerHalfWidth;
                playerRight = player.GlobalPosition.X + playerHalfWidth;
                stepLeft = courtyardStep.GlobalPosition.X - supportRect.Size.X / 2f;
                stepRight = courtyardStep.GlobalPosition.X + supportRect.Size.X / 2f;
                return playerLeft >= stepLeft && playerRight <= stepRight;
            }
            void SnapshotCourtyardStep(string boundary)
            {
                try
                {
                    var contacts = new List<string>();
                    bool playerLive = IsCourtyardDiagnosticNodeLive(player);
                    if (playerLive)
                    {
                        for (int index = 0; index < player.GetSlideCollisionCount(); index++)
                        {
                            KinematicCollision2D contact = player.GetSlideCollision(index);
                            if (!IsCourtyardDiagnosticNodeLive(contact)) { contacts.Add("invalid-contact"); continue; }
                            GodotObject collider = contact.GetCollider();
                            string colliderName = !IsCourtyardDiagnosticNodeLive(collider) ? "invalid-collider" : collider is Node node && IsCourtyardDiagnosticNodeLive(node)
                                ? $"{node.Name}#{node.GetInstanceId()}" : $"non-node#{collider.GetInstanceId()}";
                            contacts.Add($"{colliderName}:{contact.GetNormal()}");
                        }
                    }
                    bool inputLive = IsCourtyardDiagnosticNodeLive(courtyardInput);
                    PlayerInputFrame sampled = inputLive ? courtyardInput.CurrentFrame : default;
                    bool containment = TryGetCourtyardContainment(out float playerLeft,
                        out float playerRight, out float stepLeft, out float stepRight);
                    bool stepCollisionDisabled = IsCourtyardDiagnosticNodeLive(courtyardStepShape) && courtyardStepShape.Disabled;
                    bool sealOpen = IsCourtyardDiagnosticNodeLive(courtyardSeal) && courtyardSeal.IsOpen;
                    bool sealCollisionDisabled = IsCourtyardDiagnosticNodeLive(courtyardSealCollision) && courtyardSealCollision.Disabled;
                    int hp = playerLive && IsCourtyardDiagnosticNodeLive(player.GetNodeOrNull<HealthComponent>("Health"))
                        ? player.GetNode<HealthComponent>("Health").CurrentHealth : -1;
                    string recovery = $"{monitor.RecoveryRequested}/{monitor.RecoveryCompleted}";
                    string inputSequence = inputLive ? courtyardInput.CurrentFrameSequence.ToString() : "invalid";
                    string position = playerLive ? player.GlobalPosition.ToString() : "invalid";
                    string velocity = playerLive ? player.Velocity.ToString() : "invalid";
                    bool encounterLive = IsCourtyardDiagnosticNodeLive(courtyardEncounter);
                    string mechanisms = IsCourtyardDiagnosticNodeLive(level)
                        ? string.Join(',', level.Progress.ActivatedMechanisms) : "unavailable";
                    GD.Print($"TASK10_COURTYARD_STEP boundary={boundary} physics={Engine.GetPhysicsFrames()} " +
                        $"player_live={playerLive} player_id={(playerLive ? player.GetInstanceId() : 0)} " +
                        $"position={position} velocity={velocity} hp={hp} recovery={recovery} " +
                        $"input_sequence={inputSequence} jump={sampled.JumpPressed}/{sampled.JumpHeld} " +
                        $"dash={sampled.DashPressed} contacts={string.Join(';', contacts)} " +
                        $"containment={containment} player_x={playerLeft}/{playerRight} step_x={stepLeft}/{stepRight} " +
                        $"step_collision_disabled={stepCollisionDisabled} seal_open={sealOpen} " +
                        $"seal_collision_disabled={sealCollisionDisabled} " +
                        $"prerequisites={mechanisms} " +
                        $"encounter_live={encounterLive} encounter_active={(encounterLive ? courtyardEncounter.IsActive : false)} " +
                        $"batch={(encounterLive ? courtyardEncounter.CurrentBatch : -1)} " +
                        $"live_actors={(encounterLive ? courtyardEncounter.LiveActorCount : -1)} " +
                        $"accepted_jumps={(IsCourtyardDiagnosticNodeLive(courtyardMotor) ? courtyardMotor.AcceptedJumpCount : -1)} " +
                        $"accepted_dashes={(IsCourtyardDiagnosticNodeLive(courtyardMotor) ? courtyardMotor.AcceptedDashCount : -1)}");
                }
                catch (Exception diagnosticError)
                {
                    try
                    {
                        GD.Print($"TASK10_COURTYARD_STEP_DIAGNOSTIC_GAP boundary={boundary} " +
                            $"type={diagnosticError.GetType().Name} message={diagnosticError.Message.Replace('\r', ' ').Replace('\n', ' ')}");
                    }
                    catch { /* Diagnostics must not replace the route failure. */ }
                }
            }
            AssertCourtyardBoundary("before ordinary step");
            SnapshotCourtyardStep("before-ordinary-step");
            try
            {
                await PrologueCanyonTraversalTests.Task4ReachSupport(tree, player,
                    courtyardStep, clawRequired: false);
                SnapshotCourtyardStep("ordinary-step-return");
                AssertCourtyardBoundary("ordinary step return");
                void AssertFullySupportedStep(string boundary)
                {
                    bool contained = TryGetCourtyardContainment(out float playerLeft,
                        out float playerRight, out float stepLeft, out float stepRight);
                    TestAssert.True(IsCourtyardDiagnosticNodeLive(courtyardStep) &&
                        IsCourtyardDiagnosticNodeLive(courtyardStepShape) &&
                        player.IsOnFloor() && HasFloorContact(player, courtyardStep) && contained,
                        $"Task10 {boundary} requires real upward contact with CourtyardStep");
                    TestAssert.True(playerLeft >= stepLeft && playerRight <= stepRight,
                        $"Task10 {boundary} requires full capsule support; player_x={playerLeft}/{playerRight} " +
                        $"step_x={stepLeft}/{stepRight}");
                }
                AssertFullySupportedStep("ordinary step landing");
                await PrologueCanyonTraversalTests.Task4WalkTo(tree, player, 5580f, 100);
                SnapshotCourtyardStep("original-WalkTo-return");
                AssertCourtyardBoundary("original walk return");
                AssertFullySupportedStep("original walk");
                TestAssert.Equal(acceptedJumpsBeforeStep + 1, courtyardMotor.AcceptedJumpCount,
                    "Task10 courtyard step transfer accepts exactly one grounded ordinary jump and no dash");
                TestAssert.Equal(acceptedDashesBeforeStep, courtyardMotor.AcceptedDashCount,
                    "Task10 courtyard step transfer uses no dash");
            }
            catch (Exception routeError)
            {
                SnapshotCourtyardStep($"original-failure-{routeError.GetType().Name}");
                throw;
            }
            if (courtyardTransferKeyboard)
                TestAssert.Equal(courtyardTransferHp, courtyardTransferHealth.CurrentHealth,
                    "keyboard courtyard transfer preserves entry HP with actual directional guarding, not recovery");
            }
            finally
            {
                if (courtyardTransferKeyboard)
                {
                    SwapTempleEntryPreObserverGuard(courtyardPreviousInput);
                    if (GodotObject.IsInstanceValid(courtyardTransferShield))
                        courtyardTransferShield.ShieldResolved -= courtyardGuardResult;
                    SendMouse(MouseButton.Right, false, player, Vector2.Zero);
                    GD.Print($"TASK10_COURTYARD_TRANSFER_GUARD_END samples={courtyardTransferSamples} " +
                        $"held_requests={courtyardTransferRequests} guarded_contacts={courtyardTransferBlocks} " +
                        $"physics_elapsed={Engine.GetPhysicsFrames()-courtyardTransferStart} " +
                        "original_walk100_approach90_landing300_tail3=true added_jump_dash_attack=false full_route_not_implied=true");
                }
            }
            if (!fragmentReturnFromCamp)
                await DefeatTask10Encounter(tree, level, world, player, monitor,
                    "canyon.v2.encounter.sealed-courtyard");
            CanyonSealGate seal = Sector(PrologueSectorId.LostTemple)
                .GetNode<CanyonSealGate>("Gameplay/Mechanisms/CourtyardSeal");
            for (int frame = 0; frame < 30 && !seal.IsOpen; frame++)
                await PhysicsFrames(tree, monitor, 1);
            TestAssert.True(seal.IsOpen,
                "split-level defeat plus real linkage input opens the authored courtyard seal");
            await PrologueCanyonTraversalTests.Task4ReachSupport(tree, player,
                Body(PrologueSectorId.LostTemple, "CheckpointFloor"), clawRequired: false);
            if (fragmentReturnFromCamp) return; // Separate regional proof owns the already-open BellChain and sixth pickup.
            await EnterTask10TempleAndBoss(tree, level, world, player, monitor,
                ObserveWithAscentDiagnostic, SwapGrip9ControlApproachGuard,
                SwapTempleEntryPreObserverGuard, templeCheckpointSnapshotPath, variant, naturalRoute);
            await DriveTask10BossPhaseOnePositional(tree, level, world, player, monitor,
                ObserveWithAscentDiagnostic, SwapGrip9ControlApproachGuard,
                SwapTempleEntryPreObserverGuard);
            Task10BossOpeningReceipt firstOpening = await DriveTask10BossFirstExposure(tree, level, world, player, monitor,
                ObserveWithAscentDiagnostic, SwapGrip9ControlApproachGuard,
                SwapTempleEntryPreObserverGuard);
            Task10BossOpeningReceipt hp1Opening = await DriveTask10BossNonfatalRepeats(tree, level, world, player, monitor,
                ObserveWithAscentDiagnostic, SwapGrip9ControlApproachGuard,
                SwapTempleEntryPreObserverGuard, firstOpening);
            Task10BossDeathReceipt death = await DriveTask10BossFatalOpening(tree, level, world, player, monitor,
                ObserveWithAscentDiagnostic, SwapGrip9ControlApproachGuard,
                SwapTempleEntryPreObserverGuard, hp1Opening);
            Task10TerminalProof terminal = await DriveTask10BossPhysicalExit(tree, level, world, player, monitor,
                ObserveWithAscentDiagnostic, SwapGrip9ControlApproachGuard,
                SwapTempleEntryPreObserverGuard, death);
            evidence.RecordTerminal(terminal);
            Task10RouteProofContract.AssertTerminal(evidence.TerminalProof, evidence.PlayerInstanceId);
            GD.Print($"TASK10_TERMINAL_RECEIPT_RECORDED player={terminal.PlayerInstanceId} boss={terminal.BossInstanceId} " +
                $"attack={terminal.FatalAttackId} event_physics={terminal.CompletionPhysics} held_end_physics={terminal.HeldEndPhysics} " +
                $"held_input_frames={terminal.HeldInputFrameCount} fixture=False fullRoute=False");
        }
        catch (Exception error)
        {
            ascentDiagnostic?.Failure(error);
            throw; // Diagnostics never replace the original route failure or stack.
        }
        finally
        {
            ascentDiagnostic?.Dispose();
            ascentDiagnostic = null;
            PrologueCanyonTraversalTests.EndTask10InputDrive();
        }
    }

    private static async Task EnterTask10TempleAndBoss(SceneTree tree,
        PrologueLevelController level, SeamlessPrologueWorld world, CharacterBody2D player,
        RouteMonitor monitor, Action observe, Func<Action, Action> swapApproachGuard,
        Func<Action, Action> swapPreObserverGuard, string templeCheckpointSnapshotPath,
        Task10RouteVariant variant, NaturalFragmentRouteContext naturalRoute = null)
    {
        bool Live(Node node) => node != null && GodotObject.IsInstanceValid(node) &&
            node.IsInsideTree() && !node.IsQueuedForDeletion();
        void Check(bool condition, string message) => TestAssert.True(condition,
            "Task10 Temple entry: " + message);
        Check(GodotObject.IsInstanceValid(tree) && Live(level) && Live(world) &&
            Live(player) && Live(monitor.Player), "requires native-valid live entry nodes");
        Check(world.TryGetMountedSector(PrologueSectorId.LostTemple, out PrologueSector temple) &&
            Live(temple), "requires the actually mounted LostTemple");
        PrologueGameFlowController flow = level.GetNode<PrologueGameFlowController>("GameFlow");
        HealthComponent health = player.GetNode<HealthComponent>("Health");
        PlayerMotor motor = player.GetNode<PlayerMotor>("Motor");
        PlayerInputReader input = player.GetNode<PlayerInputReader>("Input");
        PlayerActionModeController modes = player.GetNode<PlayerActionModeController>("ActionModes");
        MechanicalClawController claw = player.GetNode<MechanicalClawController>("MechanicalClaw");
        StaticBody2D checkpointFloor = temple.GetNode<StaticBody2D>("Gameplay/Collision/CheckpointFloor");
        StaticBody2D arenaFloor = temple.GetNode<StaticBody2D>("Gameplay/Collision/ArenaFloor");
        BellChainMechanism chain = temple.GetNode<BellChainMechanism>("Gameplay/Mechanisms/BellChain");
        CheckpointTrigger checkpoint = temple.GetNode<CheckpointTrigger>("Gameplay/TempleCheckpoint");
        BossArenaController arena = temple.GetNode<BossArenaController>("Gameplay/BossArenaController");
        Check(new Node[] { flow, health, motor, input, modes, claw, checkpointFloor,
            arenaFloor, chain, checkpoint, arena }.All(Live), "requires live original components");
        ThreadTarget2D target = chain.GetNode<ThreadTarget2D>("ThreadTarget");
        CollisionShape2D chainDoor = chain.GetNode<CollisionShape2D>("Door/Collision");
        CollisionShape2D checkpointShape = checkpointFloor.GetNode<CollisionShape2D>("Collision");
        CollisionShape2D arenaShape = arenaFloor.GetNode<CollisionShape2D>("Collision");
        CollisionShape2D bodyShape = player.GetNode<CollisionShape2D>("BodyCollider");
        Area2D bossTrigger = arena.GetNode<Area2D>(arena.ActivationTriggerPath);
        CollisionShape2D bossTriggerShape = bossTrigger.GetNode<CollisionShape2D>("Collision");
        CollisionShape2D entryDoor = arena.GetNode<CollisionShape2D>(arena.EntryDoorCollisionPath);
        CollisionShape2D exitDoor = arena.GetNode<CollisionShape2D>(arena.ExitDoorCollisionPath);
        FallenBellkeeper boss = arena.CurrentBoss;
        Check(new Node[] { target, chainDoor, checkpointShape, arenaShape, bodyShape,
            bossTrigger, bossTriggerShape, entryDoor, exitDoor, boss }.All(Live),
            "requires live target, doors, supports and actual spawned Boss");
        LegacyThreadInteractionAdapter adapter = target.GetNode<LegacyThreadInteractionAdapter>(
            "LegacyThreadInteractionAdapter");
        HealthComponent bossHealth = boss.GetNode<HealthComponent>("Health");
        StaticBody2D entryDoorBody = entryDoor.GetParent() as StaticBody2D;
        Node[] nodes = { level, world, player, monitor.Player, temple, flow, health, motor,
            input, modes, claw, checkpointFloor, arenaFloor, chain, checkpoint, arena,
            target, adapter, chainDoor, checkpointShape, arenaShape, bodyShape, bossTrigger,
            bossTriggerShape, entryDoor, entryDoorBody, exitDoor, boss, bossHealth };
        Check(nodes.All(Live), "requires live adapter and Boss health before baseline reads");
        ulong playerId = player.GetInstanceId(), targetId = target.GetInstanceId();
        ulong bossId = boss.GetInstanceId();
        int hp = health.CurrentHealth, requests = monitor.RecoveryRequested;
        int recoveries = monitor.RecoveryCompleted, jumps = motor.AcceptedJumpCount;
        int dashes = motor.AcceptedDashCount, applications = adapter.ApplicationCount;
        int bossHp = bossHealth.CurrentHealth;
        ulong nextCast = claw.CurrentFrame.NextCastId;
        string phase = "entry", callbackFailure = null;
        bool casting = false, chainComplete = false, travelSeen = false, latchedSeen = false;
        bool releasedSeen = false, idleSeen = false, invalidCast = false;
        bool checkpointBodySeen = false, checkpointSignalSeen = false, bossBodySeen = false;
        int primarySamples = 0, checkpointBodies = 0, checkpointSignals = 0, bossBodies = 0;
        ulong primarySequence = 0, sampledE = 0;
        bool keyboardChain = KeyboardRouteInputDriver.Current != null;
        ulong keyboardReadySequence = 0UL;
        ulong eIssueSequence = 0, primaryIssueSequence = 0;
        int castWaits = 0, eSamplingWaits = 0, primarySamplingWaits = 0;
        ulong lastSamplingDiagnosticSequence = 0;
        Action previousGuard = null;
        Action previousPreObserverGuard = null;
        Exception firstFailure = null, cleanupFailure = null;

        void Safety()
        {
            Check(GodotObject.IsInstanceValid(tree) && nodes.All(Live),
                "keeps all native nodes live before each read/wait");
            Check(new[] { checkpointShape, arenaShape, bodyShape, chainDoor,
                bossTriggerShape, entryDoor, exitDoor }.All(shape =>
                GodotObject.IsInstanceValid(shape.Shape)), "keeps collision resources live");
            Check(player.GetInstanceId() == playerId && monitor.Player.GetInstanceId() == playerId &&
                arena.CurrentBoss == boss && boss.GetInstanceId() == bossId &&
                flow.State == PrologueGameFlowState.Playing && !tree.Paused && hp > 0 &&
                health.CurrentHealth == hp && monitor.RecoveryRequested == requests &&
                monitor.RecoveryCompleted == recoveries && motor.AcceptedJumpCount == jumps &&
                motor.AcceptedDashCount == dashes && player.GlobalPosition.IsFinite() &&
                player.Velocity.IsFinite(), "preserves same Playing player, HP, recovery and jump/dash baselines");
            Check(bossHp > 0 && bossHp == bossHealth.MaxHealth && bossHealth.CurrentHealth == bossHp,
                "preserves the same positive untouched full-health Boss");
            Check(!input.CurrentFrame.JumpPressed && !input.CurrentFrame.JumpHeld &&
                !input.CurrentFrame.DashPressed && !input.CurrentFrame.ShieldHeld &&
                !input.CurrentFrame.AttackModePressed &&
                (!keyboardChain || !input.CurrentFrame.AttackPressed && !input.CurrentFrame.InteractPressed),
                "uses no jump, dash, shield or combat mode input");
            Check(callbackFailure == null && !invalidCast, "keeps event attribution valid: " + callbackFailure);
            Check(adapter.ApplicationCount >= applications &&
                adapter.ApplicationCount <= applications + (casting || chainComplete ? 1 : 0),
                "admits no extra chain application");
            if (phase != "boss-approach" && phase != "boss-gates" && phase != "activation")
                Check(!arena.IsEncounterActive && !bossTrigger.GetOverlappingBodies().Contains(player),
                    "does not start Boss before the actual final approach");
        }
        bool UpwardContact(StaticBody2D floor)
        {
            if (!Live(player) || !Live(floor) || !player.IsOnFloor()) return false;
            for (int index = 0; index < player.GetSlideCollisionCount(); index++)
            {
                KinematicCollision2D contact = player.GetSlideCollision(index);
                if (!GodotObject.IsInstanceValid(contact)) continue;
                GodotObject collider = contact.GetCollider();
                if (GodotObject.IsInstanceValid(collider) && collider == floor && contact.GetNormal().Y < -.7f)
                    return true;
            }
            return false;
        }
        bool Supported(StaticBody2D floor, CollisionShape2D shape) =>
            TryTask10CapsuleCorridor(player, shape, out _, out _, out _, out _) &&
            UpwardContact(floor);
        bool GroundedAcrossSeam()
        {
            if (Supported(checkpointFloor, checkpointShape) || Supported(arenaFloor, arenaShape)) return true;
            if (checkpointShape.Disabled || arenaShape.Disabled || bodyShape.Disabled ||
                bodyShape.Shape is not CapsuleShape2D capsule ||
                checkpointShape.Shape is not RectangleShape2D leftRect ||
                arenaShape.Shape is not RectangleShape2D rightRect) return false;
            Vector2 leftEnd = checkpointShape.ToGlobal(new Vector2(leftRect.Size.X / 2f, -leftRect.Size.Y / 2f));
            Vector2 rightStart = arenaShape.ToGlobal(new Vector2(-rightRect.Size.X / 2f, -rightRect.Size.Y / 2f));
            float bodyLeft = bodyShape.ToGlobal(new Vector2(-capsule.Radius, 0f)).X;
            float bodyRight = bodyShape.ToGlobal(new Vector2(capsule.Radius, 0f)).X;
            return leftEnd.IsFinite() && rightStart.IsFinite() && leftEnd.DistanceTo(rightStart) <= .01f &&
                bodyLeft >= checkpointShape.ToGlobal(new Vector2(-leftRect.Size.X / 2f, 0f)).X &&
                bodyRight <= arenaShape.ToGlobal(new Vector2(rightRect.Size.X / 2f, 0f)).X &&
                (UpwardContact(checkpointFloor) || UpwardContact(arenaFloor));
        }
        bool Neutral() => input.CurrentFrame.MoveAxis == 0f &&
            !input.CurrentFrame.PrimaryPressed && !input.CurrentFrame.PrimaryHeld &&
            !input.CurrentFrame.PrimaryReleased && !input.CurrentFrame.GrappleModePressed &&
            (!keyboardChain || !Input.IsActionPressed(InputActions.Claw) &&
                !Input.IsActionPressed(InputActions.Attack) && !Input.IsActionPressed(InputActions.Interact)) &&
            player.Velocity.Length() <= 2f;
        bool Idle() => claw.CurrentFrame.State == MechanicalClawState.Idle &&
            claw.CurrentFrame.CastId == 0UL && claw.CurrentFrame.LockedTargetRuntimeId == 0UL &&
            claw.CurrentFrame.Failure == MechanicalClawFailure.None &&
            claw.CurrentTarget == null && claw.ResidencyTarget == null;
        void Guard()
        {
            previousGuard?.Invoke();
            Safety();
            Check(GroundedAcrossSeam(), "keeps actual upward contact and full contiguous ground support");
            bool chainEdge = keyboardChain ? input.CurrentFrame.ClawPressed : input.CurrentFrame.PrimaryPressed;
            if (chainEdge && primarySequence != input.CurrentFrameSequence)
            {
                primarySequence = input.CurrentFrameSequence;
                primarySamples++;
                ulong readySequence = keyboardChain ? keyboardReadySequence : sampledE;
                Check(casting && readySequence != 0UL && primarySequence > readySequence && primarySamples == 1 &&
                    (!keyboardChain || input.CurrentFrame.KeyboardActions &&
                        !input.CurrentFrame.PrimaryPressed && !input.CurrentFrame.GrappleModePressed &&
                        input.KeyboardAimDirection.Dot(Vector2.Up) > .99f),
                    "samples exactly one fresh typed K or legacy LMB after readiness");
            }
            Check(claw.CurrentFrame.NextCastId == nextCast + (casting || chainComplete ? 1UL : 0UL) ||
                casting && claw.CurrentFrame.NextCastId == nextCast, "admits only the exact one chain cast");
            if (casting) Check(Supported(checkpointFloor, checkpointShape) &&
                input.CurrentFrame.MoveAxis == 0f && player.Velocity.Length() <= 2f,
                "casts only while stationary on full CheckpointFloor");
            if (chainComplete) Check(chain.IsOpen && chainDoor.Disabled &&
                level.Progress.BellChainShortcutOpen && adapter.ApplicationCount == applications + 1 && Idle(),
                "retains real open door/progress, one application and target-free Idle while walking");
        }
        async Task Tick()
        {
            Safety();
            await tree.ToSignal(tree, SceneTree.SignalName.PhysicsFrame);
            Safety(); // Native lifetime checks precede the combined monitor/evidence reads.
            observe(); // Original combined observer exactly once; it invokes this scoped Guard.
        }
        void PreObserverSafety()
        {
            Safety(); // Also protects retained legacy walking waits before their registered observer.
            previousPreObserverGuard?.Invoke();
        }
        bool ExactSampledAim()
        {
            if (!keyboardChain) return input.CurrentFrame.MouseWorld.IsFinite() && target.WorldAnchor.IsFinite() &&
                input.CurrentFrame.MouseWorld.DistanceTo(target.WorldAnchor) <= .01f;
            MechanicalClawTargetResolution selected = new MechanicalClawTargetResolver()
                .ResolveKeyboard(player, input.KeyboardAimDirection);
            return input.CurrentFrame.KeyboardActions && input.KeyboardAimDirection.Dot(Vector2.Up) > .99f &&
                selected.Surface == target && selected.Snapshot.HasLineOfSight &&
                claw.KeyboardPreview.Surface == target && claw.KeyboardPreview.Snapshot.HasLineOfSight;
        }
        bool ESampleReady() => (keyboardChain
                ? keyboardReadySequence > eIssueSequence && input.CurrentFrameSequence >= keyboardReadySequence
                : sampledE > eIssueSequence && input.CurrentFrameSequence > sampledE) &&
            modes.CanBeginGrapple && Idle() && ExactSampledAim();
        bool PrimarySampleReady()
        {
            ulong readySequence = keyboardChain ? keyboardReadySequence : sampledE;
            return primaryIssueSequence >= readySequence && readySequence != 0UL &&
                (keyboardChain || primaryIssueSequence > readySequence) &&
                primarySequence > primaryIssueSequence && primarySequence > readySequence && primarySamples == 1;
        }
        void SamplingLog(string boundary, bool terminal = false)
        {
            try
            {
                Safety(); // Including failure records: no diagnostic reads before native validation.
                if (!terminal && lastSamplingDiagnosticSequence == input.CurrentFrameSequence) return;
                lastSamplingDiagnosticSequence = input.CurrentFrameSequence;
                PlayerInputFrame sampled = input.CurrentFrame;
                Vector2 anchor = target.WorldAnchor;
                float aimError = sampled.MouseWorld.DistanceTo(anchor);
                GD.Print($"TASK10_TEMPLE_INPUT_SAMPLE boundary={boundary} physics={Engine.GetPhysicsFrames()} " +
                    $"e_issue_sequence={eIssueSequence} input_sequence={input.CurrentFrameSequence} " +
                    $"latched_E_sequence={sampledE} primary_issue_sequence={primaryIssueSequence} " +
                    $"latched_primary_sequence={primarySequence} E_edge={sampled.GrappleModePressed} " +
                    $"fresh_E_seen={sampledE > eIssueSequence} issue_after_E={input.CurrentFrameSequence > sampledE} " +
                    $"mode={modes.CurrentMode} slot={modes.ActiveSlot} can_begin_grapple={modes.CanBeginGrapple} " +
                    $"shield_held={sampled.ShieldHeld} sampled_mouse_world={sampled.MouseWorld} exact_target={anchor} " +
                    $"aim_finite={sampled.MouseWorld.IsFinite() && anchor.IsFinite()} aim_error={aimError} " +
                    $"aim_within_0_01={ExactSampledAim()} has_observed_mouse_motion={input.HasObservedMouseMotion} " +
                    $"mouse_motion_sequence={input.MouseMotionSequence} observed_mouse_viewport={input.LastObservedMouseViewportPosition} " +
                    $"target_viewport={ToViewport(player, anchor)} idle={Idle()} " +
                    $"primary_edge_held_released={sampled.PrimaryPressed}/{sampled.PrimaryHeld}/{sampled.PrimaryReleased} " +
                    $"primary_samples={primarySamples} primary_issue_after_E={primaryIssueSequence > sampledE} " +
                    $"fresh_primary_seen={primarySequence > primaryIssueSequence} primary_after_E={primarySequence > sampledE} " +
                    $"E_ready={ESampleReady()} primary_ready={PrimarySampleReady()} " +
                    $"E_waits={eSamplingWaits}/8 primary_waits={primarySamplingWaits}/8 shared_waits={castWaits}/150");
            }
            catch (Exception diagnosticError)
            {
                try { GD.Print($"TASK10_TEMPLE_INPUT_SAMPLE_GAP boundary={boundary} " +
                    $"type={diagnosticError.GetType().Name} message={diagnosticError.Message.Replace('\r', ' ').Replace('\n', ' ')}"); }
                catch { /* Preserve the original sampling failure. */ }
            }
        }
        async Task Settle(StaticBody2D floor, CollisionShape2D shape)
        {
            Safety();
            ReleaseAll(player.GlobalPosition);
            ulong releaseSequence = input.CurrentFrameSequence;
            int waited = 0;
            while (waited < 24 && (input.CurrentFrameSequence <= releaseSequence || !Neutral()))
            { await Tick(); waited++; }
            Check(input.CurrentFrameSequence > releaseSequence && Neutral() && Supported(floor, shape),
                "samples neutral finite speed <=2 and full named support within 24 waits");
        }
        void Log(string boundary)
        {
            try
            {
                Check(nodes.All(Live) && new[] { checkpointShape, arenaShape, bodyShape, chainDoor,
                    bossTriggerShape, entryDoor }.All(shape => GodotObject.IsInstanceValid(shape.Shape)),
                    "requires native-valid diagnostic nodes/resources");
                bool fullCheckpoint = TryTask10CapsuleCorridor(player, checkpointShape,
                    out float capsuleLeft, out float capsuleRight, out float checkpointLeft, out float checkpointRight);
                bool doorGeometry = TryEntryDoorClearance(out Rect2 capsuleBounds,
                    out Rect2 doorBounds, out bool entryContact);
                GD.Print($"TASK10_TEMPLE_ENTRY boundary={boundary} phase={phase} physics={Engine.GetPhysicsFrames()} " +
                    $"player_id={playerId} position={player.GlobalPosition} velocity={player.Velocity} " +
                    $"hp={hp}->{health.CurrentHealth} recovery={requests}/{recoveries}->" +
                    $"{monitor.RecoveryRequested}/{monitor.RecoveryCompleted} jumps={jumps}->{motor.AcceptedJumpCount} " +
                    $"dashes={dashes}->{motor.AcceptedDashCount} input_sequence={input.CurrentFrameSequence} " +
                    $"move={input.CurrentFrame.MoveAxis} primary={input.CurrentFrame.PrimaryPressed}/" +
                    $"{input.CurrentFrame.PrimaryHeld}/{input.CurrentFrame.PrimaryReleased} " +
                    $"checkpoint_support={Supported(checkpointFloor, checkpointShape)} arena_support={Supported(arenaFloor, arenaShape)} " +
                    $"capsule_x={capsuleLeft}/{capsuleRight} checkpoint_x={checkpointLeft}/{checkpointRight} " +
                    $"checkpoint_containment={fullCheckpoint} target_anchor={target.WorldAnchor} " +
                    $"target_viewport={ToViewport(player, target.WorldAnchor)} chain_door_position={chainDoor.GlobalPosition} " +
                    $"chain_open={chain.IsOpen} chain_door_disabled={chainDoor.Disabled} applications={applications}->{adapter.ApplicationCount} " +
                    $"target_id={targetId} claw={claw.CurrentFrame.State} cast={claw.CurrentFrame.CastId} " +
                    $"next_cast={nextCast}->{claw.CurrentFrame.NextCastId} lifecycle={travelSeen}/{latchedSeen}/{releasedSeen}/{idleSeen} " +
                    $"checkpoint_events={checkpointBodies}/{checkpointSignals} checkpoint_id={world.CheckpointId} boss_events={bossBodies} " +
                    $"boss_active={arena.IsEncounterActive} boss_id={bossId} boss_hp={bossHp}->{bossHealth.CurrentHealth} " +
                    $"boss_frame={boss.CurrentFrame.State} attack={boss.CurrentFrame.AttackTimeline.Phase} " +
                    $"entry_disabled={entryDoor.Disabled} exit_disabled={exitDoor.Disabled} " +
                    $"entry_geometry={doorGeometry} capsule_edges={capsuleBounds.Position}/{capsuleBounds.End} " +
                    $"entry_door_bounds={doorBounds.Position}/{doorBounds.End} " +
                    $"entry_clearance={capsuleBounds.Position.X - doorBounds.End.X} entry_contact={entryContact} " +
                    $"entry_overlap={doorGeometry && capsuleBounds.Intersects(doorBounds)} entry_clear={EntryDoorClear()}");
            }
            catch (Exception diagnosticError)
            {
                try { GD.Print($"TASK10_TEMPLE_ENTRY_DIAGNOSTIC_GAP boundary={boundary} " +
                    $"type={diagnosticError.GetType().Name} message={diagnosticError.Message.Replace('\r', ' ').Replace('\n', ' ')}"); }
                catch { /* Preserve the original failure. */ }
            }
        }
        void ObserveCast(MechanicalClawFrame frame, GrappleSurface2D observedTarget)
        {
            try
            {
                if (!nodes.All(Live)) { callbackFailure ??= "native node invalid at claw publication"; return; }
                if (!casting) { if (frame.CastId != 0UL) invalidCast = true; return; }
                if (frame.State == MechanicalClawState.Failed || frame.BoostConsumed ||
                    frame.State is MechanicalClawState.Reel or MechanicalClawState.Swing or MechanicalClawState.Boost ||
                    frame.CastId != 0UL && frame.CastId != nextCast) invalidCast = true;
                if (frame.State is MechanicalClawState.Travel or MechanicalClawState.Latched)
                {
                    bool exact = Live(observedTarget) && observedTarget == target &&
                        observedTarget.GetInstanceId() == targetId && frame.CastId == nextCast &&
                        frame.LockedTargetRuntimeId == targetId && frame.AnchorPoint == target.WorldAnchor;
                    if (!exact) invalidCast = true;
                    if (frame.State == MechanicalClawState.Travel) travelSeen |= exact;
                    else { if (!travelSeen || releasedSeen) invalidCast = true; latchedSeen |= exact; }
                }
                if (frame.State == MechanicalClawState.Released)
                {
                    if (!latchedSeen || frame.CastId != nextCast || frame.LockedTargetRuntimeId != targetId ||
                        frame.Failure != MechanicalClawFailure.None ||
                        frame.ReleaseKind != MechanicalClawReleaseKind.Cancel) invalidCast = true;
                    releasedSeen = true;
                }
                if (frame.State == MechanicalClawState.Idle && frame.CastId == 0UL &&
                    frame.NextCastId == nextCast + 1UL)
                { if (!releasedSeen) invalidCast = true; idleSeen = true; }
            }
            catch (Exception error) { callbackFailure ??= error.GetType().Name + ":" + error.Message; }
        }
        void OnCheckpointBody(Node2D body)
        {
            if (!Live(body) || !Live(player)) { callbackFailure ??= "invalid checkpoint body"; return; }
            if (body == player && body.GetInstanceId() == playerId)
            { checkpointBodySeen = true; checkpointBodies++; }
        }
        void OnCheckpointSignal(StringName id)
        {
            checkpointSignals++;
            if (id.ToString() == "canyon.v2.temple-forecourt") checkpointSignalSeen = true;
            else callbackFailure ??= "unexpected Temple checkpoint identity " + id;
        }
        void OnBossBody(Node2D body)
        {
            if (!Live(body) || !Live(player)) { callbackFailure ??= "invalid Boss trigger body"; return; }
            if (body == player && body.GetInstanceId() == playerId) { bossBodySeen = true; bossBodies++; }
        }
        bool TryEntryDoorClearance(out Rect2 capsuleBounds, out Rect2 doorBounds, out bool contact)
        {
            capsuleBounds = doorBounds = default;
            contact = false;
            if (!Live(player) || !Live(bodyShape) || !Live(entryDoor) || !Live(entryDoorBody) ||
                !GodotObject.IsInstanceValid(bodyShape.Shape) || !GodotObject.IsInstanceValid(entryDoor.Shape) ||
                bodyShape.Shape is not CapsuleShape2D capsule || entryDoor.Shape is not RectangleShape2D rectangle)
                return false;
            Transform2D bodyTransform = bodyShape.GlobalTransform, doorTransform = entryDoor.GlobalTransform;
            if (!bodyTransform.Origin.IsFinite() || !bodyTransform.X.IsFinite() || !bodyTransform.Y.IsFinite() ||
                !doorTransform.Origin.IsFinite() || !doorTransform.X.IsFinite() || !doorTransform.Y.IsFinite() ||
                Mathf.Abs(bodyTransform.X.Y) > .001f || Mathf.Abs(bodyTransform.Y.X) > .001f ||
                Mathf.Abs(doorTransform.X.Y) > .001f || Mathf.Abs(doorTransform.Y.X) > .001f ||
                !float.IsFinite(capsule.Radius) || capsule.Radius <= 0f || !float.IsFinite(capsule.Height) ||
                capsule.Height < capsule.Radius * 2f || !rectangle.Size.IsFinite() ||
                rectangle.Size.X <= 0f || rectangle.Size.Y <= 0f) return false;
            Vector2 bodyHalf = new(capsule.Radius * Mathf.Abs(bodyTransform.X.X),
                capsule.Height * .5f * Mathf.Abs(bodyTransform.Y.Y));
            Vector2 doorHalf = new(rectangle.Size.X * .5f * Mathf.Abs(doorTransform.X.X),
                rectangle.Size.Y * .5f * Mathf.Abs(doorTransform.Y.Y));
            if (!bodyHalf.IsFinite() || !doorHalf.IsFinite() || bodyHalf.X <= 0f || bodyHalf.Y <= 0f ||
                doorHalf.X <= 0f || doorHalf.Y <= 0f) return false;
            capsuleBounds = new Rect2(bodyTransform.Origin - bodyHalf, bodyHalf * 2f);
            doorBounds = new Rect2(doorTransform.Origin - doorHalf, doorHalf * 2f);
            for (int index = 0; index < player.GetSlideCollisionCount(); index++)
            {
                KinematicCollision2D collision = player.GetSlideCollision(index);
                if (!GodotObject.IsInstanceValid(collision)) continue;
                GodotObject collider = collision.GetCollider();
                if (GodotObject.IsInstanceValid(collider) && collider == entryDoorBody) contact = true;
            }
            return true;
        }
        bool EntryDoorClear() => TryEntryDoorClearance(out Rect2 capsuleBounds,
            out Rect2 doorBounds, out bool contact) && !bodyShape.Disabled && !entryDoor.Disabled &&
            capsuleBounds.Position.X >= doorBounds.End.X + 2f && !capsuleBounds.Intersects(doorBounds) && !contact;
        bool GatesVerified() => bossBodySeen && bossTrigger.GetOverlappingBodies().Contains(player) &&
            arena.IsEncounterActive && !entryDoor.Disabled && !exitDoor.Disabled &&
            Supported(arenaFloor, arenaShape) && EntryDoorClear();
        void Cleanup(Action action)
        {
            try { action(); }
            catch (Exception error) { cleanupFailure ??= error; }
        }
        previousGuard = swapApproachGuard(Guard);
        bool clawSubscribed = false, checkpointBodySubscribed = false;
        bool checkpointSignalSubscribed = false, bossSubscribed = false;
        try
        {
            Safety(); Log("ENTRY");
            previousPreObserverGuard = swapPreObserverGuard(PreObserverSafety);
            Check(!chain.IsOpen && !chainDoor.Disabled && !level.Progress.BellChainShortcutOpen,
                "measures the actual initially closed BellChain obstruction; no manufactured closure");
            await Settle(checkpointFloor, checkpointShape);
            phase = "natural-idle";
            if (!Idle()) await WaitTask10SupportedClawReady(tree, player, monitor, observe,
                checkpointFloor, "Temple", "TASK10_TEMPLE_READY");
            Safety(); Check(Idle(), "starts E/LMB from natural target-free Idle");
            Check(target.IsAvailable && IsTargetVisible(player, target.WorldAnchor),
                "uses the exact available onscreen logical BellChain target");
            if (keyboardChain)
            {
                // W+K must remain stationary: aiming NW with A would violate that
                // original contract. Walk on the same floor before the cast instead.
                Check(bodyShape.Shape is CapsuleShape2D, "keyboard chain stance uses the actual player capsule");
                float stanceX = target.WorldAnchor.X + ((CapsuleShape2D)bodyShape.Shape).Radius + 20f;
                phase = "keyboard-chain-stance";
                int stanceWaits = 0;
                float predictedStanceStopX = float.NaN;
                int stanceForecastSteps = 0;
                while (stanceWaits < 40 && castWaits < 150 &&
                    (Mathf.Abs(player.GlobalPosition.X - stanceX) > 3f || player.Velocity.Length() > 2f))
                {
                    Check(Supported(checkpointFloor, checkpointShape),
                        "keyboard chain preparation keeps full actual CheckpointFloor support");
                    float speed = player.Velocity.X;
                    var stop = FreeMotionForecast.Neutral(speed, true, motor.MotionSettings,
                        motor.ThrusterState.Module, 1d / Engine.PhysicsTicksPerSecond,
                        Math.Min(40 - stanceWaits + 12, 150 - castWaits), 2f);
                    Check(stop.SpeedThresholdReached,
                        "keyboard chain neutral forecast fits original40+12/shared150 remaining budget");
                    predictedStanceStopX = player.GlobalPosition.X + stop.NetDistance;
                    stanceForecastSteps = stop.Steps;
                    bool right = stanceX - predictedStanceStopX > 1.5f;
                    bool left = stanceX - predictedStanceStopX < -1.5f;
                    SendAction(InputActions.MoveLeft, left);
                    SendAction(InputActions.MoveRight, right);
                    stanceWaits++; castWaits++;
                    await Tick();
                }
                SendAction(InputActions.MoveLeft, false);
                SendAction(InputActions.MoveRight, false);
                ulong stanceReleaseSequence = input.CurrentFrameSequence;
                int neutralWaits = 0;
                while (neutralWaits < 12 && castWaits < 150 &&
                    (input.CurrentFrameSequence <= stanceReleaseSequence || !Neutral()))
                { neutralWaits++; castWaits++; await Tick(); }
                GD.Print($"TASK10_TEMPLE_CHAIN_STANCE_STOP target_x={stanceX:R} player={player.GlobalPosition} " +
                    $"velocity={player.Velocity} predicted_stop_x={predictedStanceStopX:R} forecast_steps={stanceForecastSteps} " +
                    $"stance={stanceWaits}/40 neutral={neutralWaits}/12 shared={castWaits}/150 " +
                    $"sample={stanceReleaseSequence}->{input.CurrentFrameSequence} full_support={Supported(checkpointFloor, checkpointShape)}");
                Check(Mathf.Abs(player.GlobalPosition.X - stanceX) <= 3f && Neutral() &&
                    input.CurrentFrameSequence > stanceReleaseSequence && Supported(checkpointFloor, checkpointShape),
                    $"keyboard chain stance stays within3px and settles on full CheckpointFloor within shared150; " +
                    $"target_x={stanceX} position={player.GlobalPosition} velocity={player.Velocity} " +
                    $"stance_waits={stanceWaits}/40 neutral_waits={neutralWaits}/12 shared_waits={castWaits}/150");
                ulong upIssueSequence = input.CurrentFrameSequence;
                SendAction(InputActions.MoveUp, true);
                int upWaits = 0;
                while (upWaits < 8 && castWaits < 150 &&
                    (input.CurrentFrameSequence <= upIssueSequence || !input.CurrentFrame.KeyboardActions ||
                     input.KeyboardAimDirection.Dot(Vector2.Up) <= .99f))
                { upWaits++; castWaits++; await Tick(); }
                Check(input.CurrentFrameSequence > upIssueSequence && input.CurrentFrame.KeyboardActions &&
                    input.KeyboardAimDirection.Dot(Vector2.Up) > .99f && Neutral() &&
                    Supported(checkpointFloor, checkpointShape),
                    "keyboard chain preflight uses fresh actual stationary W on full CheckpointFloor within8 waits/shared150");
                phase = "natural-idle";
            }
            var chainResolver = new MechanicalClawTargetResolver();
            MechanicalClawTargetResolution resolution = keyboardChain
                ? chainResolver.ResolveKeyboard(player, input.KeyboardAimDirection)
                : chainResolver.Resolve(player, target.WorldAnchor);
            if (keyboardChain)
                GD.Print($"TASK10_TEMPLE_CHAIN_KEYBOARD_PREFLIGHT physics={Engine.GetPhysicsFrames()} " +
                    $"sample={input.CurrentFrameSequence} position={player.GlobalPosition} velocity={player.Velocity} " +
                    $"move={input.CurrentFrame.MoveAxis} direction={input.KeyboardAimDirection} " +
                    $"selected={resolution.Surface?.GetPath()} selected_id={resolution.Snapshot.RuntimeId} " +
                    $"material={resolution.Snapshot.Material} anchor={resolution.Snapshot.WorldAnchor} " +
                    $"los={resolution.Snapshot.HasLineOfSight} exact={resolution.Surface == target} " +
                    $"checkpoint_full={Supported(checkpointFloor, checkpointShape)} " +
                    $"hp={hp}->{health.CurrentHealth} recovery={requests}/{recoveries}->" +
                    $"{monitor.RecoveryRequested}/{monitor.RecoveryCompleted} shared_waits={castWaits}/150");
            Check(resolution.Surface == target && resolution.Snapshot.Exists &&
                resolution.Snapshot.RuntimeId == targetId && resolution.Snapshot.IsLegacyInteraction &&
                resolution.Snapshot.HasLineOfSight && resolution.Snapshot.WorldAnchor == target.WorldAnchor &&
                player.GlobalPosition.DistanceTo(target.WorldAnchor) <= MechanicalClawSettings.Default.MaxRange,
                "requires the original exact resolver, real LOS and cast range");
            GD.Print($"TASK10_TEMPLE_CHAIN_PREFLIGHT target={target.GetPath()} target_id={targetId} " +
                $"adapter_id={adapter.GetInstanceId()} available={target.IsAvailable} aim={target.WorldAnchor} " +
                $"logical_aim={ToViewport(player, target.WorldAnchor)} onscreen=True los={resolution.Snapshot.HasLineOfSight} " +
                $"distance={player.GlobalPosition.DistanceTo(target.WorldAnchor)} max_range={MechanicalClawSettings.Default.MaxRange} " +
                $"initial_open={chain.IsOpen} initial_door_disabled={chainDoor.Disabled} applications={applications}");
            claw.ClawFrameChanged += ObserveCast; clawSubscribed = true;
            phase = "chain-cast";
            eIssueSequence = input.CurrentFrameSequence;
            Vector2 chainAim = target.WorldAnchor;
            MoveMouse(player, chainAim);
            SendAction(InputActions.SelectGrappleMode, true);
            try
            {
                if (keyboardChain)
                {
                    await Tick(); castWaits++; eSamplingWaits++;
                    keyboardReadySequence = input.CurrentFrameSequence;
                    Check(!input.CurrentFrame.GrappleModePressed && !input.CurrentFrame.AttackModePressed &&
                        !Input.IsActionPressed(InputActions.Claw) && !Input.IsActionPressed(InputActions.Attack) &&
                        input.CurrentFrame.MoveAxis == 0f && player.Velocity.Length() <= 2f,
                        "keyboard chain readiness has no E/Q/J/K edge or horizontal motion");
                }
                while (eSamplingWaits < 8 && castWaits < 150 && !ESampleReady())
                {
                    eSamplingWaits++; castWaits++;
                    await Tick();
                    if (sampledE == 0UL && input.CurrentFrameSequence > eIssueSequence &&
                        input.CurrentFrame.GrappleModePressed) sampledE = input.CurrentFrameSequence;
                    SamplingLog("E_OBSERVED");
                }
                SamplingLog(ESampleReady() ? "E_READY" : "E_TIMEOUT", terminal: true);
                Check(ESampleReady(),
                    "witnesses typed keyboard target readiness or fresh legacy E, natural Idle and actual matching aim within8 waits/shared150");
            }
            catch (Exception error) { firstFailure = error; throw; }
            finally
            {
                if (firstFailure != null) Cleanup(() => SendAction(InputActions.SelectGrappleMode, false));
                else SendAction(InputActions.SelectGrappleMode, false);
            }
            primaryIssueSequence = input.CurrentFrameSequence;
            Check(keyboardChain ? primaryIssueSequence >= keyboardReadySequence && keyboardReadySequence > eIssueSequence
                : primaryIssueSequence > sampledE, "issues one typed K or legacy LMB after actual readiness");
            casting = true;
            SendMouse(MouseButton.Left, true, player, chainAim);
            try
            {
                while (primarySamplingWaits < 8 && castWaits < 150 && !PrimarySampleReady())
                {
                    primarySamplingWaits++; castWaits++;
                    await Tick();
                    SamplingLog("PRIMARY_OBSERVED");
                }
                SamplingLog(PrimarySampleReady() ? "PRIMARY_READY" : "PRIMARY_TIMEOUT", terminal: true);
                Check(PrimarySampleReady(), "witnesses exactly one fresh sampled LMB after its issue and E sequences within8 waits/shared150");
            }
            catch (Exception error) { firstFailure = error; throw; }
            finally
            {
                if (firstFailure != null) Cleanup(() => SendMouse(MouseButton.Left, false, player, chainAim));
                else SendMouse(MouseButton.Left, false, player, chainAim);
            }
            while (castWaits < 150 && !(chain.IsOpen && chainDoor.Disabled && Idle() && idleSeen))
            { await Tick(); castWaits++; }
            Safety();
            Check(chain.IsOpen && chainDoor.Disabled && level.Progress.BellChainShortcutOpen &&
                adapter.ApplicationCount == applications + 1 && claw.CurrentFrame.NextCastId == nextCast + 1UL &&
                travelSeen && latchedSeen && releasedSeen && idleSeen && Idle() && primarySamples == 1,
                "proves exact Travel/Latched/Released/Idle, one accepted application and deferred open door within 150 waits");
            if (keyboardChain) SendAction(InputActions.MoveUp, false);
            casting = false; chainComplete = true; Log("CHAIN_OPEN");
            checkpoint.BodyEntered += OnCheckpointBody; checkpointBodySubscribed = true;
            checkpoint.CheckpointActivated += OnCheckpointSignal; checkpointSignalSubscribed = true;
            phase = "checkpoint-walk";
            await PrologueCanyonTraversalTests.Task4WalkTo(tree, player, 5920f, 100);
            for (int waited = 0; waited < 12 &&
                level.Progress.RestoreCheckpoint().CheckpointId != "canyon.v2.temple-forecourt"; waited++) await Tick();
            Safety();
            PrologueCheckpointSnapshot actual = level.Progress.RestoreCheckpoint();
            Check(checkpointBodySeen && checkpointSignalSeen && checkpointBodies == 1 && checkpointSignals == 1 &&
                actual.HasActivatedCheckpoint && actual.CheckpointId == "canyon.v2.temple-forecourt" &&
                actual.SectorId == PrologueSectorId.LostTemple && actual.WorldPosition == new Vector2(5920f, 1080f) &&
                world.CheckpointId == "canyon.v2.temple-forecourt" && world.CurrentSector == PrologueSectorId.LostTemple &&
                checkpoint.GetOverlappingBodies().Contains(player) && Supported(checkpointFloor, checkpointShape),
                "requires exact player trigger/signal, Temple identity/position and full CheckpointFloor support");
            Check(flow.Save.Version == PrologueSaveData.CurrentVersion && flow.Save.LayoutVersion == 2 && world.LayoutVersion == 2 &&
                flow.Save.HasActivatedCheckpoint && flow.Save.CheckpointId == "canyon.v2.temple-forecourt" &&
                flow.Save.CheckpointSector == "LostTemple" && flow.Save.CheckpointWorldPosition == new Vector2(5920f, 1080f),
                "requires normal checkpoint persistence in the actual live flow save");
            byte[] saveBytes = File.ReadAllBytes(flow.SavePath);
            using (System.Text.Json.JsonDocument disk = System.Text.Json.JsonDocument.Parse(saveBytes))
            {
                System.Text.Json.JsonElement saved = disk.RootElement;
                Check(saved.GetProperty("version").GetInt32() == PrologueSaveData.CurrentVersion && saved.GetProperty("layoutVersion").GetInt32() == 2 &&
                    saved.GetProperty("hasActivatedCheckpoint").GetBoolean() &&
                    saved.GetProperty("checkpointId").GetString() == "canyon.v2.temple-forecourt" &&
                    saved.GetProperty("checkpointSector").GetString() == "LostTemple" &&
                    saved.GetProperty("checkpointWorldX").GetSingle() == 5920f &&
                    saved.GetProperty("checkpointWorldY").GetSingle() == 1080f,
                    "requires current save schema/layout2 and exact Temple checkpoint in actual disk JSON");
            }
            Log("REAL_CHECKPOINT"); Safety();
            Check(!arena.IsEncounterActive, "takes actual disk bytes strictly before Boss activation");
            using (FileStream snapshot = new(templeCheckpointSnapshotPath, FileMode.CreateNew, System.IO.FileAccess.Write, FileShare.None))
            { snapshot.Write(saveBytes, 0, saveBytes.Length); snapshot.Flush(flushToDisk: true); }
            byte[] retainedBytes = File.ReadAllBytes(templeCheckpointSnapshotPath);
            Check(retainedBytes.SequenceEqual(saveBytes), "re-reads byte-identical exclusive pre-Boss evidence snapshot");
            GD.Print($"TASK10_TEMPLE_SNAPSHOT path={templeCheckpointSnapshotPath} " +
                $"sha256={Convert.ToHexString(SHA256.HashData(retainedBytes))} length={retainedBytes.Length} boss_active=False");
            if (naturalRoute != null)
            {
                Check(variant == Task10RouteVariant.Main && keyboardChain,
                    "natural missing-quota scenario owns only the original keyboard Main driver");
                checkpoint.BodyEntered -= OnCheckpointBody; checkpointBodySubscribed = false;
                checkpoint.CheckpointActivated -= OnCheckpointSignal; checkpointSignalSubscribed = false;
                claw.ClawFrameChanged -= ObserveCast; clawSubscribed = false;
                swapPreObserverGuard(previousPreObserverGuard);
                swapApproachGuard(previousGuard);
                Exception detourFailure = null;
                try
                {
                    NaturalFragmentReceipt receipt = await DriveNaturalFragmentReturn(tree, level,
                        world, player, monitor, observe, swapApproachGuard, swapPreObserverGuard,
                        templeCheckpointSnapshotPath);
                    Check(receipt.PlayerId == playerId && receipt.BossId == bossId &&
                        receipt.EntryHp == hp && receipt.ExitHp == hp &&
                        receipt.EntryNextCast == nextCast + 1 && receipt.ExitNextCast == nextCast + 2 &&
                        receipt.Jumps == jumps && receipt.Dashes == dashes &&
                        receipt.Requests == requests && receipt.Recoveries == recoveries &&
                        receipt.ChainApplications == applications + 1,
                        "natural fragment-only receipt preserves entry identity/HP/actions and exactly one beam cast");
                    naturalRoute.Receipt = receipt;
                    nextCast = receipt.ExitNextCast - 1;
                }
                catch (Exception error) { detourFailure = error; throw; }
                finally
                {
                    var failures = new List<Exception>();
                    void Restore(Action action) { try { action(); } catch (Exception error) { failures.Add(error); } }
                    Restore(() => swapApproachGuard(Guard));
                    Restore(() => swapPreObserverGuard(PreObserverSafety));
                    Restore(() => { if (GodotObject.IsInstanceValid(claw))
                        { claw.ClawFrameChanged += ObserveCast; clawSubscribed = true; } });
                    if (failures.Count != 0)
                    {
                        if (detourFailure != null) failures.Insert(0, detourFailure);
                        throw new AggregateException("Natural fragment scope restoration", failures);
                    }
                }
                Safety(); Guard();
            }
            if (variant == Task10RouteVariant.Exploration)
            {
                // Close first-entry attribution before physical checkpoint re-entry. These
                // listeners are local evidence only; production checkpoint binding remains.
                checkpoint.BodyEntered -= OnCheckpointBody; checkpointBodySubscribed = false;
                checkpoint.CheckpointActivated -= OnCheckpointSignal; checkpointSignalSubscribed = false;
                claw.ClawFrameChanged -= ObserveCast; clawSubscribed = false;
                swapPreObserverGuard(previousPreObserverGuard);
                swapApproachGuard(previousGuard);
                Exception supplyFailure = null;
                try
                {
                    const string supplyFragmentId = "canyon.v2.fragment.temple-upper";
                    const string supplyRewardId = "canyon.v2.reward.temple-supply";
                    var supplyFragment = temple.GetNode<Knight.Prologue.Collections.QuestFragment>("Gameplay/QuestFragments/temple-upper");
                    var supplyFragmentShape = supplyFragment.GetNode<CollisionShape2D>("Collision");
                    var supplyHud = level.GetNode<PrologueFormalHud>("Hud/FormalHud");
                    Check(new Node[] { supplyFragment, supplyFragmentShape, supplyHud }.All(Live) &&
                        GodotObject.IsInstanceValid(supplyFragmentShape.Shape) && supplyFragmentShape.Shape is CircleShape2D,
                        "retains native fragment/shape/HUD before optional detour handoff");
                    ulong supplyFragmentNodeId = supplyFragment.GetInstanceId();
                    ulong supplyFragmentShapeId = supplyFragmentShape.Shape.GetInstanceId();
                    int supplyFragmentFeedback = supplyFragment.FeedbackCount;
                    PrologueSaveData supplyBaseline = Task18RawSave(retainedBytes), supplyEntrySave = flow.Save;
                    string supplyEntryIds = Task18Ids(supplyBaseline.CollectedFragmentIds);
                    string supplyExitIds = Task18Ids(supplyBaseline.CollectedFragmentIds.Append(supplyFragmentId));
                    string supplyEntryDiscoveries = Task18Ids(supplyBaseline.Discoveries);
                    Check(supplyFragment.StableId == supplyFragmentId && !supplyFragment.IsCollected &&
                        !supplyBaseline.CollectedFragmentIds.Contains(supplyFragmentId) &&
                        !supplyBaseline.Discoveries.Contains(supplyRewardId) &&
                        Task18Ids(level.Progress.CollectedFragmentIds) == supplyEntryIds &&
                        Task18SaveExact(supplyEntrySave, supplyBaseline, supplyEntryIds, supplyEntryDiscoveries),
                        "captures independent original fragment/save values, not arbitrary current-save rebasing");
                    Task18NormalSupplyReceipt supply = await DriveTask18NormalTempleSupply(tree,
                        level, world, player, monitor, observe, swapApproachGuard,
                        swapPreObserverGuard, templeCheckpointSnapshotPath);
                    Check(supply.PlayerId == playerId && supply.BossId == bossId &&
                        supply.EntryHp == hp && supply.MaxHp == health.MaxHealth &&
                        supply.ExitHp == Math.Min(supply.MaxHp, hp + 2) &&
                        supply.EntryNextCast == nextCast + 1UL &&
                        supply.ExitNextCast == supply.EntryNextCast + 1UL &&
                        supply.Requests == requests && supply.Recoveries == recoveries &&
                        supply.Jumps == jumps && supply.Dashes == dashes &&
                        supply.ChainApplications == applications + 1 && supply.HealedEvents == 1 &&
                        supply.BoostEvents == 1 && supply.ReleaseEvents == 1 &&
                        supply.SnapshotHash == Convert.ToHexString(SHA256.HashData(retainedBytes)),
                        "validates immutable optional supply identity/HP/cast/action/event deltas before restoring chain-only guards");
                    Task18FragmentReceipt collected = supply.Fragment;
                    Check(new Node[] { supplyFragment, supplyFragmentShape, supplyHud }.All(Live) &&
                        GodotObject.IsInstanceValid(supplyFragmentShape.Shape) &&
                        collected.StableId == supplyFragmentId && collected.NodeId == supplyFragmentNodeId &&
                        supplyFragment.GetInstanceId() == supplyFragmentNodeId &&
                        collected.ShapeId == supplyFragmentShapeId && supplyFragmentShape.Shape.GetInstanceId() == supplyFragmentShapeId &&
                        supplyFragmentShape.Shape is CircleShape2D { Radius: 18 } && !supplyFragmentShape.Disabled &&
                        collected.WorldPosition == new Vector2(5896, 924) && supplyFragment.GlobalPosition == collected.WorldPosition &&
                        collected.Radius == 18 && collected.EntryIds == supplyEntryIds && collected.ExitIds == supplyExitIds &&
                        collected.EntryCount == supplyBaseline.CollectedFragmentIds.Count && collected.ExitCount == collected.EntryCount + 1 &&
                        collected.EntryFeedback == supplyFragmentFeedback && collected.ExitFeedback == supplyFragmentFeedback + 1 &&
                        supplyFragment.FeedbackCount == collected.ExitFeedback && supplyFragment.IsCollected &&
                        supplyFragment.LastResult == Knight.Prologue.Collections.FragmentCollectionResult.Collected &&
                        collected.CollectionBodyEntries == 1 && collected.ReturnBodyEntries == 1 && collected.CollectedEvents == 1 &&
                        collected.SaveReplacements == 1 && collected.CollectionBodyPlayerId == playerId && collected.ReturnBodyPlayerId == playerId &&
                        collected.CollectionDiskHash.Length == 64 && collected.CollectionDiskHash.All(Uri.IsHexDigit) &&
                        collected.CollectionDiskHash != supply.SnapshotHash && !ReferenceEquals(flow.Save, supplyEntrySave),
                        "value-only receipt proves exact original fragment/node/resource, one collection and a separate non-consuming return entry");
                    string supplyExitDiscoveries = Task18Ids(supplyBaseline.Discoveries.Append(supplyRewardId));
                    Check(Task18SaveExact(supplyEntrySave, supplyBaseline, supplyEntryIds, supplyEntryDiscoveries) &&
                        Task18SaveExact(flow.Save, supplyBaseline, supplyExitIds, supplyExitDiscoveries) &&
                        Task18SaveExact(Task18RawSave(File.ReadAllBytes(flow.SavePath)), supplyBaseline, supplyExitIds, supplyExitDiscoveries) &&
                        Task18Ids(level.Progress.CollectedFragmentIds) == supplyExitIds &&
                        Task18Ids(level.Progress.Discoveries) == supplyExitDiscoveries &&
                        level.Progress.CollectionRuleVersion == supplyBaseline.CollectionRuleVersion &&
                        !level.Progress.LegacyCollectionQuotaExempt && supplyHud.CurrentModel.FragmentCount == collected.ExitCount &&
                        supplyHud.CurrentModel.FragmentRequired == 6 && !supplyHud.CurrentModel.CollectionQuotaExempt &&
                        retainedBytes.SequenceEqual(File.ReadAllBytes(templeCheckpointSnapshotPath)),
                        "caller independently verifies raw disk/live/progress/HUD sole fragment +1 and witnessed reward +1, preserving every other snapshot value");
                    hp = supply.ExitHp;
                    nextCast = supply.ExitNextCast - 1UL;
                }
                catch (Exception error) { supplyFailure = error; throw; }
                finally
                {
                    // Restore even on a detour exception, without waiting or reading components.
                    var restoreFailures = new List<Exception>();
                    void Restore(Action action) { try { action(); } catch (Exception error) { restoreFailures.Add(error); } }
                    Restore(() => swapApproachGuard(Guard));
                    Restore(() => swapPreObserverGuard(PreObserverSafety));
                    Restore(() => { if (GodotObject.IsInstanceValid(claw))
                        { claw.ClawFrameChanged += ObserveCast; clawSubscribed = true; } });
                    if (restoreFailures.Count != 0)
                    {
                        if (supplyFailure != null) restoreFailures.Insert(0, supplyFailure);
                        throw new AggregateException("Task18 normal supply scope restoration", restoreFailures);
                    }
                }
                Safety(); Guard();
            }
            phase = "arena-stage";
            await PrologueCanyonTraversalTests.Task4WalkTo(tree, player, 6160f, 100);
            await Settle(arenaFloor, arenaShape);
            Safety();
            Check(Supported(arenaFloor, arenaShape) && !arena.IsEncounterActive &&
                !bossTrigger.GetOverlappingBodies().Contains(player), "stages on full enabled ArenaFloor before actual trigger");
            Check(bodyShape.Shape is CapsuleShape2D && bossTriggerShape.Shape is RectangleShape2D,
                "requires actual capsule and rectangular trigger geometry");
            CapsuleShape2D stagedCapsule = (CapsuleShape2D)bodyShape.Shape;
            RectangleShape2D triggerRect = (RectangleShape2D)bossTriggerShape.Shape;
            float stagedRight = bodyShape.ToGlobal(new Vector2(stagedCapsule.Radius, 0f)).X;
            float triggerLeft = bossTriggerShape.ToGlobal(new Vector2(-triggerRect.Size.X / 2f, 0f)).X;
            Check(!bossTriggerShape.Disabled && bossTrigger.Monitoring &&
                stagedRight < triggerLeft,
                "measures a real capsule-to-enabled-trigger margin after neutral staging");
            Log("PRETRIGGER");
            GD.Print($"TASK10_TEMPLE_PRETRIGGER capsule_right={stagedRight} trigger_left={triggerLeft} " +
                $"margin={triggerLeft - stagedRight} actual_overlap=False boss_active=False neutral=True");
            bossTrigger.BodyEntered += OnBossBody; bossSubscribed = true;
            phase = "boss-approach";
            SendAction(InputActions.MoveLeft, false); SendAction(InputActions.MoveRight, true);
            int approachWaits = 0;
            while (approachWaits < 50 && (!arena.IsEncounterActive || !EntryDoorClear()) && player.GlobalPosition.X < 6260f)
            { await Tick(); approachWaits++; }
            SendAction(InputActions.MoveRight, false);
            Safety(); Check(bossBodySeen && arena.IsEncounterActive && EntryDoorClear(),
                "real ordinary walking toward6260 enters the exact Boss trigger and clears the live enabled EntryDoor by2px without contact within50 waits");
            phase = "boss-gates";
            for (int waited = 0; waited < 12 && !GatesVerified(); waited++) await Tick();
            Safety(); Check(GatesVerified(), "requires actual player overlap, active same Boss, full ArenaFloor, deferred enabled gates and whole-capsule EntryDoor clearance without contact/overlap within12 waits");
            phase = "activation"; Log("ACTIVATION");
        }
        catch (Exception error)
        {
            firstFailure = error; Log("FAILURE");
            SamplingLog("FAILURE", terminal: true);
            try { GD.Print($"TASK10_TEMPLE_ENTRY_FAILURE type={error.GetType().Name} " +
                $"message={error.Message.Replace('\r', ' ').Replace('\n', ' ')}"); } catch { }
            throw;
        }
        finally
        {
            Cleanup(() => { if (clawSubscribed && GodotObject.IsInstanceValid(claw)) claw.ClawFrameChanged -= ObserveCast; });
            Cleanup(() => { if (checkpointBodySubscribed && GodotObject.IsInstanceValid(checkpoint)) checkpoint.BodyEntered -= OnCheckpointBody; });
            Cleanup(() => { if (checkpointSignalSubscribed && GodotObject.IsInstanceValid(checkpoint)) checkpoint.CheckpointActivated -= OnCheckpointSignal; });
            Cleanup(() => { if (bossSubscribed && GodotObject.IsInstanceValid(bossTrigger)) bossTrigger.BodyEntered -= OnBossBody; });
            Cleanup(() => ReleaseAll(Live(player) ? player.GlobalPosition : Vector2.Zero));
            Cleanup(() => swapPreObserverGuard(previousPreObserverGuard));
            Cleanup(() => swapApproachGuard(previousGuard));
            if (cleanupFailure != null && firstFailure != null)
                try { GD.Print($"TASK10_TEMPLE_ENTRY_CLEANUP_GAP type={cleanupFailure.GetType().Name}"); } catch { }
        }
        if (cleanupFailure != null) throw cleanupFailure;
    }

    private static async Task DriveTask10BossPhaseOnePositional(SceneTree tree,
        PrologueLevelController level, SeamlessPrologueWorld world, CharacterBody2D player,
        RouteMonitor monitor, Action observe, Func<Action, Action> swapApproachGuard,
        Func<Action, Action> swapPreObserverGuard)
    {
        // Test-only continuation of the real route: positions are candidate goals, never
        // damage geometry or an alternative authority for the production actor timeline.
        bool Live(Node node) => node != null && GodotObject.IsInstanceValid(node) &&
            node.IsInsideTree() && !node.IsQueuedForDeletion();
        void Check(bool condition, string message) => TestAssert.True(condition,
            "Task10 Boss phase1 positional: " + message);
        Check(GodotObject.IsInstanceValid(tree) && Live(level) && Live(world) &&
            Live(player) && Live(monitor.Player), "requires live original route nodes");
        Check(world.TryGetMountedSector(PrologueSectorId.LostTemple, out PrologueSector temple) &&
            Live(temple), "requires actually mounted LostTemple");
        PrologueGameFlowController flow = level.GetNode<PrologueGameFlowController>("GameFlow");
        BossArenaController arena = temple.GetNode<BossArenaController>("Gameplay/BossArenaController");
        Check(Live(arena), "requires actual arena before reading its Boss");
        FallenBellkeeper boss = arena.CurrentBoss;
        Check(Live(boss), "requires actual spawned Boss");
        HealthComponent health = player.GetNode<HealthComponent>("Health");
        HealthComponent bossHealth = boss.GetNode<HealthComponent>("Health");
        Hurtbox bossHurtbox = boss.GetNode<Hurtbox>(boss.HurtboxPath);
        PlayerMotor motor = player.GetNode<PlayerMotor>("Motor");
        PlayerInputReader input = player.GetNode<PlayerInputReader>("Input");
        PlayerCombat combat = player.GetNode<PlayerCombat>("Combat");
        PlayerActionModeController modes = player.GetNode<PlayerActionModeController>("ActionModes");
        PlayerEnergyController energy = player.GetNode<PlayerEnergyController>("Energy");
        PlayerShieldController shield = player.GetNode<PlayerShieldController>("Shield");
        MechanicalClawController claw = player.GetNode<MechanicalClawController>("MechanicalClaw");
        StaticBody2D floor = temple.GetNode<StaticBody2D>("Gameplay/Collision/ArenaFloor");
        Check(Live(floor), "live actual ArenaFloor before collision lookup");
        CollisionShape2D floorShape = floor.GetNode<CollisionShape2D>("Collision");
        CollisionShape2D bodyShape = player.GetNode<CollisionShape2D>("BodyCollider");
        CollisionShape2D entryDoor = arena.GetNode<CollisionShape2D>(arena.EntryDoorCollisionPath);
        CollisionShape2D exitDoor = arena.GetNode<CollisionShape2D>(arena.ExitDoorCollisionPath);
        Node[] nodes = { level, world, temple, flow, arena, boss, player, monitor.Player,
            health, bossHealth, bossHurtbox, motor, input, combat, modes, energy, shield,
            claw, floor, floorShape, bodyShape, entryDoor, exitDoor };
        Check(nodes.All(Live), "requires live original components before baseline reads");
        Check(GodotObject.IsInstanceValid(combat.Tuning) && GodotObject.IsInstanceValid(motor.Tuning),
            "live actual combat/motion tuning before duration/braking reads");
        ulong playerId = player.GetInstanceId(), bossId = boss.GetInstanceId();
        int hp = health.CurrentHealth, requests = monitor.RecoveryRequested;
        int recoveries = monitor.RecoveryCompleted, jumps = motor.AcceptedJumpCount;
        int dashes = motor.AcceptedDashCount;
        ulong nextCast = claw.CurrentFrame.NextCastId;
        Check(hp > 0 && bossHealth.CurrentHealth == 12 && bossHealth.MaxHealth == 12 &&
            boss.CurrentFrame.State == FallenBellkeeperState.Intro,
            $"requires genuine positive entry HP and Boss12/12 Intro; playerHP={hp} " +
            $"BossHP={bossHealth.CurrentHealth}/{bossHealth.MaxHealth} state={boss.CurrentFrame.State}");
        Check(player.GlobalPosition.IsFinite() && boss.GlobalPosition.IsFinite(), "finite entry poses");
        int flank = player.GlobalPosition.X < boss.GlobalPosition.X ? -1 : 1;
        int inward = -flank, waits = 0, damageHits = 0, pairedHits = 0, accepted = 0;
        int damageEvents = 0, healEvents = 0, deathEvents = 0;
        int lastBossHp = 12, primarySamples = 0;
        ulong pendingId = 0, pendingSweep = 0, issuedSweep = 0, primaryIssueSequence = 0;
        ulong primarySampleSequence = 0, qIssueSequence = 0, qSampleSequence = 0;
        bool keyboardPhaseOne = KeyboardRouteInputDriver.Current != null;
        ulong keyboardAttackReady = 0UL;
        ulong pendingStartPhysics = 0, lastInwardSequence = 0, lastOutwardSequence = 0;
        bool pendingDamage = false, pendingConnect = false, pendingPaired = false;
        bool primaryIssued = false, primaryHeld = false, selecting = false;
        bool retreating = false, connectRetreatStarted = false, subscribed = false;
        bool scopeInstalled = false, preScopeInstalled = false;
        int commandedMove = 0;
        AttackPresentationFrame presentation = default;
        ulong publication = 0, completedPublication = 0;
        ulong loggedAttack = 0;
        AttackPhase loggedPhase = AttackPhase.None;
        bool loggedLock = false;
        ulong lockedSlamId = 0;
        Vector2 lockedSlamTarget = Vector2.Zero;
        string stage = "entry";
        Exception callbackFailure = null, firstFailure = null, cleanupFailure = null;
        Action previousGuard = null, previousPreObserverGuard = null;
        float attackSeconds = combat.Tuning.AttackStartupSeconds + combat.Tuning.AttackActiveSeconds +
            combat.Tuning.AttackRecoverySeconds;
        Check(float.IsFinite(attackSeconds) && attackSeconds > 0f && Engine.PhysicsTicksPerSecond > 0,
            "positive actual attack interval/physics rate");
        int attackInterval = (int)MathF.Ceiling(attackSeconds * Engine.PhysicsTicksPerSecond) + 4;

        Rect2 Bounds(CollisionShape2D shape)
        {
            Check(Live(shape) && GodotObject.IsInstanceValid(shape.Shape), "live bounds authority");
            Transform2D transform = shape.GlobalTransform;
            Check(transform.Origin.IsFinite() && transform.X.IsFinite() && transform.Y.IsFinite(),
                "finite transformed bounds");
            Rect2 local = shape.Shape.GetRect();
            Rect2 bounds = new(transform * local.Position, Vector2.Zero);
            foreach (Vector2 corner in new[] { new Vector2(local.End.X, local.Position.Y),
                local.End, new Vector2(local.Position.X, local.End.Y) }) bounds = bounds.Expand(transform * corner);
            Check(bounds.Position.IsFinite() && bounds.Size.IsFinite(), "finite world bounds");
            return bounds;
        }
        bool Supported()
        {
            if (!TryTask10CapsuleCorridor(player, floorShape, out _, out _, out _, out _) ||
                !player.IsOnFloor()) return false;
            bool contact = false;
            for (int index = 0; index < player.GetSlideCollisionCount(); index++)
            {
                KinematicCollision2D collision = player.GetSlideCollision(index);
                if (!GodotObject.IsInstanceValid(collision)) continue;
                GodotObject collider = collision.GetCollider();
                if (!GodotObject.IsInstanceValid(collider)) continue;
                Check(collider != entryDoor.GetParent() && collider != exitDoor.GetParent() && collider != boss,
                    "no closed-door or Boss slide contact");
                if (collider == floor && collision.GetNormal().Y < -.7f) contact = true;
            }
            return contact;
        }
        float Gap() => flank * (player.GlobalPosition.X - boss.GlobalPosition.X);
        bool CurrentPresentation()
        {
            AttackTimelineFrame raw = boss.CurrentFrame.AttackTimeline;
            AttackTimelineFrame actual = presentation.Timeline;
            return publication > 0 && completedPublication == publication &&
                actual.AttackId == raw.AttackId && actual.Kind == raw.Kind && actual.Phase == raw.Phase &&
                actual.PhaseRemainingSeconds == raw.PhaseRemainingSeconds;
        }
        float Clearance()
        {
            Check(CurrentPresentation(), "uses only completed current actor presentation");
            AttackShapeFrame shape = presentation.Shape;
            Check(shape.Origin.IsFinite() && shape.Extent.IsFinite() &&
                float.IsFinite(shape.RotationRadians), "finite actual attack geometry");
            if (presentation.Timeline.Kind == EnemyAttackKind.BossLeapSlam)
            {
                Check(shape.Kind == AttackShapeKind.Circle && shape.Extent.X > 0f,
                    "actual Slam circle authority");
                return Mathf.Abs(player.GlobalPosition.X - shape.Origin.X) - shape.Extent.X - 28f;
            }
            float left, right;
            if (presentation.Timeline.Kind == EnemyAttackKind.BossSweep)
            {
                Check(shape.Kind == AttackShapeKind.ConvexPolygon && shape.Points != null &&
                    shape.Points.Count >= 3 && shape.Points.All(point => point.IsFinite()),
                    "actual world-space Sweep polygon authority");
                left = shape.Points.Min(point => point.X); right = shape.Points.Max(point => point.X);
            }
            else
            {
                Check(presentation.Timeline.Kind == EnemyAttackKind.BossGroundWave &&
                    shape.Kind == AttackShapeKind.GroundBand && shape.Extent.X > 0f && shape.Extent.Y > 0f,
                    "actual Wave band authority");
                float half = Mathf.Abs(Mathf.Cos(shape.RotationRadians)) * shape.Extent.X +
                    Mathf.Abs(Mathf.Sin(shape.RotationRadians)) * shape.Extent.Y;
                left = shape.Origin.X - half; right = shape.Origin.X + half;
            }
            return flank < 0 ? left - player.GlobalPosition.X - 28f : player.GlobalPosition.X - right - 28f;
        }
        void Safety()
        {
            Check(GodotObject.IsInstanceValid(tree) && nodes.All(Live), "native lifetime before reads/waits");
            Check(new[] { floorShape, bodyShape, entryDoor, exitDoor }.All(shape =>
                GodotObject.IsInstanceValid(shape.Shape)), "live collision resources");
            Check(GodotObject.IsInstanceValid(motor.Tuning), "live braking resource before policy reads");
            Check(player.GetInstanceId() == playerId && monitor.Player.GetInstanceId() == playerId &&
                boss.GetInstanceId() == bossId && arena.CurrentBoss == boss && arena.IsEncounterActive &&
                flow.State == PrologueGameFlowState.Playing && !tree.Paused,
                "same player/Boss and active Playing arena");
            Check(health.CurrentHealth == hp && monitor.RecoveryRequested == requests &&
                monitor.RecoveryCompleted == recoveries && motor.AcceptedJumpCount == jumps &&
                motor.AcceptedDashCount == dashes && damageEvents == 0 && healEvents == 0 && deathEvents == 0,
                "no player damage/heal/death/recovery/jump/dash");
            Check(player.GlobalPosition.IsFinite() && player.Velocity.IsFinite() &&
                boss.GlobalPosition.IsFinite() && boss.Velocity.IsFinite() && Gap() > 60f &&
                float.IsFinite(energy.EnergyRatio) && float.IsFinite(energy.HeatRatio),
                "finite same-flank poses/resources; no crossing Boss");
            Check(!floorShape.Disabled && !bodyShape.Disabled && !entryDoor.Disabled && !exitDoor.Disabled &&
                bodyShape.Shape is CapsuleShape2D capsule && Mathf.Abs(capsule.Radius *
                    bodyShape.GlobalTransform.X.Length() - 20f) < .01f && Supported(),
                "actual full ArenaFloor/contact, enabled gates and 20px player halfwidth");
            Rect2 body = Bounds(bodyShape), entry = Bounds(entryDoor), exit = Bounds(exitDoor);
            Check(body.Position.X >= entry.End.X + 2f && body.End.X <= exit.Position.X - 2f &&
                !body.Intersects(entry) && !body.Intersects(exit), "whole-capsule closed-door containment");
            Check(!input.CurrentFrame.JumpPressed && !input.CurrentFrame.JumpHeld &&
                !input.CurrentFrame.DashPressed && !input.CurrentFrame.ShieldHeld &&
                !input.CurrentFrame.GrappleModePressed && !input.CurrentFrame.ThreadPressed &&
                !input.CurrentFrame.ThreadHeld && !input.CurrentFrame.ThreadReleased &&
                (!input.CurrentFrame.AttackPressed || keyboardPhaseOne && primaryIssued &&
                    input.CurrentFrameSequence > primaryIssueSequence &&
                    (primaryHeld || input.CurrentFrameSequence == primarySampleSequence)) &&
                (!keyboardPhaseOne || !input.CurrentFrame.ClawPressed && !input.CurrentFrame.InteractPressed) &&
                input.CurrentFrame.Aim.Y == 0f && !shield.IsActive &&
                claw.CurrentFrame.State == MechanicalClawState.Idle && claw.CurrentFrame.CastId == 0 &&
                claw.CurrentFrame.NextCastId == nextCast && claw.CurrentTarget == null && claw.ResidencyTarget == null,
                "no shield/legacy attack/vertical aim/E/claw cast or target");
            Check(bossHealth.MaxHealth == 12 && bossHealth.CurrentHealth == lastBossHp &&
                lastBossHp == 12 - damageHits && damageHits <= 5 && accepted <= 5 && pairedHits <= damageHits &&
                !boss.CurrentFrame.ArmorClosed && boss.CurrentFrame.State is FallenBellkeeperState.Intro or
                    FallenBellkeeperState.PhaseOne or FallenBellkeeperState.Transition,
                "exact Boss12→7 trajectory, at most five accepted strikes, no phase2");
            if (callbackFailure != null) throw new InvalidOperationException(
                "Task10 Boss phase1 callback failure", callbackFailure);
        }
        void Log(string boundary, string details = "")
        {
            // Deliberately no diagnostic native reads until their lifetime is validated.
            Check(nodes.All(Live), "live nodes before compact record");
            AttackTimelineFrame timeline = presentation.Timeline;
            string clearance = CurrentPresentation() && timeline.Phase != AttackPhase.None
                ? Clearance().ToString("R") : "unavailable";
            GD.Print($"TASK10_BOSS_PHASE1 boundary={boundary} stage={stage} physics={Engine.GetPhysicsFrames()} " +
                $"input_sequence={input.CurrentFrameSequence} waits={waits}/1800 player={playerId} boss={bossId} " +
                $"pose={player.GlobalPosition} velocity={player.Velocity} boss_pose={boss.GlobalPosition} " +
                $"full_floor={Supported()} HP={health.CurrentHealth}/{hp} energy={energy.EnergyRatio:R} " +
                $"heat={energy.HeatRatio:R} overheated={energy.IsOverheated} bossHP={bossHealth.CurrentHealth} " +
                $"state={boss.CurrentFrame.State} attack={timeline.AttackId}/{timeline.Kind}/{timeline.Phase} " +
                $"remaining={timeline.PhaseRemainingSeconds:R} locked={timeline.HasLockedTarget} " +
                $"target={timeline.LockedWorldTarget} clearance={clearance} shield={shield.IsActive} " +
                $"mode={modes.CurrentMode} slot={modes.ActiveSlot} claw={claw.CurrentFrame.State}/{nextCast} " +
                $"jumps={motor.AcceptedJumpCount}/{jumps} dash={motor.AcceptedDashCount}/{dashes} " +
                $"recovery={monitor.RecoveryRequested}/{monitor.RecoveryCompleted} " +
                $"accepted={accepted} damage_hits={damageHits} paired={pairedHits} {details}");
        }
        void Callback(Action action)
        {
            try { Check(nodes.All(Live), "live callback actors"); action(); }
            catch (Exception error) { callbackFailure ??= error; }
        }
        void Pair()
        {
            if (!pendingDamage || !pendingConnect || pendingPaired) return;
            pendingPaired = true; pairedHits++;
            Log("PAIR", $"player_attack={pendingId} sweep={pendingSweep} delta=1");
        }
        bool PendingInterval() => pendingId != 0 && Engine.GetPhysicsFrames() >= pendingStartPhysics &&
            Engine.GetPhysicsFrames() - pendingStartPhysics <= (ulong)attackInterval && combat.IsAttacking;
        void OnStarted(ulong id, int direction) => Callback(() =>
        {
            Check(primaryIssued && primaryHeld && accepted < 5 &&
                (pendingId == 0 || pendingPaired) && id != 0 && id > pendingId,
                "unique actual accepted attack token; no extra/missed prior strike");
            Check(CurrentPresentation() && presentation.Timeline.AttackId == issuedSweep &&
                presentation.Timeline.Kind == EnemyAttackKind.BossSweep &&
                presentation.Timeline.Phase == AttackPhase.Recovery &&
                presentation.Timeline.PhaseRemainingSeconds >= .22f && Gap() >= 90f && Gap() <= 100f &&
                Mathf.Abs(player.GlobalPosition.Y - boss.GlobalPosition.Y) <= 28f && Supported() &&
                direction == (int)AttackDirection.Horizontal && combat.LastAttackFacing == inward &&
                (input.CurrentFrame.MoveAxis == inward && input.CurrentFrame.Aim == Vector2.Right * inward ||
                    input.CurrentFrame.MoveAxis == 0f && input.CurrentFrame.Aim == Vector2.Zero &&
                    lastInwardSequence > lastOutwardSequence) &&
                !shield.IsActive && modes.CurrentMode == PlayerActionMode.Attack && modes.ActiveSlot == 1,
                "actual SweepRecovery start ≥.22s, gap90..100, real horizontal inward facing/full support");
            pendingId = id; pendingSweep = issuedSweep;
            pendingStartPhysics = Engine.GetPhysicsFrames();
            pendingDamage = pendingConnect = pendingPaired = false; accepted++;
            connectRetreatStarted = false;
            Log("ATTACK_STARTED", $"player_attack={id} direction={direction} facing={combat.LastAttackFacing}");
        });
        void OnConnected(Hurtbox hurtbox) => Callback(() =>
        {
            Check(Live(hurtbox) && hurtbox == bossHurtbox && PendingInterval() && !pendingConnect,
                "exact BossHurtbox connects once within latest actual accepted attack interval");
            pendingConnect = true; Log("ATTACK_CONNECTED", $"player_attack={pendingId} sweep={pendingSweep}"); Pair();
        });
        void OnBossDamaged(int remaining, Vector2 impulse) => Callback(() =>
        {
            Check(PendingInterval() && !pendingDamage && lastBossHp - remaining == 1 &&
                remaining == 11 - damageHits && damageHits < 5 && impulse.IsFinite(),
                "one actual HP decrement attributed to latest accepted token, not callback count/click");
            lastBossHp = remaining; damageHits++; pendingDamage = true;
            Log("HP_DELTA", $"player_attack={pendingId} sweep={pendingSweep} delta=1 remaining={remaining}"); Pair();
        });
        void OnPlayerDamaged(int remaining, Vector2 impulse) => Callback(() => { damageEvents++; });
        void OnPlayerHealed(int restored, int remaining) => Callback(() => { healEvents++; });
        void OnPlayerDied() => Callback(() => { deathEvents++; });
        void OnBossHealed(int restored, int remaining) => Callback(() =>
            Check(false, $"unexpected Boss heal {restored}/{remaining}"));
        void OnBossDied() => Callback(() => Check(false, "unexpected Boss death"));
        void OnPresentation(AttackPresentationFrame frame) => Callback(() =>
        { presentation = frame.Timeline.Phase == AttackPhase.None ? frame : frame.Validate(); publication++; });
        void OnBossFrame(FallenBellkeeperFrame frame, int facing) => Callback(() =>
        { completedPublication = publication; });
        void Guard()
        {
            previousGuard?.Invoke(); Safety();
            if (input.CurrentFrame.MoveAxis == inward) lastInwardSequence = input.CurrentFrameSequence;
            if (input.CurrentFrame.MoveAxis == flank) lastOutwardSequence = input.CurrentFrameSequence;
            if (selecting && input.CurrentFrame.AttackModePressed && input.CurrentFrameSequence > qIssueSequence)
                qSampleSequence = input.CurrentFrameSequence;
            bool attackEdge = keyboardPhaseOne ? input.CurrentFrame.AttackPressed : input.CurrentFrame.PrimaryPressed;
            if (attackEdge && primarySampleSequence != input.CurrentFrameSequence)
            {
                Check(primaryIssued && input.CurrentFrameSequence > primaryIssueSequence &&
                    (keyboardPhaseOne ? keyboardAttackReady > qIssueSequence && primaryIssueSequence >= keyboardAttackReady &&
                        input.CurrentFrame.KeyboardActions && !input.CurrentFrame.PrimaryPressed &&
                        !input.CurrentFrame.AttackModePressed :
                        qSampleSequence > qIssueSequence && primaryIssueSequence > qSampleSequence),
                    "fresh typed J or legacy LMB is separately sampled after actual readiness");
                primarySampleSequence = input.CurrentFrameSequence; primarySamples++;
                Check(primarySamples == accepted && primarySamples <= 5, "one fresh edge per accepted strike");
            }
            AttackTimelineFrame raw = boss.CurrentFrame.AttackTimeline;
            if (raw.Phase == AttackPhase.None) return;
            Check(CurrentPresentation(), "no stale/default shape evidence for live attack");
            AttackTimelineFrame actual = presentation.Timeline;
            bool hazardous = actual.Phase is AttackPhase.Telegraph or AttackPhase.Active;
            float clearance = Clearance();
            if (actual.Kind == EnemyAttackKind.BossLeapSlam && actual.HasLockedTarget)
            {
                if (lockedSlamId != actual.AttackId)
                { lockedSlamId = actual.AttackId; lockedSlamTarget = actual.LockedWorldTarget; }
                Check(actual.LockedWorldTarget == lockedSlamTarget &&
                    presentation.Shape.Origin.DistanceTo(lockedSlamTarget) <= .01f,
                    "same enriched Slam target/actual circle origin remains locked");
            }
            if (hazardous && actual.Kind is EnemyAttackKind.BossSweep or EnemyAttackKind.BossGroundWave)
                Check(clearance >= 0f, "outside actual Sweep/Wave X geometry expanded by20+8 in Telegraph/Active");
            if (actual.Kind == EnemyAttackKind.BossLeapSlam && actual.Phase == AttackPhase.Active)
                Check(actual.HasLockedTarget && clearance >= 0f,
                    "enriched locked Slam circle clear by Active and through Active");
            // Unlocked Slam follows the live player; never demand clearance from its preview.
            if (loggedAttack != actual.AttackId || loggedPhase != actual.Phase || loggedLock != actual.HasLockedTarget)
            {
                loggedAttack = actual.AttackId; loggedPhase = actual.Phase; loggedLock = actual.HasLockedTarget;
                Log("BOSS_BOUNDARY");
            }
        }
        void PreObserverSafety() { Safety(); previousPreObserverGuard?.Invoke(); }
        async Task Tick()
        {
            Safety(); Check(waits < 1800, "shared1800 wait budget exhausted"); waits++;
            await tree.ToSignal(tree, SceneTree.SignalName.PhysicsFrame);
            Safety(); observe(); // Combined original observer exactly once, invoking this scoped Guard.
        }
        void Move(int direction)
        {
            if (commandedMove == direction) return;
            SendAction(InputActions.MoveLeft, direction < 0);
            SendAction(InputActions.MoveRight, direction > 0); commandedMove = direction;
        }
        void Primary(bool pressed)
        {
            if (primaryHeld == pressed) return;
            SendMouse(MouseButton.Left, pressed, player, boss.GlobalPosition); primaryHeld = pressed;
        }
        void Approach(float target)
        {
            float difference = Gap() - target;
            float toward = -flank * player.Velocity.X * MathF.Sign(difference);
            Check(float.IsFinite(motor.Tuning.GroundDeceleration) && motor.Tuning.GroundDeceleration > 0f,
                "positive actual ordinary braking tuning");
            float brake = toward > 0f ? toward * toward / (2f * motor.Tuning.GroundDeceleration) + toward / 30f : 0f;
            Move(Mathf.Abs(difference) > Mathf.Max(2f, brake) ? (difference > 0f ? inward : flank) : 0);
        }
        void Cleanup(Action action)
        { try { action(); } catch (Exception error) { cleanupFailure ??= error; } }
        // Passive measurement only: none of these values feeds the existing policy.
        string[] measureNames = { "request_time_ge24", "request_gap_le103_5", "request_gap_gt100", "full_inward_speed",
            "vertical_le28", "inward_horizontal_axis", "inward_latest", "can_begin", "can_afford",
            "shield_off", "primary_notheld", "primary_notpressed", "combat_idle",
            "not_retreating", "unissued_sweep" };
        string[] measureBranchNames = { "late-retreat", "approach", "issue", "neutral", "outerexcluded" };
        int[] measureTrue = new int[15], measureBranches = new int[5];
        string[] measureFalse = new string[15];
        ulong measureId = 0;
        int measureWindows = 0, measureOmitted = 0, measureOmittedEvaluations = 0;
        int measureEvaluations = 0, measureFaults = 0, measureRecords = 0;
        bool measureEnabled = false;
        float measureMinimumGap = float.PositiveInfinity, measureMaximumTime = float.NegativeInfinity;
        string measureEntry = null, measureLast = null, measureMinimum = null;
        string measureLate = null, measureStationary = null, measureFirstFault = null;
        string MeasureSnapshot(AttackTimelineFrame timeline, out bool[] gates, out float gap)
        {
            Check(nodes.All(Live), "live nodes before passive strike-gate reads");
            Check(GodotObject.IsInstanceValid(motor.Tuning), "live full-speed resource before passive request-gate read");
            Vector2 pose = player.GlobalPosition, bossPose = boss.GlobalPosition;
            float vx = player.Velocity.X, axis = input.CurrentFrame.MoveAxis;
            gap = flank * (pose.X - bossPose.X);
            gates = new[] { timeline.PhaseRemainingSeconds >= .24f, gap <= 103.5f, gap > 100f,
                vx == inward * motor.Tuning.MaxRunSpeed, Mathf.Abs(pose.Y - bossPose.Y) <= 28f,
                axis == inward && input.CurrentFrame.Aim == Vector2.Right * inward,
                lastInwardSequence > lastOutwardSequence, modes.CanBeginAttack, modes.CanAffordAttack,
                !shield.IsActive, !input.CurrentFrame.PrimaryHeld, !input.CurrentFrame.PrimaryPressed,
                !combat.IsAttacking, !retreating, issuedSweep != timeline.AttackId };
            return $"physics={Engine.GetPhysicsFrames()} input_sequence={input.CurrentFrameSequence} " +
                $"remaining={timeline.PhaseRemainingSeconds:R} pose={pose} boss_pose={bossPose} " +
                $"vX={vx:R} axis={axis:R} aim={input.CurrentFrame.Aim} fullspeed={motor.Tuning.MaxRunSpeed:R} " +
                $"gap={gap:R} vertical_gap={Mathf.Abs(pose.Y - bossPose.Y):R} " +
                $"last_inward={lastInwardSequence} last_outward={lastOutwardSequence} " +
                $"mode={modes.CurrentMode} slot={modes.ActiveSlot} energy={energy.EnergyRatio:R} " +
                $"heat={energy.HeatRatio:R} bossHP={bossHealth.CurrentHealth} accepted={accepted} paired={pairedHits}";
        }
        void MeasureClose(string reason, AttackTimelineFrame? exitTimeline = null)
        {
            if (measureId == 0) return;
            try
            {
                if (!measureEnabled) return;
                string exit = measureLast;
                if (exitTimeline.HasValue)
                {
                    try { exit = MeasureSnapshot(exitTimeline.Value, out _, out _) + " branch=window-close"; }
                    catch (Exception error) { measureFaults++; measureFirstFault ??= error.GetType().Name; }
                }
                // First-false snapshots are deduplicated, not discarded or inferred from a branch.
                var falseFacts = new Dictionary<string, List<string>>();
                for (int index = 0; index < measureNames.Length; index++)
                {
                    string facts = measureFalse[index] ?? "absent";
                    if (!falseFacts.TryGetValue(facts, out List<string> names))
                        falseFacts[facts] = names = new List<string>();
                    names.Add(measureNames[index]);
                }
                string trueCounts = string.Join(',', measureNames.Select((name, index) => $"{name}:{measureTrue[index]}"));
                string branches = string.Join(',', measureBranchNames.Select((name, index) => $"{name}:{measureBranches[index]}"));
                string firstFalse = string.Join(';', falseFacts.Select(pair => $"{string.Join(',', pair.Value)}=>({pair.Key})"));
                GD.Print($"TASK10_BOSS_PHASE1_GATE boundary=ENTRY sweep={measureId} window={measureWindows}/5 {measureEntry}"); measureRecords++;
                GD.Print($"TASK10_BOSS_PHASE1_GATE boundary=FIRST_LATE sweep={measureId} facts={measureLate ?? "absent"}"); measureRecords++;
                GD.Print($"TASK10_BOSS_PHASE1_GATE boundary=MINIMUM sweep={measureId} {measureMinimum} " +
                    $"stationary_gap90_100_speed_le2={measureStationary ?? "absent"} " +
                    $"maximum_time_all_non_time_gates_true={(float.IsFinite(measureMaximumTime) ? measureMaximumTime.ToString("R") : "absent")}"); measureRecords++;
                GD.Print($"TASK10_BOSS_PHASE1_GATE boundary=END sweep={measureId} reason={reason} " +
                    $"evaluations={measureEvaluations} last_evaluation=({measureLast}) exit=({exit}) " +
                    $"true_counts=[{trueCounts}] branches=[{branches}] first_false=[{firstFalse}]"); measureRecords++;
            }
            catch (Exception error) { measureFaults++; measureFirstFault ??= error.GetType().Name; }
            finally { measureId = 0; measureEnabled = false; }
        }
        void MeasureBefore(AttackTimelineFrame timeline)
        {
            try
            {
                if (timeline.Kind != EnemyAttackKind.BossSweep || timeline.Phase != AttackPhase.Recovery)
                { MeasureClose("phase-exit", timeline); return; }
                if (measureId != timeline.AttackId)
                {
                    MeasureClose("attack-id-exit", timeline);
                    measureId = timeline.AttackId; measureWindows++;
                    measureEnabled = measureWindows <= 5;
                    if (!measureEnabled) { measureOmitted++; measureOmittedEvaluations++; return; }
                    measureTrue = new int[15]; measureBranches = new int[5]; measureFalse = new string[15];
                    measureEvaluations = 0; measureMinimumGap = float.PositiveInfinity;
                    measureMaximumTime = float.NegativeInfinity;
                    measureEntry = measureLast = measureMinimum = measureLate = measureStationary = null;
                }
                if (!measureEnabled) { measureOmittedEvaluations++; return; }
                measureEvaluations++;
                measureLast = MeasureSnapshot(timeline, out bool[] gates, out float gap);
                measureEntry ??= measureLast;
                for (int index = 0; index < gates.Length; index++)
                {
                    if (gates[index]) measureTrue[index]++;
                    else measureFalse[index] ??= measureLast;
                }
                if (gap <= measureMinimumGap) { measureMinimumGap = gap; measureMinimum = measureLast; }
                if (gap >= 90f && gap <= 100f && Mathf.Abs(player.Velocity.X) <= 2f)
                    measureStationary ??= measureLast; // Optional raw fact, not a request predicate.
                if (gates.Skip(1).All(value => value))
                    measureMaximumTime = Mathf.Max(measureMaximumTime, timeline.PhaseRemainingSeconds);
            }
            catch (Exception error) { measureFaults++; measureFirstFault ??= error.GetType().Name; }
        }
        void MeasureBranch(int branch)
        {
            try
            {
                if (!measureEnabled || measureId == 0 || measureLast == null) return;
                measureBranches[branch]++;
                string before = measureLast;
                measureLast += " branch=" + measureBranchNames[branch];
                if (measureEntry == before) measureEntry = measureLast;
                if (measureMinimum == before) measureMinimum = measureLast;
                if (measureStationary == before) measureStationary = measureLast;
                for (int index = 0; index < measureFalse.Length; index++)
                    if (measureFalse[index] == before) measureFalse[index] = measureLast;
                if (branch == 0) measureLate ??= measureLast;
            }
            catch (Exception error) { measureFaults++; measureFirstFault ??= error.GetType().Name; }
        }
        void MeasureTerminal(string reason)
        {
            try
            {
                if (nodes.All(Live)) MeasureClose(reason, boss.CurrentFrame.AttackTimeline);
                else MeasureClose(reason);
                GD.Print($"TASK10_BOSS_PHASE1_GATE boundary=TERMINAL reason={reason} windows={measureWindows} " +
                    $"retained={Math.Min(measureWindows, 5)} omitted_windows={measureOmitted} " +
                    $"omitted_evaluations={measureOmittedEvaluations} window_records={measureRecords}/20 " +
                    $"diagnostic_faults={measureFaults} first_fault={measureFirstFault ?? "none"} diagnostic_only=True");
            }
            catch (Exception error) { measureFaults++; measureFirstFault ??= error.GetType().Name; }
        }
        try
        {
            previousGuard = swapApproachGuard(Guard); scopeInstalled = true;
            previousPreObserverGuard = swapPreObserverGuard(PreObserverSafety); preScopeInstalled = true;
            subscribed = true;
            boss.AttackFrameChanged += OnPresentation; boss.FrameChanged += OnBossFrame;
            combat.AttackStarted += OnStarted; combat.AttackConnected += OnConnected;
            bossHealth.Damaged += OnBossDamaged; bossHealth.Healed += OnBossHealed; bossHealth.Died += OnBossDied;
            health.Damaged += OnPlayerDamaged; health.Healed += OnPlayerHealed; health.Died += OnPlayerDied;
            Safety(); Log("ENTRY");
            // Previous helper has released inputs, but its final sampled D/velocity may remain.
            SendAction(InputActions.MoveLeft, false); SendAction(InputActions.MoveRight, false);
            stage = "initial-approach";
            while (waits < 180 && (Gap() < 200f || Gap() > 210f || Mathf.Abs(player.Velocity.X) > 2f))
            { Approach(205f); await Tick(); }
            Move(0); Check(Gap() >= 200f && Gap() <= 210f && Mathf.Abs(player.Velocity.X) <= 2f,
                "natural initial205 approach/settle within180 shared waits");
            selecting = true; stage = "sample-Q"; qIssueSequence = input.CurrentFrameSequence;
            SendAction(InputActions.SelectAttackMode, true);
            int qWaits = 0;
            if (keyboardPhaseOne)
            {
                await Tick(); qWaits++;
                keyboardAttackReady = input.CurrentFrameSequence;
                Check(keyboardAttackReady > qIssueSequence && input.CurrentFrame.KeyboardActions &&
                    modes.CanBeginAttack && modes.ActiveSlot == 1 && !shield.IsActive &&
                    !Input.IsActionPressed(InputActions.Attack) && !Input.IsActionPressed(InputActions.Claw) &&
                    !input.CurrentFrame.AttackModePressed && !input.CurrentFrame.InteractPressed,
                    "independent J readiness without Q selection or a premature strike");
            }
            else while (qWaits < 8 && (qSampleSequence <= qIssueSequence ||
                input.CurrentFrameSequence <= qSampleSequence || modes.CurrentMode != PlayerActionMode.Attack))
            { await Tick(); qWaits++; }
            SendAction(InputActions.SelectAttackMode, false); selecting = false;
            Check(keyboardPhaseOne ? keyboardAttackReady > qIssueSequence :
                qSampleSequence > qIssueSequence && input.CurrentFrameSequence > qSampleSequence &&
                modes.CurrentMode == PlayerActionMode.Attack && modes.ActiveSlot == 1 && !shield.IsActive,
                "actual independent J readiness or separate legacy Q before any strike");
            Log(keyboardPhaseOne ? "KEYBOARD_ATTACK_READY" : "Q_READY",
                $"keyboard_ready={keyboardAttackReady} Q_issue={qIssueSequence} Q_sample={qSampleSequence}");
            stage = "phase1";
            while (damageHits < 5)
            {
                Safety();
                if (boss.CurrentFrame.State == FallenBellkeeperState.Intro) { Move(0); await Tick(); continue; }
                Check(CurrentPresentation(), "phase1 decisions require completed actual actor publication");
                AttackTimelineFrame timeline = presentation.Timeline;
                if (pendingId != 0 && !pendingPaired &&
                    Engine.GetPhysicsFrames() - pendingStartPhysics > (ulong)attackInterval)
                    Check(false, "accepted attack missed exact paired one-damage connection in its bounded interval");
                if (pendingConnect && !connectRetreatStarted)
                {
                    Check(timeline.Kind != EnemyAttackKind.BossLeapSlam || !timeline.HasLockedTarget,
                        "actual connect initiates retreat before enriched Slam lock");
                    retreating = true; connectRetreatStarted = true;
                    Log("RETREAT_AFTER_CONNECT", $"player_attack={pendingId} sweep={pendingSweep}");
                }
                // A buffered edge may need several physics observations. Preserve the
                // admitted neutral/inward facing until that edge is actually sampled.
                if (primaryHeld && primarySampleSequence <= primaryIssueSequence)
                { Move(0); await Tick(); continue; }
                if (primaryIssued && primaryHeld && primarySampleSequence > primaryIssueSequence)
                { Primary(false); Move(0); }
                if (pendingId != 0 && !pendingConnect)
                { Move(0); await Tick(); continue; }
                MeasureBefore(timeline);
                if (timeline.Kind == EnemyAttackKind.BossSweep && timeline.Phase == AttackPhase.Recovery &&
                    issuedSweep != timeline.AttackId && !combat.IsAttacking && !retreating)
                {
                    if (timeline.PhaseRemainingSeconds < .24f) { MeasureBranch(0); Move(flank); } // Missed request window: skip this cycle.
                    else if (Gap() > 103.5f) { MeasureBranch(1); Move(inward); }
                    else if (Gap() > 100f && Gap() <= 103.5f &&
                        player.Velocity.X == inward * motor.Tuning.MaxRunSpeed &&
                        Mathf.Abs(player.GlobalPosition.Y - boss.GlobalPosition.Y) <= 28f &&
                        input.CurrentFrame.MoveAxis == inward && input.CurrentFrame.Aim == Vector2.Right * inward &&
                        lastInwardSequence > lastOutwardSequence &&
                        modes.CanBeginAttack && modes.CanAffordAttack &&
                        !shield.IsActive && !input.CurrentFrame.PrimaryHeld && !input.CurrentFrame.PrimaryPressed &&
                        (!keyboardPhaseOne || !Input.IsActionPressed(InputActions.Attack) && !input.CurrentFrame.AttackPressed))
                    {
                        MeasureBranch(2);
                        issuedSweep = timeline.AttackId; primaryIssued = true;
                        primaryIssueSequence = input.CurrentFrameSequence;
                        Move(0); // Request only; actual OnStarted still requires gap90..100/remaining≥.22.
                        Primary(true); Log("PRIMARY_ISSUED", $"sweep={issuedSweep} sequence={primaryIssueSequence}");
                    }
                    else { MeasureBranch(3); Move(0); }
                }
                else if (timeline.Kind == EnemyAttackKind.BossLeapSlam)
                {
                    MeasureBranch(4);
                    // Retreat began after actual connect, before half-telegraph lock. Obtain
                    // clearance after the enriched lock; only Active is an enforced Slam hazard.
                    if (timeline.Phase == AttackPhase.Recovery) Approach(305f);
                    else if (!timeline.HasLockedTarget || Clearance() < 8f || Gap() < 285f) Move(flank);
                    else Move(0);
                }
                else if (timeline.Kind == EnemyAttackKind.BossGroundWave)
                {
                    MeasureBranch(4);
                    if (timeline.Phase == AttackPhase.Recovery)
                    { retreating = false; Approach(205f); }
                    else if (Clearance() < 8f || Gap() < 285f) Move(flank);
                    else if (Gap() > 315f) Check(false, "Wave candidate285..315 exceeded; no cross-arena fallback");
                    else Move(0);
                }
                else if (retreating) { MeasureBranch(4); Approach(305f); }
                else { MeasureBranch(4); Approach(205f); }
                await Tick();
            }
            // No sixth strike: stop immediately at the fifth actual decrement, then observe
            // the already accepted token's connection and the production model Transition.
            stage = "transition"; Primary(false); Move(0);
            while (boss.CurrentFrame.State != FallenBellkeeperState.Transition || pairedHits != 5 ||
                Mathf.Abs(player.Velocity.X) > 2f || input.CurrentFrame.PrimaryHeld ||
                keyboardPhaseOne && Input.IsActionPressed(InputActions.Attack) || input.CurrentFrame.MoveAxis != 0f)
                await Tick();
            Safety(); Check(accepted == 5 && primarySamples == 5 && damageHits == 5 && pairedHits == 5 &&
                bossHealth.CurrentHealth == 7, "five unique accepted/connected one-damage Sweep hits, actual HP7 Transition");
            Log("TRANSITION"); Log("SUMMARY", "phase1_local_only=True phase2_unrun=True");
            MeasureTerminal("phase1-end");
        }
        catch (Exception error)
        {
            firstFailure = error;
            MeasureTerminal("failure");
            try { Log("FAIL", $"type={error.GetType().Name} message={error.Message.Replace('\r', ' ').Replace('\n', ' ')}"); }
            catch { /* Preserve first failure even if diagnostic nodes were invalidated. */ }
            throw;
        }
        finally
        {
            if (subscribed)
            {
                Cleanup(() => { if (GodotObject.IsInstanceValid(boss)) { boss.AttackFrameChanged -= OnPresentation; boss.FrameChanged -= OnBossFrame; } });
                Cleanup(() => { if (GodotObject.IsInstanceValid(combat)) { combat.AttackStarted -= OnStarted; combat.AttackConnected -= OnConnected; } });
                Cleanup(() => { if (GodotObject.IsInstanceValid(bossHealth)) { bossHealth.Damaged -= OnBossDamaged; bossHealth.Healed -= OnBossHealed; bossHealth.Died -= OnBossDied; } });
                Cleanup(() => { if (GodotObject.IsInstanceValid(health)) { health.Damaged -= OnPlayerDamaged; health.Healed -= OnPlayerHealed; health.Died -= OnPlayerDied; } });
            }
            Cleanup(() => SendAction(InputActions.MoveLeft, false));
            Cleanup(() => SendAction(InputActions.MoveRight, false));
            Cleanup(() => SendAction(InputActions.SelectAttackMode, false));
            Cleanup(() => SendMouse(MouseButton.Left, false, Live(player) ? player : null,
                Live(boss) ? boss.GlobalPosition : Vector2.Zero));
            Cleanup(() => { if (preScopeInstalled) swapPreObserverGuard(previousPreObserverGuard); });
            Cleanup(() => { if (scopeInstalled) swapApproachGuard(previousGuard); });
            if (firstFailure != null && cleanupFailure != null)
                try { GD.Print($"TASK10_BOSS_PHASE1 cleanup_gap={cleanupFailure.GetType().Name}"); } catch { }
        }
        if (cleanupFailure != null) throw cleanupFailure;
    }

    private sealed record Task10BossOpeningReceipt(ulong PlayerId, ulong BossId, ulong ChainId,
        int PlayerHp, int RecoveryRequests, int Recoveries, int Jumps, int Dashes, int BossHp,
        ulong PlayerAttackId, ulong AttackPhysics, ulong HammerId, ulong ExposureEntryPhysics,
        ulong NextCastId, int Applications, ulong TerminalPhysics, int Waits, string NativeSignature,
        int PhysicsTicks, float PhysicsDelta, Knight.Config.BossSettings BossSettings,
        PlayerCombatSettings CombatSettings, PlayerMotionSettings MotionSettings);

    private enum Task10BossOpeningMode { Nonfatal, Fatal }
    private sealed record Task10BossFatalDamage(ulong PlayerAttackId, ulong AttackPhysics,
        ulong DamagePhysics, ulong ExposureEntryPhysics, float ExposureElapsed, float RemainingLowerBound,
        Vector2 Impulse);
    private sealed record Task10BossDeathReceipt(Task10BossOpeningReceipt Opening,
        Task10BossFatalDamage Damage, int DiedEvents, int ArenaEvents, ulong DefeatedPhysics,
        int DrainWaits, int DeathTailWaits, int SettleWaits);
    private sealed record Task10BossOpeningOutcome(Task10BossOpeningReceipt Opening, Task10BossDeathReceipt Death);

    private static Transform2D Task10BossUniform(CollisionShape2D shape, Action native, Action<bool, string> check)
    {
        native(); Transform2D t = shape.GlobalTransform;
        float x = t.X.Length(), y = t.Y.Length();
        check(t.Origin.IsFinite() && t.X.IsFinite() && t.Y.IsFinite() && float.IsFinite(x) && x > 0f &&
            Mathf.Abs(x - y) <= .0001f && Mathf.Abs(t.X.Dot(t.Y)) <= .0001f * x * y &&
            t.X.Cross(t.Y) > 0f, "finite positive uniform orthogonal collider transform");
        return t;
    }

    private static Rect2 Task10BossBounds(CollisionShape2D shape, Func<CollisionShape2D, Transform2D> uniform,
        Action<bool, string> check)
    {
        Transform2D t = uniform(shape);
        if (shape.Shape is CapsuleShape2D capsule)
        {
            float radius = capsule.Radius * t.X.Length(), half = capsule.Height * .5f * t.Y.Length();
            check(float.IsFinite(radius) && float.IsFinite(half) && radius > 0f && half >= radius, "valid capsule dimensions");
            Vector2 extent = new(radius + Mathf.Abs(Mathf.Sin(t.Rotation)) * (half - radius),
                radius + Mathf.Abs(Mathf.Cos(t.Rotation)) * (half - radius));
            return new Rect2(t.Origin - extent, extent * 2f);
        }
        check(shape.Shape is RectangleShape2D, "only measured capsule/rectangle bounds supported");
        Rect2 local = shape.Shape.GetRect(), bounds = new(t * local.Position, Vector2.Zero);
        foreach (Vector2 corner in new[] { new Vector2(local.End.X, local.Position.Y), local.End,
            new Vector2(local.Position.X, local.End.Y) }) bounds = bounds.Expand(t * corner);
        check(bounds.Position.IsFinite() && bounds.Size.IsFinite(), "finite actual rectangle bounds");
        return bounds;
    }

    private static bool Task10BossSupported(CharacterBody2D player, StaticBody2D floor, FallenBellkeeper boss,
        CollisionShape2D bodyShape, CollisionShape2D floorShape, CollisionShape2D entryDoor, CollisionShape2D exitDoor,
        Action native, Func<CollisionShape2D, Rect2> bounds, Action<bool, string> check)
    {
        native(); Rect2 body = bounds(bodyShape), ground = bounds(floorShape);
        if (!player.IsOnFloor() || body.Position.X < ground.Position.X || body.End.X > ground.End.X) return false;
        bool upward = false;
        for (int i = 0; i < player.GetSlideCollisionCount(); i++)
        {
            KinematicCollision2D contact = player.GetSlideCollision(i);
            if (!GodotObject.IsInstanceValid(contact)) continue;
            GodotObject collider = contact.GetCollider();
            if (!GodotObject.IsInstanceValid(collider)) continue;
            check(collider != boss && collider != entryDoor.GetParent() && collider != exitDoor.GetParent(), "no Boss/door slide contact");
            if (collider == floor && contact.GetNormal().Y < -.7f) upward = true;
        }
        return upward;
    }

    private static async Task<Task10BossOpeningReceipt> DriveTask10BossFirstExposure(SceneTree tree,
        PrologueLevelController level, SeamlessPrologueWorld world, CharacterBody2D player,
        RouteMonitor monitor, Action observe, Func<Action, Action> swapApproachGuard,
        Func<Action, Action> swapPreObserverGuard, int expectedEntryBossHp = 7,
        Task10BossOpeningReceipt priorReceipt = null)
    {
        Task10BossOpeningOutcome outcome = await DriveTask10BossOpeningCore(tree, level, world, player, monitor,
            observe, swapApproachGuard, swapPreObserverGuard, Task10BossOpeningMode.Nonfatal, expectedEntryBossHp, priorReceipt);
        return outcome.Opening;
    }

    private static async Task<Task10BossDeathReceipt> DriveTask10BossFatalOpening(SceneTree tree,
        PrologueLevelController level, SeamlessPrologueWorld world, CharacterBody2D player,
        RouteMonitor monitor, Action observe, Func<Action, Action> swapApproachGuard,
        Func<Action, Action> swapPreObserverGuard, Task10BossOpeningReceipt priorReceipt)
    {
        TestAssert.True(priorReceipt != null && priorReceipt.BossHp == 1 && priorReceipt.Applications == 6,
            "Task10 Boss fatal opening: only qualified living HP1/six applications");
        Task10BossOpeningOutcome outcome = await DriveTask10BossOpeningCore(tree, level, world, player, monitor,
            observe, swapApproachGuard, swapPreObserverGuard, Task10BossOpeningMode.Fatal, 1, priorReceipt);
        TestAssert.True(outcome.Death != null, "Task10 Boss fatal opening: genuine death receipt after cleanup");
        return outcome.Death;
    }

    private static async Task<Task10BossOpeningOutcome> DriveTask10BossOpeningCore(SceneTree tree,
        PrologueLevelController level, SeamlessPrologueWorld world, CharacterBody2D player,
        RouteMonitor monitor, Action observe, Func<Action, Action> swapApproachGuard,
        Func<Action, Action> swapPreObserverGuard, Task10BossOpeningMode mode, int expectedEntryBossHp,
        Task10BossOpeningReceipt priorReceipt)
    {
        bool fatal = mode == Task10BossOpeningMode.Fatal;
        bool keyboardOpening = KeyboardRouteInputDriver.Current != null;
        // One exact runner-owned Root child lookup, only for the final HP1 opening.
        Task11PointerAdmissionTrace pointerTrace = null;
        if (fatal && expectedEntryBossHp == 1)
        {
            try { pointerTrace = tree.Root.GetNodeOrNull<Task11PointerAdmissionTrace>(Task11PointerAdmissionTrace.RootChildName); }
            catch { /* Missing observer remains unarmed/incomplete; never replace route validation. */ }
        }
        bool Live(Node node) => node != null && GodotObject.IsInstanceValid(node) &&
            node.IsInsideTree() && !node.IsQueuedForDeletion();
        void Check(bool condition, string message) => TestAssert.True(condition, "Task10 Boss first exposure: " + message);
        Check(GodotObject.IsInstanceValid(tree) && Live(level) && Live(world) && Live(player) &&
            Live(monitor.Player), "native-valid original route entry");
        Check(world.TryGetMountedSector(PrologueSectorId.LostTemple, out PrologueSector temple) && Live(temple),
            "actual mounted LostTemple");
        BossArenaController arena = temple.GetNode<BossArenaController>("Gameplay/BossArenaController");
        Check(Live(arena) && Live(arena.CurrentBoss), "actual arena/Boss before component reads");
        FallenBellkeeper boss = arena.CurrentBoss;
        PrologueGameFlowController flow = level.GetNode<PrologueGameFlowController>("GameFlow");
        HealthComponent health = player.GetNode<HealthComponent>("Health"), bossHealth = boss.GetNode<HealthComponent>("Health");
        PlayerMotor motor = player.GetNode<PlayerMotor>("Motor");
        PlayerInputReader input = player.GetNode<PlayerInputReader>("Input");
        PlayerCombat combat = player.GetNode<PlayerCombat>("Combat");
        PlayerActionModeController modes = player.GetNode<PlayerActionModeController>("ActionModes");
        PlayerEnergyController energy = player.GetNode<PlayerEnergyController>("Energy");
        PlayerShieldController shield = player.GetNode<PlayerShieldController>("Shield");
        MechanicalClawController claw = player.GetNode<MechanicalClawController>("MechanicalClaw");
        StaticBody2D floor = temple.GetNode<StaticBody2D>("Gameplay/Collision/ArenaFloor");
        Hurtbox playerHurtbox = player.GetNode<Hurtbox>("Hurtbox"), bossHurtbox = boss.GetNode<Hurtbox>(boss.HurtboxPath);
        Hitbox hammerHitbox = boss.GetNode<Hitbox>(boss.AttackHitboxPath);
        ThreadTarget2D chain = boss.GetNode<ThreadTarget2D>(boss.ChainTargetPath);
        Check(new Node[] { floor, playerHurtbox, bossHurtbox, hammerHitbox, chain }.All(Live), "live geometry owners");
        CollisionShape2D floorShape = floor.GetNode<CollisionShape2D>("Collision");
        CollisionShape2D bodyShape = player.GetNode<CollisionShape2D>("BodyCollider");
        CollisionShape2D hurtShape = playerHurtbox.GetNode<CollisionShape2D>("HurtboxCollider");
        CollisionShape2D bossHurtShape = bossHurtbox.GetNode<CollisionShape2D>("HurtboxCollider");
        CollisionShape2D hammerShape = hammerHitbox.GetNode<CollisionShape2D>("AttackCollider");
        CollisionShape2D chainShape = chain.GetNode<CollisionShape2D>("TargetCollision/Collision");
        CollisionShape2D entryDoor = arena.GetNode<CollisionShape2D>(arena.EntryDoorCollisionPath);
        CollisionShape2D exitDoor = arena.GetNode<CollisionShape2D>(arena.ExitDoorCollisionPath);
        LegacyThreadInteractionAdapter adapter = chain.GetNode<LegacyThreadInteractionAdapter>("LegacyThreadInteractionAdapter");
        Node[] nodes = { level, world, temple, arena, boss, flow, player, monitor.Player, health, bossHealth,
            motor, input, combat, modes, energy, shield, claw, floor, playerHurtbox, bossHurtbox, hammerHitbox,
            chain, adapter, floorShape, bodyShape, hurtShape, bossHurtShape, hammerShape, chainShape, entryDoor, exitDoor };
        CollisionShape2D[] shapes = { floorShape, bodyShape, hurtShape, bossHurtShape, hammerShape, chainShape, entryDoor, exitDoor };
        void Native()
        {
            Check(GodotObject.IsInstanceValid(tree) && nodes.All(Live), "native lifetime before reads/callbacks/waits");
            Check(shapes.All(shape => GodotObject.IsInstanceValid(shape.Shape)) &&
                GodotObject.IsInstanceValid(motor.Tuning) && GodotObject.IsInstanceValid(combat.Tuning) &&
                GodotObject.IsInstanceValid(boss.Tuning), "native-valid collision/tuning resources");
        }
        Native();
        ulong playerId = player.GetInstanceId(), bossId = boss.GetInstanceId(), chainId = chain.GetInstanceId();
        int hp = health.CurrentHealth, requests = monitor.RecoveryRequested, recoveries = monitor.RecoveryCompleted;
        int jumps = motor.AcceptedJumpCount, dashes = motor.AcceptedDashCount, applications = adapter.ApplicationCount;
        ulong nextCast = claw.CurrentFrame.NextCastId;
        string nativeSignature = string.Join(",", nodes.Select(node => node.GetInstanceId())) + "/" +
            string.Join(",", shapes.Where(shape => shape != hammerShape).Select(shape => shape.Shape.GetInstanceId())) +
            $"/{motor.Tuning.GetInstanceId()}/{combat.Tuning.GetInstanceId()}/{boss.Tuning.GetInstanceId()}";
        Check(fatal ? expectedEntryBossHp == 1 && priorReceipt != null && priorReceipt.BossHp == 1 && priorReceipt.Applications == 6 :
            expectedEntryBossHp is >= 2 and <= 7 && (expectedEntryBossHp == 7 ? priorReceipt == null : priorReceipt != null),
            "only initial7 or five fresh nonfatal openings2..6 with prior receipt");
        if (priorReceipt != null)
            Check(playerId == priorReceipt.PlayerId && bossId == priorReceipt.BossId && chainId == priorReceipt.ChainId &&
                hp == priorReceipt.PlayerHp && requests == priorReceipt.RecoveryRequests && recoveries == priorReceipt.Recoveries &&
                jumps == priorReceipt.Jumps && dashes == priorReceipt.Dashes && expectedEntryBossHp == priorReceipt.BossHp &&
                nextCast == priorReceipt.NextCastId && applications == priorReceipt.Applications && nativeSignature == priorReceipt.NativeSignature &&
                Engine.PhysicsTicksPerSecond == priorReceipt.PhysicsTicks && Engine.TimeScale == 1d &&
                Mathf.Abs((float)boss.GetPhysicsProcessDeltaTime() - priorReceipt.PhysicsDelta) <= .000001f &&
                boss.Tuning.ToSettings() == priorReceipt.BossSettings && combat.Tuning.ToCombatSettings() == priorReceipt.CombatSettings &&
                motor.Tuning.ToMotionSettings() == priorReceipt.MotionSettings, "original receipt/health/counters/cast/resources/clock continuity");
        FallenBellkeeperState expectedEntryState = fatal ? FallenBellkeeperState.Exposed :
            expectedEntryBossHp == 7 ? FallenBellkeeperState.Transition : FallenBellkeeperState.PhaseTwoArmored;
        Check(hp > 0 && bossHealth.CurrentHealth == expectedEntryBossHp && boss.CurrentFrame.State == expectedEntryState &&
            player.GlobalPosition.X < boss.GlobalPosition.X, $"genuine HP{expectedEntryBossHp} {expectedEntryState} on original left flank");
        if (fatal) Check(priorReceipt.TerminalPhysics == Engine.GetPhysicsFrames() && priorReceipt.PhysicsTicks == 60 &&
            priorReceipt.BossSettings.ExposedSeconds == 2f, "immediate qualified HP1 receipt and original180 drain derivation");
        int ticks = Engine.PhysicsTicksPerSecond;
        float startup = combat.Tuning.AttackStartupSeconds, exposureSeconds = boss.Tuning.ExposedSeconds;
        float stepDelta = (float)boss.GetPhysicsProcessDeltaTime();
        Check(ticks > 0 && Engine.TimeScale == 1d && float.IsFinite(stepDelta) && stepDelta > 0f &&
            Mathf.Abs(stepDelta - 1f / ticks) <= .000001f && float.IsFinite(startup) && startup > 0f &&
            float.IsFinite(exposureSeconds) && exposureSeconds > 0f, "unambiguous actual physics/config clock");
        var bossTuning = boss.Tuning; var combatTuning = combat.Tuning;
        var bossSettings = boss.Tuning.ToSettings(); var combatSettings = combat.Tuning.ToCombatSettings();
        MechanicalClawSettings settings = MechanicalClawSettings.Default;
        var resolver = new MechanicalClawTargetResolver(settings);
        int waits = 0, accepted = 0, primaries = 0, damaged = 0, connected = 0;
        int playerChanges = 0, eSamples = 0, qSamples = 0;
        bool positioned = false, eIssued = false, castIssued = false, qIssued = false, strikeIssued = false;
        bool travel = false, latched = false, released = false, paired = false, activeSeen = false;
        bool subscribed = false, scopeInstalled = false, preInstalled = false;
        ulong eIssue = 0, eSample = 0, castIssue = 0, castSample = 0, qIssue = 0, qSample = 0, strikeIssue = 0, strikeSample = 0;
        ulong keyboardCastReady = 0, keyboardStrikeReady = 0;
        ulong firstHammer = 0, attackId = 0, attackPhysics = 0, inwardSequence = 0, outwardSequence = 0;
        ulong publication = 0, completedPublication = 0, exposureEntryPhysics = 0, lastBossPhysics = 0;
        float exposureElapsed = 0f;
        bool exposureObserved = false;
        AttackPresentationFrame presentation = default;
        AttackPhase loggedPhase = AttackPhase.None; bool loggedLock = false;
        MechanicalClawState loggedClaw = MechanicalClawState.Idle;
        string stage = "entry";
        Exception callbackFailure = null, firstFailure = null, cleanupFailure = null;
        Task10BossOpeningReceipt receipt = null;
        Task10BossDeathReceipt deathReceipt = null;
        Task10BossFatalDamage fatalDamage = null;
        int diedEvents = 0, arenaEvents = 0, fatalDrainWaits = 0, deathTailWaits = 0, finalSettleWaits = 0;
        ulong defeatedPhysics = 0;
        bool fatalEarlySubscribed = false, arenaSubscribed = false;
        Action previousGuard = null, previousPre = null;
        int admissionDiagnosticRecords = 0, admissionDiagnosticFaults = 0;
        var admissionDiagnosticKeys = new HashSet<string>();
        int commandedMove = 0;
        int attackInterval = (int)MathF.Ceiling((startup + combat.Tuning.AttackActiveSeconds +
            combat.Tuning.AttackRecoverySeconds) * ticks) + 4;
        Check(float.IsFinite(combat.Tuning.AttackActiveSeconds) && combat.Tuning.AttackActiveSeconds > 0f &&
            float.IsFinite(combat.Tuning.AttackRecoverySeconds) && combat.Tuning.AttackRecoverySeconds > 0f &&
            attackInterval > 0, "finite configured bounded real attack interval");
        float Gap() => boss.GlobalPosition.X - player.GlobalPosition.X;
        Transform2D Uniform(CollisionShape2D shape) => Task10BossUniform(shape, Native, Check);
        Rect2 Bounds(CollisionShape2D shape) => Task10BossBounds(shape, Uniform, Check);
        bool Supported() => Task10BossSupported(player, floor, boss, bodyShape, floorShape, entryDoor, exitDoor,
            Native, Bounds, Check);
        bool Idle() => claw.CurrentFrame.State == MechanicalClawState.Idle && claw.CurrentFrame.CastId == 0 &&
            claw.CurrentFrame.LockedTargetRuntimeId == 0 && claw.CurrentTarget == null && claw.ResidencyTarget == null;
        bool Stationary() => Supported() && Gap() >= 80f && Gap() <= 90f && player.Velocity.Length() <= 2f &&
            input.CurrentFrame.MoveAxis == 0f && inwardSequence > outwardSequence;
        // The authored chain is (+70,-42) from the Boss: at the grounded
        // melee gap80..90 its anchor is just outside the keyboard Right cone.
        // Keep the original melee band; only the keyboard K stance is farther out.
        bool ChainStationary() => !keyboardOpening ? Stationary() :
            Supported() && Gap() >= 94f && Gap() <= 98f && player.Velocity.Length() <= 2f &&
            input.CurrentFrame.MoveAxis == 0f && inwardSequence > outwardSequence;
        bool CurrentHammer()
        {
            Native(); AttackTimelineFrame raw = boss.CurrentFrame.AttackTimeline, actual = presentation.Timeline;
            return publication > 0 && completedPublication == publication && firstHammer != 0 &&
                actual.AttackId == firstHammer && actual.AttackId == raw.AttackId &&
                actual.Kind == EnemyAttackKind.BossHammerThrow && actual.Kind == raw.Kind && actual.Phase == raw.Phase &&
                actual.PhaseRemainingSeconds == raw.PhaseRemainingSeconds;
        }
        float HammerClearance()
        {
            Check(CurrentHammer(), "current first-Hammer publication/model identity");
            AttackShapeFrame s = presentation.Shape; Transform2D t = Uniform(hammerShape);
            Check(hammerShape.Shape is CapsuleShape2D && s.Kind == AttackShapeKind.Capsule &&
                s.Origin.IsFinite() && s.Extent.IsFinite() && float.IsFinite(s.RotationRadians), "actual capsule publication");
            CapsuleShape2D capsule = (CapsuleShape2D)hammerShape.Shape;
            Vector2 measured = new(capsule.Radius * t.X.Length(), capsule.Height * .5f * t.Y.Length());
            Check(s.Origin.DistanceTo(t.Origin) <= .0001f && s.Extent.DistanceTo(measured) <= .0001f &&
                Mathf.Abs(Mathf.AngleDifference(s.RotationRadians, t.Rotation)) <= .0001f &&
                s.Extent.X > 0f && s.Extent.Y >= s.Extent.X,
                $"published/current post-move collider consistency origin={s.Origin}/{t.Origin} extent={s.Extent}/{measured}");
            float half = s.Extent.X + Mathf.Abs(Mathf.Cos(s.RotationRadians)) * (s.Extent.Y - s.Extent.X);
            float clearance = Bounds(hurtShape).Position.Y - (s.Origin.Y + half);
            Check(float.IsFinite(clearance), "finite measured full hurtbox vertical clearance"); return clearance;
        }
        float ExposureLowerBound()
        {
            Native(); Clock(); Check(exposureObserved && boss.CurrentFrame.State == FallenBellkeeperState.Exposed &&
                !boss.CurrentFrame.ArmorClosed && !boss.CurrentFrame.AttackActive && adapter.ApplicationCount == applications + 1,
                "actual same-chain Exposed, never stale Hammer timer");
            return exposureSeconds - exposureElapsed - (float)boss.GetPhysicsProcessDeltaTime();
        }
        void Clock()
        {
            Native();
            Check(Engine.PhysicsTicksPerSecond == ticks && Engine.TimeScale == 1d && boss.Tuning == bossTuning &&
                combat.Tuning == combatTuning && boss.Tuning.ToSettings() == bossSettings &&
                combat.Tuning.ToCombatSettings() == combatSettings &&
                Mathf.Abs((float)boss.GetPhysicsProcessDeltaTime() - stepDelta) <= .000001f,
                "unchanged actual tuning/rate/timeScale/delta");
        }
        void Safety()
        {
            Native();
            Check(player.GetInstanceId() == playerId && monitor.Player.GetInstanceId() == playerId &&
                boss.GetInstanceId() == bossId && arena.CurrentBoss == boss && (arena.IsEncounterActive || fatalDamage != null) &&
                flow.State == PrologueGameFlowState.Playing && !tree.Paused, "same original Playing player/Boss/arena");
            if (fatal)
            {
                string signature = string.Join(",", nodes.Select(node => node.GetInstanceId())) + "/" +
                    string.Join(",", shapes.Where(shape => shape != hammerShape).Select(shape => shape.Shape.GetInstanceId())) +
                    $"/{motor.Tuning.GetInstanceId()}/{combat.Tuning.GetInstanceId()}/{boss.Tuning.GetInstanceId()}";
                Check(signature == priorReceipt.NativeSignature && motor.Tuning.ToMotionSettings() == priorReceipt.MotionSettings &&
                    chain.GetInstanceId() == priorReceipt.ChainId && hp == priorReceipt.PlayerHp && requests == priorReceipt.RecoveryRequests &&
                    recoveries == priorReceipt.Recoveries && jumps == priorReceipt.Jumps && dashes == priorReceipt.Dashes,
                    "fatal original receipt/native/resource/motion and player baselines");
            }
            Check(health.CurrentHealth == hp && playerChanges == 0 && monitor.RecoveryRequested == requests &&
                monitor.RecoveryCompleted == recoveries && motor.AcceptedJumpCount == jumps && motor.AcceptedDashCount == dashes,
                "no player HP/heal/death/recovery/jump/dash changes");
            Clock();
            Check(player.GlobalPosition.IsFinite() && player.Velocity.IsFinite() && boss.GlobalPosition.IsFinite() &&
                boss.Velocity.IsFinite() && Gap() > 60f && float.IsFinite(energy.EnergyRatio) && float.IsFinite(energy.HeatRatio),
                "finite left-flank poses/resources, no crossing");
            Check(!floorShape.Disabled && !bodyShape.Disabled && !hurtShape.Disabled &&
                (fatalDamage != null || !entryDoor.Disabled && !exitDoor.Disabled) && Supported(),
                "full original ArenaFloor upward support, closed doors until attributed fatal damage");
            Rect2 body = Bounds(bodyShape), entry = Bounds(entryDoor), exit = Bounds(exitDoor);
            Check(body.Position.X > entry.End.X && body.End.X < exit.Position.X && !body.Intersects(entry) &&
                !body.Intersects(exit), "positive whole-body closed-door clearance");
            Check(!input.CurrentFrame.JumpPressed && !input.CurrentFrame.JumpHeld && !input.CurrentFrame.DashPressed &&
                !input.CurrentFrame.ShieldHeld && !shield.IsActive && !motor.IsDashing &&
                (!input.CurrentFrame.AttackPressed || keyboardOpening && strikeIssued &&
                    input.CurrentFrameSequence > strikeIssue &&
                    (Input.IsActionPressed(InputActions.Attack) || input.CurrentFrameSequence == strikeSample)) &&
                !input.CurrentFrame.ThreadPressed && !input.CurrentFrame.ThreadHeld && !input.CurrentFrame.ThreadReleased,
                "no Space/dash/shield/legacy attacks");
            if (keyboardOpening)
                Check(!input.CurrentFrame.PrimaryPressed && !input.CurrentFrame.PrimaryHeld &&
                    !input.CurrentFrame.GrappleModePressed && !input.CurrentFrame.AttackModePressed &&
                    !input.CurrentFrame.InteractPressed &&
                    (!input.CurrentFrame.ClawPressed || castIssued && input.CurrentFrameSequence > castIssue),
                    "keyboard opening has no legacy/mode/Q edge and only its owned K/J windows");
            Check(bossHealth.CurrentHealth == expectedEntryBossHp - damaged && damaged <= 1 && accepted <= 1 && connected <= 1 &&
                adapter.ApplicationCount >= applications && adapter.ApplicationCount <= applications + (castIssued ? 1 : 0) &&
                claw.CurrentFrame.NextCastId >= nextCast && claw.CurrentFrame.NextCastId <= nextCast + (castIssued ? 1UL : 0UL) &&
                claw.CurrentFrame.Failure == MechanicalClawFailure.None && !claw.CurrentFrame.BoostConsumed,
                $"one cast/application and exact Boss{expectedEntryBossHp}→{expectedEntryBossHp - 1} only");
            if (!castIssued) Check(Idle(), "target-free Idle before only cast");
            if (fatalDamage != null)
                Check(bossHealth.CurrentHealth == 0 && damaged == 1 && accepted == 1 && Stationary() && Idle() &&
                    boss.CurrentFrame.State is FallenBellkeeperState.Exposed or FallenBellkeeperState.Defeated &&
                    !boss.CurrentFrame.AttackActive && adapter.ApplicationCount == applications + 1 &&
                    claw.CurrentFrame.NextCastId == nextCast + 1, "only attributed fatal Exposed→Defeated, stationary original flank/counters");
            else if (firstHammer != 0 && boss.CurrentFrame.State != FallenBellkeeperState.Exposed)
                Check(boss.CurrentFrame.State is FallenBellkeeperState.HammerTelegraph or FallenBellkeeperState.HammerThrown,
                    "first Hammer window cannot expire/roll into recovery or a second cycle");
            if (exposureObserved && fatalDamage == null) Check(boss.CurrentFrame.State == FallenBellkeeperState.Exposed, "first exposure cannot expire/retry");
            if (callbackFailure != null) throw new InvalidOperationException("Task10 first exposure callback failure", callbackFailure);
        }
        void Log(string boundary, string details = "")
        {
            Native(); AttackTimelineFrame t = presentation.Timeline;
            string clearance = CurrentHammer() ? HammerClearance().ToString("R") : "not-current-Hammer";
            GD.Print($"TASK10_BOSS_PHASE2 boundary={boundary} expected_entry_hp={expectedEntryBossHp} stage={stage} physics={Engine.GetPhysicsFrames()} waits={waits}/600 " +
                $"input_sequence={input.CurrentFrameSequence} player={playerId} boss={bossId} HP={health.CurrentHealth}/{hp} bossHP={bossHealth.CurrentHealth} " +
                $"pose={player.GlobalPosition} velocity={player.Velocity} boss_pose={boss.GlobalPosition} gap={Gap():R} full_floor={Supported()} " +
                $"state={boss.CurrentFrame.State} attack={t.AttackId}/{t.Kind}/{t.Phase} remaining={t.PhaseRemainingSeconds:R} locked={t.HasLockedTarget} " +
                $"shape={presentation.Shape.Kind}/{presentation.Shape.Origin}/{presentation.Shape.Extent}/{presentation.Shape.RotationRadians:R} clearance={clearance} " +
                $"hurtbox_bounds={Bounds(hurtShape)} hammer_transform={hammerShape.GlobalTransform} chain={chainId}/{chain.WorldAnchor} " +
                $"distance={player.GlobalPosition.DistanceTo(chain.WorldAnchor):R} energy={energy.EnergyRatio:R} heat={energy.HeatRatio:R} " +
                $"mode={modes.CurrentMode}/{modes.ActiveSlot} claw={claw.CurrentFrame.State}/{claw.CurrentFrame.CastId}/{claw.CurrentFrame.NextCastId} " +
                $"adapter={adapter.ApplicationCount}/{applications} accepted={accepted} damaged={damaged} connected={connected} " +
                $"exposure_entry_physics={exposureEntryPhysics} exposure_measured_elapsed={exposureElapsed:R} exposure_configured_seconds={exposureSeconds:R} " +
                $"current_delta={(float)boss.GetPhysicsProcessDeltaTime():R} exposure_remaining_lower_bound={(fatalDamage != null ? fatalDamage.RemainingLowerBound.ToString("R") : exposureObserved ? ExposureLowerBound().ToString("R") : "unavailable")} {details}");
        }
        void Callback(Action action) { try { Native(); action(); } catch (Exception error) { callbackFailure ??= error; } }
        void AdmissionDiagnostic(string boundary, Action capture)
        {
            if (admissionDiagnosticRecords >= 8 || !admissionDiagnosticKeys.Add(boundary + "/" + stage)) return;
            admissionDiagnosticRecords++;
            try { Native(); capture(); }
            catch (Exception error)
            {
                admissionDiagnosticFaults++;
                try { GD.Print($"TASK10_BOSS_PHASE2_ADMISSION boundary={boundary} diagnostic_gap={error.GetType().Name} " +
                    $"records={admissionDiagnosticRecords}/8 diagnostic_faults={admissionDiagnosticFaults}"); }
                catch { /* Passive diagnostics never replace the original admission assertion. */ }
            }
        }
        (bool admitted, Vector2 point, Vector2 local, Vector2 screen, float radius, Transform2D transform) PointerAdmission()
        {
            Native(); Transform2D transform = Uniform(chainShape);
            Check(chainShape.Shape is CircleShape2D, "actual chain circle for sampled pointer containment");
            float radius = ((CircleShape2D)chainShape.Shape).Radius;
            float determinant = transform.Determinant();
            Check(float.IsFinite(radius) && radius > 0f && float.IsFinite(determinant) && determinant > 0f,
                "finite positive chain radius/invertible collider transform");
            Vector2 point = input.CurrentFrame.MouseWorld;
            Vector2 local = transform.AffineInverse() * point;
            Vector2 screen = player.GetViewport().GetCanvasTransform() * point;
            float localDistance = local.Length();
            bool admitted = point.IsFinite() && local.IsFinite() && screen.IsFinite() && float.IsFinite(localDistance) &&
                localDistance < radius && player.GetViewport().GetVisibleRect().HasPoint(screen) &&
                !chainShape.Disabled && chain.IsAvailable;
            return (admitted, point, local, screen, radius, transform);
        }
        void CaptureAimAdmission(MechanicalClawFrame frame, GrappleSurface2D target)
        {
            if (frame.State != MechanicalClawState.Aim) return;
            if (keyboardOpening)
            {
                AdmissionDiagnostic("KEYBOARD_AIM_PRECHECK", () =>
                    GD.Print($"TASK10_BOSS_PHASE2_KEYBOARD_AIM stage={stage} physics={Engine.GetPhysicsFrames()} " +
                        $"sequence={input.CurrentFrameSequence} ready={keyboardCastReady} cast_issue={castIssue} " +
                        $"K={input.CurrentFrame.ClawPressed} J={input.CurrentFrame.AttackPressed} " +
                        $"direction={input.KeyboardAimDirection} axis={input.CurrentFrame.Aim} " +
                        $"target={(Live(target) ? target.GetInstanceId() : 0UL)}/{chainId} " +
                        $"current={(Live(claw.CurrentTarget) ? claw.CurrentTarget.GetInstanceId() : 0UL)} " +
                        $"anchor={frame.AnchorPoint} legacy_primary={input.CurrentFrame.PrimaryPressed}"));
                return;
            }
            AdmissionDiagnostic("AIM_PRECHECK", () =>
            {
                PlayerInputFrame sampled = input.CurrentFrame;
                ulong sequence = input.CurrentFrameSequence;
                Vector2 anchor = chain.WorldAnchor;
                float aimError = sampled.MouseWorld.DistanceTo(anchor);
                bool fresh = sequence > castIssue, modeReady = modes.CanBeginGrapple;
                bool combatInactive = !combat.IsAttacking, mouseFinite = sampled.MouseWorld.IsFinite();
                var pointer = PointerAdmission();
                bool targetLive = Live(target), currentTargetLive = Live(claw.CurrentTarget);
                bool selectedChain = targetLive && currentTargetLive && target == chain && claw.CurrentTarget == chain &&
                    target.GetInstanceId() == chainId && claw.CurrentTarget.GetInstanceId() == chainId &&
                    frame.AnchorPoint.IsFinite() && frame.AnchorPoint.DistanceTo(anchor) <= .01f &&
                    frame.EffectiveVisibility && claw.CurrentFrame == frame;
                bool precedingConjuncts = fresh && sampled.PrimaryPressed && modeReady && combatInactive && pointer.admitted;
                GD.Print($"TASK10_BOSS_PHASE2_ADMISSION boundary=AIM_PRECHECK stage={stage} physics={Engine.GetPhysicsFrames()} " +
                    $"input_sequence={sequence} e_issue={eIssue} e_sample={eSample} cast_issue={castIssue} cast_sample={castSample} " +
                    $"cast_issued={castIssued} E_fresh={eSample > eIssue} cast_after_E={castIssue > eSample} input_after_cast_issue={fresh} " +
                    $"frame={frame.State}/{frame.CastId}/{frame.NextCastId} primary_pressed={sampled.PrimaryPressed} primary_held={sampled.PrimaryHeld} " +
                    $"mode={modes.CurrentMode} can_begin_grapple={modeReady} shield_held={sampled.ShieldHeld} combat_is_attacking={!combatInactive} " +
                    $"sampled_mouse_world={sampled.MouseWorld} live_chain_anchor={anchor} mouse_finite={mouseFinite} anchor_finite={anchor.IsFinite()} " +
                    $"cursor_anchor_error_diagnostic={aimError:R} pointer_gate={pointer.admitted} pointer_local={pointer.local} pointer_screen={pointer.screen} " +
                    $"circle_radius={pointer.radius:R} collider_transform={pointer.transform} pointer_local_finite={pointer.local.IsFinite()} " +
                    $"pointer_screen_finite={pointer.screen.IsFinite()} pointer_inside={pointer.local.Length() < pointer.radius} " +
                    $"pointer_onscreen={player.GetViewport().GetVisibleRect().HasPoint(pointer.screen)} target_collision_disabled={chainShape.Disabled} chain_available={chain.IsAvailable} " +
                    $"event_target_live={targetLive} event_target_id={(targetLive ? target.GetInstanceId() : 0UL)}/{chainId} " +
                    $"current_target_live={currentTargetLive} current_target_id={(currentTargetLive ? claw.CurrentTarget.GetInstanceId() : 0UL)}/{chainId} " +
                    $"event_target_exact={target == chain} current_target_exact={claw.CurrentTarget == chain} frame_anchor={frame.AnchorPoint} " +
                    $"frame_anchor_finite={frame.AnchorPoint.IsFinite()} canonical_anchor_error={frame.AnchorPoint.DistanceTo(anchor):R} " +
                    $"effective_visibility={frame.EffectiveVisibility} current_frame_exact={claw.CurrentFrame == frame} selected_chain={selectedChain} " +
                    $"preceding_outer_conjuncts={precedingConjuncts} " +
                    $"chain_gate={(precedingConjuncts ? "PENDING_EXISTING_EVALUATION" : "NOT_EVALUATED_SHORT_CIRCUIT")} " +
                    $"records={admissionDiagnosticRecords}/8 diagnostic_faults={admissionDiagnosticFaults}");
            });
        }
        void CaptureChainAdmission(int samplingReserve, bool available, MechanicalClawTargetResolution resolution,
            Vector2 anchor, Vector2 screen, float distance)
        {
            AdmissionDiagnostic("CHAIN_GATE_" + samplingReserve, () =>
            {
                bool surfaceLive = Live(resolution.Surface);
                float remaining = presentation.Timeline.PhaseRemainingSeconds;
                float required = distance / settings.ShuttleSpeed + samplingReserve / (float)ticks + .10f;
                GD.Print($"TASK10_BOSS_PHASE2_ADMISSION boundary=CHAIN_GATE_{samplingReserve} stage={stage} physics={Engine.GetPhysicsFrames()} " +
                    $"input_sequence={input.CurrentFrameSequence} chain_gate_evaluated=True available_result={available} time_gate={remaining > required} " +
                    $"keyboard={keyboardOpening} raw_aim={input.CurrentFrame.Aim} direction={input.KeyboardAimDirection} " +
                    $"move={input.CurrentFrame.MoveAxis} velocity={player.Velocity} gap={Gap():R} " +
                    $"cast_stance={ChainStationary()} melee_stance={Stationary()} " +
                    $"remaining={remaining:R} required={required:R} distance={distance:R} target_collision_disabled={chainShape.Disabled} " +
                    $"chain_available={chain.IsAvailable} legacy_kind={chain.Kind.IsLegacyInteraction()} surface_live={surfaceLive} " +
                    $"exact_surface={resolution.Surface == chain} surface_id={(surfaceLive ? resolution.Surface.GetInstanceId() : 0UL)} " +
                    $"snapshot_exists={resolution.Snapshot.Exists} runtime_id={resolution.Snapshot.RuntimeId}/{chainId} " +
                    $"snapshot_anchor={resolution.Snapshot.WorldAnchor} live_anchor={anchor} anchor_error={resolution.Snapshot.WorldAnchor.DistanceTo(anchor):R} " +
                    $"snapshot_legacy={resolution.Snapshot.IsLegacyInteraction} LOS={resolution.Snapshot.HasLineOfSight} " +
                    $"anchor_finite={anchor.IsFinite()} screen={screen} screen_finite={screen.IsFinite()} " +
                    $"onscreen={player.GetViewport().GetVisibleRect().HasPoint(screen)} distance_finite={float.IsFinite(distance)} range_gate={distance <= settings.MaxRange} " +
                    $"records={admissionDiagnosticRecords}/8 diagnostic_faults={admissionDiagnosticFaults}");
            });
        }
        void OnPresentation(AttackPresentationFrame frame) => Callback(() =>
        {
            presentation = frame.Timeline.Phase == AttackPhase.None ? frame : frame.Validate(); publication++;
            if (frame.Timeline.Kind != EnemyAttackKind.BossHammerThrow) return;
            firstHammer = firstHammer == 0 ? frame.Timeline.AttackId : firstHammer;
            Check(frame.Timeline.AttackId == firstHammer && frame.Timeline.Phase is AttackPhase.Telegraph or AttackPhase.Active,
                "only first observed Hammer identity/active window");
            if (fatal) Check(firstHammer != priorReceipt.HammerId, "seventh opening has a fresh actual Hammer identity");
        });
        void OnBossFrame(FallenBellkeeperFrame frame, int facing) => Callback(() =>
        {
            Clock();
            completedPublication = publication;
            ulong physics = Engine.GetPhysicsFrames(); float delta = (float)boss.GetPhysicsProcessDeltaTime();
            Check(lastBossPhysics == 0 || physics == lastBossPhysics + 1, "one monotonic physics-driven Boss publication per step");
            Check(float.IsFinite(delta) && delta > 0f && Mathf.Abs(delta - stepDelta) <= .000001f, "unchanged actual publication delta");
            lastBossPhysics = physics;
            if (fatalDamage != null)
            {
                Check(frame == boss.CurrentFrame && frame.State == FallenBellkeeperState.Defeated &&
                    bossHealth.CurrentHealth == 0 && !frame.AttackActive && !frame.ChainTargetActive &&
                    frame.AttackTimeline.Phase == AttackPhase.None && diedEvents == 1 && arenaEvents == 1,
                    "actual post-fatal Defeated physics publication after both genuine signals");
                if (defeatedPhysics == 0) defeatedPhysics = physics;
                return; // Death presentation never advances the retained Exposed clock.
            }
            if (frame.State != FallenBellkeeperState.Exposed) return;
            if (!exposureObserved)
            {
                Check(frame.EnteredState && firstHammer != 0 && activeSeen && travel && latched && released &&
                    adapter.ApplicationCount == applications + 1, "first actual entry attributed to one completed legacy chain");
                // Model TransitionTo resets elapsed to zero before this very same step's FrameChanged.
                exposureObserved = true; exposureEntryPhysics = physics; exposureElapsed = 0f;
            }
            else { Check(!frame.EnteredState, "no repeated exposure entry"); exposureElapsed += delta; }
        });
        void OnClaw(MechanicalClawFrame frame, GrappleSurface2D target) => Callback(() =>
        {
            if (frame.State == MechanicalClawState.Aim)
            {
                pointerTrace?.Snapshot("first_Aim_before_admission_assertion");
                pointerTrace?.Freeze("first_aim_observed");
            }
            Check(frame.Failure == MechanicalClawFailure.None && !frame.BoostConsumed && frame.State != MechanicalClawState.Boost,
                "no cast failure/boost publication");
            if (frame.State == MechanicalClawState.Idle) return;
            Check(castIssued && (keyboardOpening
                ? keyboardCastReady > eIssue && castIssue >= keyboardCastReady
                : eSample > eIssue && castIssue > eSample), "only cast after separately witnessed input readiness");
            CaptureAimAdmission(frame, target);
            if (frame.State == MechanicalClawState.Aim)
            {
                Check(input.CurrentFrameSequence > castIssue &&
                    (keyboardOpening ? input.CurrentFrame.KeyboardActions && input.CurrentFrame.ClawPressed &&
                        !input.CurrentFrame.AttackPressed && input.CurrentFrame.MoveAxis == 0f &&
                        input.KeyboardAimDirection.Dot(Vector2.Right) > .99f : input.CurrentFrame.PrimaryPressed) &&
                    modes.CanBeginGrapple && !combat.IsAttacking &&
                    (keyboardOpening || PointerAdmission().admitted) &&
                    ChainGate(12), "fresh exact actual LMB admission");
                Check(Live(target) && Live(claw.CurrentTarget) && target == chain && claw.CurrentTarget == chain &&
                    target.GetInstanceId() == chainId && claw.CurrentTarget.GetInstanceId() == chainId &&
                    frame.AnchorPoint.IsFinite() && frame.AnchorPoint.DistanceTo(chain.WorldAnchor) <= .01f &&
                    frame.EffectiveVisibility && claw.CurrentFrame == frame, "actual sampled-pointer production-selected chain/anchor/visibility/frame");
            }
            if (frame.State is MechanicalClawState.Windup or MechanicalClawState.Travel or MechanicalClawState.Latched)
            {
                Check(Live(target) && target == chain && frame.CastId == nextCast && frame.NextCastId == nextCast + 1 &&
                    frame.AnchorPoint.DistanceTo(chain.WorldAnchor) <= .01f, "exact chain/unique cast token and live anchor");
                if (frame.State is MechanicalClawState.Travel or MechanicalClawState.Latched)
                    Check(frame.LockedTargetRuntimeId == chainId, "exact locked chain runtime id");
            }
            if (frame.State == MechanicalClawState.Travel) travel = true;
            if (frame.State == MechanicalClawState.Latched) { Check(travel && !latched, "one ordered latch"); latched = true; }
            if (frame.State == MechanicalClawState.Released)
            {
                Check(latched && !released && frame.CastId == nextCast && frame.ReleaseKind == MechanicalClawReleaseKind.Cancel &&
                    adapter.ApplicationCount == applications + 1, "one production legacy release after accepted application"); released = true;
            }
            if (loggedClaw != frame.State) { loggedClaw = frame.State; Log(frame.State == MechanicalClawState.Latched ? "LATCHED" : "CAST_EVENT"); }
        });
        bool HitInterval() => attackId != 0 && Engine.GetPhysicsFrames() >= attackPhysics &&
            Engine.GetPhysicsFrames() - attackPhysics <= (ulong)attackInterval && combat.IsAttacking;
