        bool ChainGate(int samplingReserve)
        {
            Native(); Check(CurrentHammer() && presentation.Timeline.Phase == AttackPhase.Active &&
                boss.CurrentFrame.State == FallenBellkeeperState.HammerThrown && boss.CurrentFrame.AttackActive &&
                boss.CurrentFrame.ArmorClosed && boss.CurrentFrame.ChainTargetActive && bossHealth.CurrentHealth == expectedEntryBossHp &&
                ChainStationary() && HammerClearance() >= 2f, "actual first Active Hammer safety/admission at its stationary cast stance");
            Vector2 anchor = chain.WorldAnchor;
            MechanicalClawTargetResolution resolution = keyboardOpening
                ? resolver.ResolveKeyboard(player, input.KeyboardAimDirection)
                : resolver.Resolve(player, anchor);
            Vector2 screen = player.GetGlobalTransformWithCanvas() * player.ToLocal(anchor);
            float distance = player.GlobalPosition.DistanceTo(anchor);
            bool available = !chainShape.Disabled && chain.IsAvailable && chain.Kind.IsLegacyInteraction() &&
                chain.TryGetEligibleReceiver(player, out Node receiver) && Live(receiver) && receiver == boss &&
                resolution.Surface == chain && resolution.Snapshot.Exists && resolution.Snapshot.RuntimeId == chainId &&
                resolution.Snapshot.WorldAnchor.DistanceTo(anchor) <= .01f && resolution.Snapshot.IsLegacyInteraction &&
                resolution.Snapshot.HasLineOfSight && anchor.IsFinite() && screen.IsFinite() &&
                player.GetViewport().GetVisibleRect().HasPoint(screen) && float.IsFinite(distance) && distance <= settings.MaxRange;
            if (keyboardOpening)
                available &= input.CurrentFrame.KeyboardActions && input.CurrentFrame.Aim == Vector2.Zero &&
                    input.KeyboardAimDirection.Dot(Vector2.Right) > .99f;
            CaptureChainAdmission(samplingReserve, available, resolution, anchor, screen, distance);
            Check(presentation.Timeline.PhaseRemainingSeconds > distance / settings.ShuttleSpeed + samplingReserve / (float)ticks + .10f,
                $"conservative first-Hammer time gate reserve={samplingReserve} distance={distance:R}");
