        void ObserveCourtyardBellClaw(MechanicalClawFrame frame, GrappleSurface2D actualTarget)
        {
            if (!courtyardBellIssued || courtyardBellComplete) return;
            if (frame.Failure != MechanicalClawFailure.None) courtyardBellInvalidReceipt = true;
            if (frame.State is not (MechanicalClawState.Latched or MechanicalClawState.Released)) return;
            bool sameCast = frame.CastId == courtyardBellCast && frame.NextCastId == courtyardBellCast + 1 &&
                frame.LockedTargetRuntimeId == courtyardBellTarget.GetInstanceId();
            bool actualApplication = courtyardBellAdapter.ApplicationCount == courtyardBellApplications + 1;
            bool cleanInput = input.CurrentFrameSequence > courtyardBellIssueSequence &&
                input.CurrentFrame.KeyboardActions && !input.CurrentFrame.AttackPressed && !input.CurrentFrame.ShieldHeld &&
                !input.CurrentFrame.JumpPressed && !input.CurrentFrame.DashPressed && !input.CurrentFrame.PrimaryPressed;
            if (frame.State == MechanicalClawState.Latched)
            {
                courtyardBellReceipt = sameCast && actualApplication && cleanInput && actualTarget == courtyardBellTarget;
                courtyardBellReceiptSequence = input.CurrentFrameSequence;
                courtyardBellReceiptPhysics = Engine.GetPhysicsFrames();
                courtyardBellInvalidReceipt |= !courtyardBellReceipt;
                CourtyardBellSnapshot("opening-latched-adapter-receipt");
            }
            else
            {
                courtyardBellReleased = courtyardBellReceipt && sameCast && actualApplication && cleanInput && actualTarget == null;
                courtyardBellInvalidReceipt |= !courtyardBellReleased;
                CourtyardBellSnapshot("opening-released-receipt");
            }
