        bool SplitMothCastWindow(GraveLampMoth moth)
        {
            if (!splitBellKeyboard && !frozenLowerKeyboard) return currentFrame % 60 == 0;
            // Mode prefix2 + admission<=8 + Aim/Windup2 + latch/safety2,
            // plus actual flight distance at the production shuttle speed.
            float leadSeconds = player.GlobalPosition.DistanceTo(moth.GlobalPosition) /
                MechanicalClawSettings.Default.ShuttleSpeed + 14f / Engine.PhysicsTicksPerSecond;
            bool early = (moth.CurrentState is GraveLampMothState.Hover or GraveLampMothState.Align) ||
                moth.CurrentState == GraveLampMothState.Telegraph &&
                moth.CurrentFrame.AttackTimeline.PhaseRemainingSeconds > leadSeconds;
            return early && !combat.IsAttacking && modes.CanBeginGrapple &&
                player.GetNode<MechanicalClawController>("MechanicalClaw").CurrentFrame.State == MechanicalClawState.Idle;
