        var splitIdentityCache = new Dictionary<ulong, string>();
        string SplitIdentity(Node node)
        {
            if (!DiagnosticLive(node)) return "unavailable";
            ulong id = node.GetInstanceId();
            if (!splitIdentityCache.TryGetValue(id, out string identity))
            {
                identity = $"{node.GetPath()}#{id}";
                splitIdentityCache[id] = identity;
            }
            return identity;
