        string SplitObservation(out string key, out string castIds)
        {
            // These are previous actually sampled inputs, never acknowledgement of the
            // intended movement whose SendAction calls have not happened at this location.
            bool playerLive = DiagnosticLive(player), mothLive = DiagnosticLive(splitMoth);
            bool inputLive = DiagnosticLive(input), modesLive = DiagnosticLive(modes);
            bool clawLive = DiagnosticLive(splitClaw), shieldLive = DiagnosticLive(shield);
            PlayerInputFrame sampled = inputLive ? input.CurrentFrame : default;
            MechanicalClawFrame claw = clawLive ? splitClaw.CurrentFrame : default;
            HealthComponent mothHealth = mothLive
                ? splitMoth.GetNodeOrNull<HealthComponent>("Health") : null;
            string mothState = mothLive ? splitMoth.CurrentState.ToString() : "unavailable";
            string hp = DiagnosticLive(playerHealth) ? playerHealth.CurrentHealth.ToString() : "unavailable";
            string enemyHp = DiagnosticLive(mothHealth) ? mothHealth.CurrentHealth.ToString() : "unavailable";
            string mode = modesLive ? modes.CurrentMode.ToString() : "unavailable";
            string slot = modesLive ? modes.ActiveSlot.ToString() : "unavailable";
            string canGrapple = modesLive ? modes.CanBeginGrapple.ToString() : "unavailable";
            string shieldActive = shieldLive ? shield.IsActive.ToString() : "unavailable";
            string clawTarget = clawLive ? SplitIdentity(splitClaw.CurrentTarget) : "unavailable";
            var contacts = new List<string>();
