            Vector2 mothPosition = mothLive ? splitMoth.GlobalPosition : Vector2.Zero;
            string actualGap = playerLive && mothLive
                ? $"dx={mothPosition.X - playerPosition.X:R} dy={mothPosition.Y - playerPosition.Y:R}"
                : "dx=unavailable dy=unavailable";
            return $"physics={Engine.GetPhysicsFrames()} loop={currentFrame} moth={splitMothIdentity} " +
                $"moth_live={mothLive} moth_xy={(mothLive ? mothPosition.ToString() : "unavailable")} " +
                $"moth_velocity={(mothLive ? splitMoth.Velocity.ToString() : "unavailable")} moth_state={mothState} moth_hp={enemyHp} " +
                $"player_live={playerLive} player_xy={(playerLive ? playerPosition.ToString() : "unavailable")} " +
                $"player_velocity={(playerLive ? player.Velocity.ToString() : "unavailable")} floor={(playerLive && player.IsOnFloor())} " +
                $"{actualGap} intended_left={splitIntendedLeft} intended_right={splitIntendedRight} " +
                $"dy_gate={dyGate} cadence_gate={cadence} gate_kind={(splitBellKeyboard ? "early_non_dive" : "legacy60")} " +
                $"combined_gate={dyGate && cadence} strike_eligible={splitStrikeEligible} " +
                $"input_live={inputLive} previous_sample_sequence={(inputLive ? input.CurrentFrameSequence : 0)} " +
                $"previous_sample_move={sampled.MoveAxis} primary={sampled.PrimaryPressed}/{sampled.PrimaryHeld} shield_held={sampled.ShieldHeld} " +
                $"mode={mode} slot={slot} can_begin_grapple={canGrapple} shield_active={shieldActive} " +
                $"claw_live={clawLive} claw_state={claw.State} claw_failure={claw.Failure} cast_id={claw.CastId} next_cast_id={claw.NextCastId} " +
                $"claw_target={clawTarget} locked_target_id={claw.LockedTargetRuntimeId} player_hp={hp} " +
                $"recoveries={monitor.RecoveryRequested}/{monitor.RecoveryCompleted} contacts=[{string.Join(';', contacts)}]";
