        void SteamSnapshot(string reason, bool eventLine = false, string detail = "")
        {
            if (!SteamWindow()) return;
            if (eventLine)
            {
                if (reason == "player_damaged")
                {
                    if (sentryDamageEvents >= 12) return;
                    sentryDamageEvents++;
                }
                else if (reason == "bolt_connected")
                {
                    if (sentryConnectedEvents >= 12) return;
                    sentryConnectedEvents++;
                }
                else
                {
                    if (sentryShieldEvents >= 24) return;
                    sentryShieldEvents++;
                }
            }
            else
            {
                if (sentrySnapshotCount >= 24) return;
                sentrySnapshotCount++;
            }
            bool sentryLive = GodotObject.IsInstanceValid(trackedSentry) &&
                trackedSentry.IsInsideTree();
