            bool healthLive = GodotObject.IsInstanceValid(playerHealth) && playerHealth.IsInsideTree();
            bool shieldLive = GodotObject.IsInstanceValid(shield) && shield.IsInsideTree();
            bool combatLive = GodotObject.IsInstanceValid(combat) && combat.IsInsideTree();
            bool modesLive = GodotObject.IsInstanceValid(modes) && modes.IsInsideTree();
            bool energyLive = GodotObject.IsInstanceValid(energy) && energy.IsInsideTree();
            BellBoltSentryFrame sentryFrame = sentryLive ? trackedSentry.CurrentFrame : default;
            AttackTimelineFrame timeline = sentryFrame.AttackTimeline;
            GD.Print($"TASK10_STEAM_SENTRY_{(eventLine ? "EVENT" : "STATE")} reason={reason} " +
