        void SteamPolicyLog(string reason, string detail = "")
        {
            if (sentryPolicyLines++ >= 40) return;
            GD.Print($"TASK10_STEAM_POLICY reason={reason} physics={Engine.GetPhysicsFrames()} " +
                $"loop={currentFrame} sample={input.CurrentFrameSequence} " +
                $"player={player.GlobalPosition} hp={playerHealth.CurrentHealth} " +
                $"energy={energy.EnergyRatio:0.000} heat={energy.HeatRatio:0.000} " +
