        Hitbox.ConnectedEventHandler boltConnected = targetHurtbox =>
        {
            string targetIdentity = GodotObject.IsInstanceValid(targetHurtbox) &&
                targetHurtbox.IsInsideTree()
                ? $"{targetHurtbox.GetPath()}#{targetHurtbox.GetInstanceId()}" : "unavailable";
            bool isPlayer = GodotObject.IsInstanceValid(targetHurtbox) &&
                GodotObject.IsInstanceValid(playerHurtbox) &&
