        void ObserveSteamBolt()
        {
            if (!GodotObject.IsInstanceValid(trackedSentry) || !trackedSentry.IsInsideTree()) return;
            BellBoltProjectile bolt = trackedSentry.GetChildren().OfType<BellBoltProjectile>()
                .FirstOrDefault(candidate => GodotObject.IsInstanceValid(candidate) &&
                    candidate.IsInsideTree() && !candidate.IsRetired);
            if (ReferenceEquals(bolt, trackedBolt)) return;
            if (GodotObject.IsInstanceValid(trackedBoltHitbox))
                trackedBoltHitbox.Connected -= boltConnected;
            trackedBolt = bolt;
            trackedBoltHitbox = null;
            if (bolt == null) return;
            boltIdentity = $"{bolt.GetPath()}#{bolt.GetInstanceId()}";
            trackedBoltHitbox = bolt.GetNodeOrNull<Hitbox>("Hitbox");
            hitboxIdentity = GodotObject.IsInstanceValid(trackedBoltHitbox) &&
                trackedBoltHitbox.IsInsideTree()
                ? $"{trackedBoltHitbox.GetPath()}#{trackedBoltHitbox.GetInstanceId()}" : "unavailable";
            if (GodotObject.IsInstanceValid(trackedBoltHitbox))
                trackedBoltHitbox.Connected += boltConnected;
            SteamSnapshot("bolt_discovered");
        }

        Action<BellBoltSentryFrame> sentryFrameChanged = frame =>
        {
            if (!SteamWindow()) return;
            ObserveSteamBolt();
            bool changed = frame.State.ToString() != lastSentryState ||
                frame.AttackTimeline.AttackId != lastSentryAttackId ||
                frame.AttackTimeline.Phase != lastSentryPhase ||
                frame.AttackTimeline.HasLockedTarget != lastSentryLock;
            lastSentryState = frame.State.ToString();
            lastSentryAttackId = frame.AttackTimeline.AttackId;
            lastSentryPhase = frame.AttackTimeline.Phase;
            lastSentryLock = frame.AttackTimeline.HasLockedTarget;
            if (frame.FireRequested) SteamSnapshot("fire_requested");
            else if (changed) SteamSnapshot("state_or_timeline_change");
            else if (GodotObject.IsInstanceValid(trackedBolt) && !trackedBolt.IsRetired &&
                (Engine.GetPhysicsFrames() - sentryStartPhysics) % 10 == 0)
                SteamSnapshot("bolt_10_frames");
        };
        Action<PlayerShieldResult, ulong> sentryShieldResolved = (result, transitionId) =>
