        string GearDiagnosticFloor()
        {
            if (!GodotObject.IsInstanceValid(player) || !player.IsInsideTree())
                return "unavailable_player";
            if (!player.IsOnFloor()) return "airborne";
            for (int index = 0; index < player.GetSlideCollisionCount(); index++)
            {
                KinematicCollision2D collision = player.GetSlideCollision(index);
                if (!GodotObject.IsInstanceValid(collision)) return "invalid_contact";
                if (collision.GetNormal().Y >= -.7f) continue;
                GodotObject collider = collision.GetCollider();
                if (!GodotObject.IsInstanceValid(collider)) return "invalid_collider";
                if (collider is Node node)
                    return node.IsInsideTree()
                        ? $"{node.GetPath()}#{node.GetInstanceId()}"
                        : $"detached_collider#{node.GetInstanceId()}";
                return collider.GetInstanceId().ToString();
            }
            return "floor_without_slide_collider";
        }

        void GearDiagnosticSnapshot(string reason, Vector2? suppliedImpulse = null)
        {
            if (!gearDiagnostic || !GodotObject.IsInstanceValid(player) ||
                !GodotObject.IsInstanceValid(input) || !GodotObject.IsInstanceValid(energy) ||
                !GodotObject.IsInstanceValid(shield) || !GodotObject.IsInstanceValid(playerHealth)) return;
            bool laneValid = GodotObject.IsInstanceValid(diagnosticLane);
            CollisionShape2D laneCollider = laneValid
                ? diagnosticLane.GetNodeOrNull<CollisionShape2D>("Collision") : null;
            Rect2? laneEnvelope = GodotObject.IsInstanceValid(laneCollider) &&
                laneCollider.Shape is RectangleShape2D rectangle && GodotObject.IsInstanceValid(rectangle)
                ? WorldEnvelope(laneCollider, rectangle.Size / 2f) : null;
            CapsuleShape2D capsule = GodotObject.IsInstanceValid(diagnosticCapsule)
                ? diagnosticCapsule.Shape as CapsuleShape2D : null;
            if (!GodotObject.IsInstanceValid(capsule)) capsule = null;
            Rect2? capsuleEnvelope = capsule != null
                ? WorldEnvelope(diagnosticCapsule, new Vector2(capsule.Radius, capsule.Height / 2f)) : null;
            bool centerInside = laneEnvelope?.HasPoint(player.GlobalPosition) ?? false;
            bool capsuleAabbOverlap = laneEnvelope.HasValue && capsuleEnvelope.HasValue &&
                laneEnvelope.Value.Intersects(capsuleEnvelope.Value);
            bool monitoredOverlap = laneValid && diagnosticLane.GetOverlappingBodies().Contains(player);
            Node2D liveActor = GodotObject.IsInstanceValid(actorRoot)
                ? actorRoot.GetChildren().OfType<Node2D>().FirstOrDefault(candidate =>
                    GodotObject.IsInstanceValid(candidate) && candidate.Name.ToString().StartsWith(
                        encounterId.Replace('.', '_'), StringComparison.Ordinal)) : null;
            bool actorValid = GodotObject.IsInstanceValid(liveActor);
            string actorState = liveActor switch
            {
                RustShellSquire rust => rust.CurrentState.ToString(),
                BellBackLaborer bell => bell.CurrentState.ToString(),
                _ => "unreported"
            };
            string actorPhase = liveActor switch
            {
                RustShellSquire rust => rust.CurrentFrame.AttackTimeline.Phase.ToString(),
                BellBackLaborer bell => bell.CurrentFrame.AttackTimeline.Phase.ToString(),
                _ => "unreported"
            };
            Hitbox actorHitbox = actorValid ? liveActor.GetNodeOrNull<Hitbox>("AttackHitbox") : null;
            bool hitboxMonitoring = GodotObject.IsInstanceValid(actorHitbox) && actorHitbox.Monitoring;
            CollisionShape2D hitboxCollider = GodotObject.IsInstanceValid(actorHitbox)
                ? actorHitbox.GetNodeOrNull<CollisionShape2D>("AttackCollider") : null;
            string state = $"{input.Current.ShieldHeld}/{shield.IsActive}/{energy.IsOverheated}/" +
                $"{energy.IsShieldSustained}/{playerHealth.CurrentHealth}/{combat.IsAttacking}/" +
                $"{MathF.Round(shield.GuardDirection.X * 4f)}/{MathF.Round(shield.GuardDirection.Y * 4f)}/" +
                $"{centerInside}/{capsuleAabbOverlap}/{monitoredOverlap}/" +
                $"{(laneValid ? diagnosticLane.PulseCount : -1)}/{actorState}/{actorPhase}/{hitboxMonitoring}";
            if (reason == "state")
            {
                if (state == diagnosticLastState || diagnosticStateLogs >= 48) return;
                diagnosticLastState = state;
                diagnosticStateLogs++;
            }
            if (reason == "damage")
            {
                if (diagnosticDamageLogs >= 16 && playerHealth.CurrentHealth > 0) return;
                if (playerHealth.CurrentHealth <= 0 && diagnosticFatalLogged) return;
                if (playerHealth.CurrentHealth <= 0) diagnosticFatalLogged = true;
                diagnosticDamageLogs++;
            }
            GD.Print($"TASK10_GEAR_STATE reason={reason} physics={Engine.GetPhysicsFrames()} loop={currentFrame} " +
                $"sample={input.CurrentFrameSequence} player={player.GlobalPosition} velocity={player.Velocity} " +
                $"floor={GearDiagnosticFloor()} health={playerHealth.CurrentHealth} " +
                $"move={input.Current.MoveAxis} primary={input.Current.PrimaryPressed}/{input.Current.PrimaryHeld} " +
                $"shield_held={input.Current.ShieldHeld} shield_active={shield.IsActive} direction={shield.GuardDirection} " +
                $"energy={energy.EnergyRatio:0.000} heat={energy.HeatRatio:0.000} " +
                $"overheated={energy.IsOverheated} sustained={energy.IsShieldSustained} " +
                $"capsule_radius={capsule?.Radius} capsule_height={capsule?.Height} capsule_aabb={capsuleEnvelope} " +
                $"capsule_center={(GodotObject.IsInstanceValid(diagnosticCapsule) ? diagnosticCapsule.GlobalPosition.ToString() : "unavailable")} " +
                $"capsule_enabled={(GodotObject.IsInstanceValid(diagnosticCapsule) && !diagnosticCapsule.Disabled)} " +
                $"lane_valid={laneValid} lane_aabb={laneEnvelope} center_inside={centerInside} " +
                $"capsule_aabb_overlap={capsuleAabbOverlap} monitored_overlap={monitoredOverlap} " +
                $"lane_processing={(laneValid && diagnosticLane.IsPhysicsProcessing())} " +
                $"lane_monitoring={(laneValid && diagnosticLane.Monitoring)} " +
                $"lane_collider_enabled={(GodotObject.IsInstanceValid(laneCollider) && !laneCollider.Disabled)} " +
                $"lane_pulses={(laneValid ? diagnosticLane.PulseCount : -1)} " +
                $"lane_interval={(laneValid ? diagnosticLane.PulseIntervalSeconds : -1f):0.000} " +
                $"lane_damage={(laneValid ? diagnosticLane.Damage : -1)} lane_knockback={(laneValid ? diagnosticLane.Knockback : -1f)} " +
                $"arrival_active={(GodotObject.IsInstanceValid(group) && group.IsArrivalWarningActive)} " +
                $"actor={(actorValid ? liveActor.IsInsideTree() ? liveActor.GetPath().ToString() : "detached_actor" : "none")} " +
                $"actor_id={(actorValid ? liveActor.GetInstanceId() : 0)} " +
                $"actor_type={(actorValid ? liveActor.GetType().Name : "none")} " +
                $"actor_position={(actorValid ? liveActor.GlobalPosition.ToString() : "unavailable")} " +
                $"actor_state={actorState} actor_phase={actorPhase} hitbox_monitoring={hitboxMonitoring} " +
                $"hitbox_knockback={(GodotObject.IsInstanceValid(actorHitbox) ? actorHitbox.Knockback : -1f)} " +
                $"hitbox_collider_enabled={(GodotObject.IsInstanceValid(hitboxCollider) && !hitboxCollider.Disabled)} " +
                $"damage_impulse={(suppliedImpulse.HasValue ? suppliedImpulse.Value.ToString() : "not_supplied")}");
        }

        static Rect2 WorldEnvelope(CollisionShape2D collider, Vector2 halfSize)
        {
            Transform2D transform = collider.GlobalTransform;
            Rect2 envelope = new(transform * -halfSize, Vector2.Zero);
            envelope = envelope.Expand(transform * new Vector2(halfSize.X, -halfSize.Y));
            envelope = envelope.Expand(transform * halfSize);
            return envelope.Expand(transform * new Vector2(-halfSize.X, halfSize.Y));
        }

