                        gearBellMotor.AcceptedJumpCount == gearLureJumps && gearBellMotor.AcceptedDashCount == gearLureDashes &&
                        (gearPostLureLast == 0 || physics == gearPostLureLast + 1) &&
                        input.CurrentFrameSequence > gearPostLureSequence,
