                            $"target_is_player={isPlayer} last_damage_seq={steamBellLastDamageSequence} " +
                            $"last_damage_physics={steamBellLastDamagePhysics} " +
                            $"same_physics_as_last_damage={Engine.GetPhysicsFrames() == steamBellLastDamagePhysics} " +
                            "connected_can_be_blocked=true attribution=requires_pairing", fatalCandidate);
                    }
                    catch (Exception) { steamBellErrors++; }
                };
                steamBellHitbox.Connected += steamBellConnected;
                steamBell.FrameChanged += steamBellFrameChanged;
                steamBell.AttackFrameChanged += steamBellAttackChanged;
                if (!steamBellShieldSubscribed)
                {
                    shield.ShieldResolved += steamBellShieldResolved;
                    steamBellShieldSubscribed = true;
                }
                SteamBellSnapshot("bound", $"bound_actor={boundActorId} bound_hitbox={boundHitboxId}");
            }
            if (enemyHealth != observedEnemyHealth)
            {
                if (GodotObject.IsInstanceValid(observedEnemyHealth))
                    observedEnemyHealth.Damaged -= damaged;
                observedEnemyHealth = enemyHealth;
                if (GodotObject.IsInstanceValid(observedEnemyHealth))
                    observedEnemyHealth.Damaged += damaged;
            }
            Vector2 target = actor.GlobalPosition;
            if (actor is BellBackLaborer observedSplitBell) ObserveSplitBell("state", observedSplitBell);
            lastActorPosition = target;
            lastEnemyHealth = enemyHealth?.CurrentHealth;
            float dx = target.X - player.GlobalPosition.X;
            float dy = target.Y - player.GlobalPosition.Y;
            if (trackedActorId != actor.GetInstanceId())
            {
                trackedActorId = actor.GetInstanceId();
                desiredActorSide = Mathf.IsZeroApprox(dx) ? 1f : Mathf.Sign(dx);
                if (Task10IsSavedResident(actor))
                    GD.Print($"TASK10_RESIDENT_COMBAT_TARGET scene={actor.SceneFilePath} actor_id={trackedActorId} " +
                        $"player_id={player.GetInstanceId()} hp={enemyHealth?.CurrentHealth} " +
                        $"player={player.GlobalPosition} target={actor.GlobalPosition} wave={encounterId}");
            }
            bool splitBellPolicy = splitBellKeyboard && actor is BellBackLaborer;
            if (splitBellPolicy && actor is BellBackLaborer splitBell)
            {
                if (splitBellActorId == 0) splitBellActorId = splitBell.GetInstanceId();
                GuardSplitBell(splitBell);
                if (splitBell.CurrentState != BellBackLaborerState.Exposed)
                {
                    // The passive RED observed a successful first K, then J into Armor
                    // after exposure ended. Rearm from the first admitted stance, not
                    // an arbitrary75-loop cadence; no J/L may cancel the next flight.
                    if(!splitBellRearming) { splitBellRearming=true; splitBellRearmEpisode++; splitBellRearmSamples=0; }
                    splitBellRearmSamples++;
                    SendAction(InputActions.PrimaryAction, false);
                    SendAction(InputActions.Attack, false);
                    SendAction(InputActions.MoveUp, false);
                    SendAction(InputActions.MoveDown, false);
                    SendAction(InputActions.Jump, false);
                    MechanicalClawController splitBellRearmClaw = player.GetNode<MechanicalClawController>("MechanicalClaw");
                    bool idle = !combat.IsAttacking && splitBellRearmClaw.CurrentFrame.State == MechanicalClawState.Idle &&
                        splitBellRearmClaw.CurrentFrame.Failure == MechanicalClawFailure.None;
                    float error = float.IsFinite(splitBellCastStanceX)
                        ? splitBellCastStanceX - player.GlobalPosition.X : 0f;
                    float vx = player.Velocity.X;
                    float braking = vx * vx / (2f * splitBellMotor.Tuning.GroundAcceleration) +
                        MathF.Abs(vx) / Engine.PhysicsTicksPerSecond;
                    // This early continue used to bypass the shared danger
                    // consumer entirely. Keep the original scanner/guard rules
                    // here too, before deciding to move or start a new cast.
                    Task10EncounterDanger rearmDanger;
                    try
                    {
                        rearmDanger=Task10ObserveEncounterDanger(actorRoot,encounterId,actor,false,rangedThreatLeaves);
                    }
                    finally { rangedThreatLeaves.Clear(); }
                    bool rearmDefend=!combat.IsAttacking && splitBellRearmClaw.CurrentFrame.State==MechanicalClawState.Idle &&
                        Task10MixedDefendWindow(shield,rearmDanger);
                    monitor.CombatDecisionObserved?.Invoke(actor.GetInstanceId(),rearmDanger,rearmDefend);
                    if(rearmDefend)
                    {
                        SendAction(InputActions.MoveLeft,false);
                        SendAction(InputActions.MoveRight,false);
                        SendMouse(MouseButton.Right,true,player,rearmDanger.GuardSource);
                        ObserveSplitBellRearm(splitBell,rearmDanger,true,idle,false,0,error,braking);
                        await PhysicsFrames(tree,monitor,1);
                        GuardSplitBell(splitBell);
                        continue; // Real defense takes this original one-frame slot; no new wait budget.
                    }
                    SendMouse(MouseButton.Right,false,player,target);
                    int direction = idle && MathF.Abs(error) > 1.5f ? MathF.Sign(error) : 0;
                    if (direction != 0 && vx * error > 0f && MathF.Abs(error) <= braking + 1.5f)
                        direction = -MathF.Sign(vx);
                    SendAction(InputActions.MoveLeft, direction < 0);
                    SendAction(InputActions.MoveRight, direction > 0);
                    bool neutral = direction == 0 && MathF.Abs(error) <= 1.5f && player.Velocity.Length() <= 2f &&
                        input.CurrentFrame.MoveAxis == 0f && !input.CurrentFrame.AttackPressed &&
                        !input.CurrentFrame.ClawPressed && !input.CurrentFrame.ShieldHeld &&
                        !shield.IsActive && !Input.IsPhysicalKeyPressed(Key.L);
                    ObserveSplitBellRearm(splitBell,rearmDanger,false,idle,neutral,direction,error,braking);
                    if (idle && neutral)
                    {
                        ThreadTarget2D splitTarget = splitBell.GetNode<ThreadTarget2D>("ThreadTarget");
                        LegacyThreadInteractionAdapter splitAdapter =
                            splitTarget.GetNode<LegacyThreadInteractionAdapter>("LegacyThreadInteractionAdapter");
                        TestAssert.True(Task10KeyboardClawPlanSelects(player, splitTarget),
                            "keyboard split Bell rearm retains exact native target and LOS at its admitted stance");
                        int applications = splitAdapter.ApplicationCount;
                        ulong nextCast = splitBellRearmClaw.CurrentFrame.NextCastId;
                        if (!float.IsFinite(splitBellCastStanceX)) splitBellCastStanceX = player.GlobalPosition.X;
                        ObserveSplitBell("exposure-rearm-before-CastAt");
                        await CastAt(tree, monitor, player, splitTarget,
                            () => splitBell.CurrentState == BellBackLaborerState.Exposed, 45);
                        GuardSplitBell(splitBell);
                        TestAssert.True(splitAdapter.ApplicationCount == applications + 1 &&
                            splitBellRearmClaw.CurrentFrame.NextCastId == nextCast + 1 &&
                            splitBellRearmClaw.CurrentFrame.Failure == MechanicalClawFailure.None &&
                            splitBell.CurrentState == BellBackLaborerState.Exposed &&
                            splitBell.GetNode<Hurtbox>("Hurtbox").DamageReceiverPath == new NodePath("../Health"),
                            "keyboard split Bell observes one real new cast/application and Health exposure before J");
                        ObserveSplitBell("exposure-rearm-after-CastAt");
                        threadCasts++;
                        SendAction(InputActions.SelectAttackMode, true);
                        await PhysicsFrames(tree, monitor, 1);
                        SendAction(InputActions.SelectAttackMode, false);
                    }
                    wasInStrikeRange = false;
                    await PhysicsFrames(tree, monitor, 1);
                    GuardSplitBell(splitBell);
                    continue;
                }
                splitBellRearming=false;
            }
            if (courtyardKeyboardJump && group.CurrentBatch == 1 && actor is BellBackLaborer &&
                !courtyardJumpComplete && (courtyardJumpPreparing || dy < -74f))
            {
                // This authored Bell is 80px above CourtyardStep. The old generic
                // approach released Space as soon as airborne, cutting the jump short.
                // Every phase below uses this loop's existing one-frame wait/900 budget.
                if (!courtyardJumpPreparing)
                {
                    TestAssert.True(CourtyardJumpSupport(courtyardJumpStep, courtyardJumpStepShape),
                        "keyboard courtyard upper Bell jump begins on complete actual CourtyardStep support");
                    courtyardJumpPreparing = true;
                    courtyardJumpPlayerId = player.GetInstanceId();
                    courtyardJumpActorId = actor.GetInstanceId();
                    courtyardJumpBaseline = courtyardJumpMotor.AcceptedJumpCount;
                    courtyardDashBaseline = courtyardJumpMotor.AcceptedDashCount;
                    courtyardRequestBaseline = monitor.RecoveryRequested;
                    courtyardRecoveryBaseline = monitor.RecoveryCompleted;
                    courtyardNeutralSequence = input.CurrentFrameSequence;
                    CourtyardJumpSnapshot("prepare", actor);
                }
                TestAssert.True(player.GetInstanceId() == courtyardJumpPlayerId &&
                    monitor.Player.GetInstanceId() == courtyardJumpPlayerId && actor.GetInstanceId() == courtyardJumpActorId &&
                    playerHealth.CurrentHealth == playerHealthAtStart &&
                    monitor.RecoveryRequested == courtyardRequestBaseline &&
                    monitor.RecoveryCompleted == courtyardRecoveryBaseline &&
                    courtyardJumpMotor.AcceptedDashCount == courtyardDashBaseline &&
                    courtyardJumpMotor.AcceptedJumpCount >= courtyardJumpBaseline &&
                    courtyardJumpMotor.AcceptedJumpCount <= courtyardJumpBaseline + 1 &&
                    (!courtyardJumpLanded || CourtyardJumpSupport(courtyardJumpFloor, courtyardJumpFloorShape)) &&
                    player.GlobalPosition.IsFinite() && player.Velocity.IsFinite(),
                    "keyboard courtyard step jump preserves same player, HP, recoveries and one ordinary jump/no dash");
                // Clear the adapter's hold intents as well as raw keys before real D.
                SendMouse(MouseButton.Right, false, player, target);
                SendAction(InputActions.PrimaryAction, false);
                SendAction(InputActions.Attack, false);
                SendAction(InputActions.Claw, false);
                SendAction(InputActions.MoveUp, false);
                SendAction(InputActions.MoveDown, false);
                SendAction(InputActions.MoveLeft, false);
                SendAction(InputActions.MoveRight, !courtyardJumpLanded);
                if (!courtyardJumpIssued)
                {
                    SendAction(InputActions.Jump, false);
                    TestAssert.True(CourtyardJumpSupport(courtyardJumpStep, courtyardJumpStepShape) &&
                        courtyardJumpMotor.AcceptedJumpCount == courtyardJumpBaseline,
                        "keyboard courtyard jump preparation retains complete lower support without a prior jump");
                    var upperRectangle = (RectangleShape2D)courtyardJumpFloorShape.Shape;
                    float upperLeft = courtyardJumpFloorShape.GlobalPosition.X - upperRectangle.Size.X * .5f;
                    float launchX = upperLeft - playerCapsule.Radius - 8f;
                    if (player.GlobalPosition.X >= launchX && input.CurrentFrameSequence > courtyardNeutralSequence &&
                        !input.CurrentFrame.JumpHeld && !input.CurrentFrame.JumpPressed && !combat.IsAttacking &&
                        HasFloorContact((CharacterBody2D)actor, courtyardJumpFloor))
                    {
                        courtyardJumpIssued = true;
                        courtyardIssueSequence = courtyardLastSequence = input.CurrentFrameSequence;
                        courtyardIssuePhysics = Engine.GetPhysicsFrames();
                        SendAction(InputActions.Jump, true);
                        CourtyardJumpSnapshot("edge-issued", actor);
                    }
                }
                else
                {
                    if (input.CurrentFrameSequence > courtyardLastSequence)
                    {
                        courtyardLastSequence = input.CurrentFrameSequence;
                        if (input.CurrentFrame.JumpPressed)
                        {
                            courtyardJumpEdges++;
                            courtyardEdgeSequence = input.CurrentFrameSequence;
                            TestAssert.True(courtyardJumpEdges == 1,
                                "keyboard courtyard step uses one fresh Space edge, never an air-jump retry");
                            CourtyardJumpSnapshot("fresh-edge", actor);
                        }
                        if (courtyardEdgeSequence != 0 && !courtyardJumpReleased)
                        {
                            TestAssert.True(input.CurrentFrame.JumpHeld && input.CurrentFrame.MoveAxis > 0f &&
                                input.CurrentFrame.KeyboardActions && !input.CurrentFrame.DashPressed &&
                                !input.CurrentFrame.AttackPressed && !input.CurrentFrame.ClawPressed &&
                                !input.CurrentFrame.PrimaryPressed && !input.CurrentFrame.ShieldHeld &&
                                Engine.GetPhysicsFrames() > courtyardLastHeldPhysics,
                                "keyboard courtyard rise samples real held Space+D without combat/legacy input");
                            courtyardLastHeldPhysics = Engine.GetPhysicsFrames();
                            courtyardHeldSamples++;
                            if (courtyardHeldSamples <= 4 || courtyardHeldSamples % 2 == 0)
                                CourtyardJumpSnapshot("held-sample", actor);
                        }
                    }
                    bool jumpAccepted = courtyardEdgeSequence > courtyardIssueSequence &&
                        courtyardJumpMotor.AcceptedJumpCount == courtyardJumpBaseline + 1;
                    TestAssert.True(jumpAccepted || Engine.GetPhysicsFrames() - courtyardIssuePhysics < 8,
                        "keyboard courtyard fresh grounded Space is actually accepted within eight physics frames");
                    if (jumpAccepted && courtyardHeldSamples == 12 && !courtyardJumpReleased)
                    {
                        SendAction(InputActions.Jump, false);
                        courtyardJumpReleased = true;
                        courtyardReleaseSequence = input.CurrentFrameSequence;
                        CourtyardJumpSnapshot("release-issued", actor);
                    }
                    bool sampledRelease = courtyardJumpReleased && input.CurrentFrameSequence > courtyardReleaseSequence &&
                        !input.CurrentFrame.JumpHeld && !input.CurrentFrame.JumpPressed;
                    if (sampledRelease && CourtyardJumpSupport(courtyardJumpFloor, courtyardJumpFloorShape))
                    {
                        if (!courtyardJumpLanded)
                        {
                            courtyardFirstLandingX = player.GlobalPosition.X;
                            CourtyardJumpSnapshot("full-upper-landing", actor);
                        }
                        courtyardJumpLanded = true;
                        SendAction(InputActions.MoveRight, false);
                        if (input.CurrentFrame.MoveAxis == 0f && player.Velocity.Length() <= 2f)
                        {
                            TestAssert.True(jumpAccepted && courtyardJumpEdges == 1 && courtyardHeldSamples == 12,
                                "keyboard courtyard upper landing proves exactly one accepted jump and twelve held physics samples");
                            courtyardJumpComplete = true;
                            CourtyardJumpSnapshot("neutral-upper-complete", actor);
                        }
                    }
                }
                wasInStrikeRange = false;
                await PhysicsFrames(tree, monitor, 1);
                continue;
            }
            bool courtyardBellPolicy = courtyardKeyboardJump && group.CurrentBatch == 1 &&
                actor is BellBackLaborer && courtyardJumpComplete;
            bool courtyardBellExposed = courtyardBellPolicy &&
                ((BellBackLaborer)actor).CurrentState == BellBackLaborerState.Exposed &&
                actor.GetNode<Hurtbox>("Hurtbox").DamageReceiverPath == new NodePath("../Health");
            if (courtyardBellPolicy)
            {
                TestAssert.True(player.GetInstanceId() == courtyardJumpPlayerId &&
                    monitor.Player.GetInstanceId() == courtyardJumpPlayerId && actor.GetInstanceId() == courtyardJumpActorId &&
                    playerHealth.CurrentHealth == playerHealthAtStart && enemyHealth?.CurrentHealth > 0 &&
                    monitor.RecoveryRequested == courtyardRequestBaseline && monitor.RecoveryCompleted == courtyardRecoveryBaseline &&
                    courtyardJumpMotor.AcceptedJumpCount == courtyardJumpBaseline + 1 &&
                    courtyardJumpMotor.AcceptedDashCount == courtyardDashBaseline &&
                    CourtyardJumpSupport(courtyardJumpFloor, courtyardJumpFloorShape) &&
                    HasFloorContact((BellBackLaborer)actor, courtyardJumpFloor) &&
                    player.GlobalPosition.IsFinite() && player.Velocity.IsFinite(),
                    "keyboard courtyard Bell cycles preserve same live actors, HP, recoveries, full upper support and one jump/no dash");
                if (courtyardBellComplete && !courtyardBellExposed)
                {
                    TestAssert.True(((BellBackLaborer)actor).CurrentState != BellBackLaborerState.Exposed &&
                        actor.GetNode<Hurtbox>("Hurtbox").DamageReceiverPath == new NodePath("../Armor"),
                        "keyboard courtyard rearm independently observes the real return to Armor after exposure");
                    CourtyardBellSnapshot("armor-returned-rearm");
                    courtyardBellPreparing = courtyardBellIssued = courtyardBellKeyReleased =
                        courtyardBellReceipt = courtyardBellReleased = courtyardBellComplete = false;
                    courtyardBellInvalidReceipt = false;
                    courtyardBellEdges = 0;
                    courtyardBellSpacingPhase = 0;
                    courtyardBellIssueSequence = courtyardBellLastSequence = courtyardBellEdgeSequence =
                        courtyardBellReceiptSequence = courtyardBellReceiptPhysics = courtyardBellCast = 0;
                    courtyardBellLastState = "";
                }
            }
            if (courtyardBellPolicy && actor is BellBackLaborer openingBell && !courtyardBellComplete)
            {
                // One real K per observed exposure cycle, inside the original 900-iteration loop.
                // Armor is never a J window. No J/L may cancel the next exposure's flight.
                if (!courtyardBellPreparing)
                {
                    if (courtyardBellCycle == 0)
                    {
                        courtyardBell = openingBell;
                        courtyardBellTarget = actor.GetNode<ThreadTarget2D>("ThreadTarget");
                        courtyardBellAdapter = courtyardBellTarget.GetNode<LegacyThreadInteractionAdapter>("LegacyThreadInteractionAdapter");
                        courtyardBellFirstApplications = courtyardBellAdapter.ApplicationCount;
                        courtyardBellFirstRawEdges = KeyboardRouteInputDriver.Current.ClawEdges;
                        courtyardBellClaw.ClawFrameChanged += ObserveCourtyardBellClaw;
                    }
                    courtyardBellCycle++;
                    TestAssert.True(courtyardBellCycle <= 900 && openingBell == courtyardBell &&
                        actor.GetNode<ThreadTarget2D>("ThreadTarget") == courtyardBellTarget &&
                        courtyardBellAdapter.ApplicationCount == courtyardBellFirstApplications + courtyardBellCycle - 1 &&
                        KeyboardRouteInputDriver.Current.ClawEdges == courtyardBellFirstRawEdges + courtyardBellCycle - 1,
                        "keyboard courtyard reuses the same native Bell target and exactly one K/application per prior exposure cycle");
                    courtyardBellPreparing = true;
                    courtyardBellApplications = courtyardBellAdapter.ApplicationCount;
                    courtyardBellRawEdges = KeyboardRouteInputDriver.Current.ClawEdges;
                    courtyardBellNeutralSequence = input.CurrentFrameSequence;
                    TestAssert.True(openingBell.CurrentState != BellBackLaborerState.Exposed,
                        "keyboard courtyard opening cannot reuse an existing Bell exposure");
                    CourtyardBellSnapshot("opening-prepare");
                }
                SendMouse(MouseButton.Right, false, player, target);
                SendAction(InputActions.Attack, false);
                SendAction(InputActions.MoveUp, false);
                SendAction(InputActions.MoveDown, false);
                SendAction(InputActions.MoveLeft, false);
                SendAction(InputActions.MoveRight, false);
                SendAction(InputActions.Jump, false);
                if (!courtyardBellIssued)
                {
                    SendAction(InputActions.PrimaryAction, false);
                    SendAction(InputActions.Claw, false);
                    bool idle = !combat.IsAttacking && courtyardBellClaw.CurrentFrame.State == MechanicalClawState.Idle &&
                        courtyardBellClaw.CurrentFrame.Failure == MechanicalClawFailure.None;
                    bool stanceReady;
                    {
                        // The first landing is a candidate, not a successful cast.
                        // Neutral inertia may have carried the player inside Bell's
                        // enemy body before this opening. Return using real keys;
                        // only the unchanged native preflight may admit the target.
                        float stanceX = courtyardBellCycle == 1 ? courtyardFirstLandingX : courtyardBellCastStanceX;
                        TestAssert.True(float.IsFinite(stanceX),
                            "keyboard courtyard retains actual first landing or actually admitted rearm stance");
                        float error = stanceX - player.GlobalPosition.X;
                        float vx = player.Velocity.X;
                        var stop = FreeMotionForecast.Neutral(vx, true, courtyardJumpMotor.MotionSettings,
                            courtyardJumpMotor.ThrusterState.Module, 1d / Engine.PhysicsTicksPerSecond,
                            900 - frame, 2f);
                        TestAssert.True(stop.SpeedThresholdReached,
                            "courtyard neutral stance forecast fits remaining original900 budget");
                        float braking = stop.NetDistance;
                        float stopX = player.GlobalPosition.X + braking;
                        Vector2 inward = courtyardBellCycle == 1
                            ? PlayerKeyboardAimModel.ResolveDirection(courtyardBellTarget.WorldAnchor - player.GlobalPosition, 1)
                            : courtyardBellPlanned;
                        bool inwardFacing = input.KeyboardAimDirection.Dot(inward) > .99f;
                        stanceReady = MathF.Abs(error) <= 1.5f && player.Velocity.Length() <= 2f && inwardFacing;
                        if (!stanceReady)
                        {
                            // J's real facing pulses creep toward Bell. Reuse the first native
                            // winning stance with normal A/D, not a forced target or body pose.
                            int direction = MathF.Abs(stanceX - stopX) <= 1.5f ? 0 : MathF.Sign(stanceX - stopX);
                            if (direction == 0 && player.Velocity.Length() <= 2f && !inwardFacing)
                                direction = MathF.Sign(inward.X);
                            if (idle)
                            {
                                SendAction(InputActions.MoveLeft, direction < 0);
                                SendAction(InputActions.MoveRight, direction > 0);
                                if (courtyardBellSpacingPhase == 0)
                                {
                                    courtyardBellSpacingPhase = 1;
                                    CourtyardBellSnapshot("rearm-spacing-start", detail:
                                        $"stance_x={stanceX:R} stance_delta={error:R} braking={braking:R} " +
                                        $"stop_x={stopX:R} forecast_steps={stop.Steps} direction={direction}");
                                }
                            }
                            courtyardBellNeutralSequence = input.CurrentFrameSequence;
                        }
                        else if (courtyardBellSpacingPhase == 1)
                        {
                            courtyardBellSpacingPhase = 2;
                            CourtyardBellSnapshot("rearm-spacing-stopped", detail:
                                $"stance_x={stanceX:R} stance_delta={error:R} braking={braking:R} stop_x={stopX:R}");
                        }
                    }
                    bool neutral = stanceReady && player.Velocity.Length() <= 2f &&
                        input.CurrentFrameSequence > courtyardBellNeutralSequence &&
                        input.CurrentFrame.MoveAxis == 0f && !input.CurrentFrame.AttackPressed &&
                        !input.CurrentFrame.ClawPressed && !input.CurrentFrame.ShieldHeld &&
                        !input.CurrentFrame.JumpPressed && !input.CurrentFrame.JumpHeld &&
                        !Input.IsPhysicalKeyPressed(Key.J) && !Input.IsPhysicalKeyPressed(Key.K) && !Input.IsPhysicalKeyPressed(Key.L);
                    if (neutral && idle)
                    {
                        courtyardBellPlanned = PlayerKeyboardAimModel.ResolveDirection(
                            courtyardBellTarget.WorldAnchor - player.GlobalPosition, 1);
                        MechanicalClawTargetResolution selection = new MechanicalClawTargetResolver().ResolveKeyboard(player, courtyardBellPlanned);
                        bool targetAvailable = courtyardBellTarget.IsAvailable;
                        bool receiverEligible = courtyardBellTarget.TryGetEligibleReceiver(player, out Node receiver);
                        CourtyardBellSnapshot("opening-preflight", detail:
                            $"target={courtyardBellTarget.GetPath()} target_id={courtyardBellTarget.GetInstanceId()} " +
                            $"target_anchor={courtyardBellTarget.WorldAnchor} planned={courtyardBellPlanned} " +
                            $"available={targetAvailable} eligible={receiverEligible} receiver_is_bell={receiver == openingBell} " +
                            $"receiver_id={(GodotObject.IsInstanceValid(receiver) ? receiver.GetInstanceId() : 0UL)} " +
                            $"bell_id={openingBell.GetInstanceId()} selected={selection.Surface?.GetPath()} " +
                            $"selected_id={selection.Snapshot.RuntimeId} selected_exists={selection.Snapshot.Exists} " +
                            $"selected_anchor={selection.Snapshot.WorldAnchor} selected_los={selection.Snapshot.HasLineOfSight} " +
                            $"selected_legacy={selection.Snapshot.IsLegacyInteraction} selected_material={selection.Snapshot.Material}");
                        TestAssert.True(targetAvailable && receiverEligible && receiver == openingBell &&
                            enemyHealth?.CurrentHealth > 0 &&
                            selection.Surface == courtyardBellTarget && selection.Snapshot.RuntimeId == courtyardBellTarget.GetInstanceId() &&
                            selection.Snapshot.HasLineOfSight && selection.Snapshot.IsLegacyInteraction &&
                            (courtyardBellCycle == 1 || input.KeyboardAimDirection.Dot(courtyardBellPlanned) > .99f),
                            "keyboard courtyard opening has the exact live Bell native keyboard target and LOS");
                        if (courtyardBellCycle == 1) courtyardBellCastStanceX = player.GlobalPosition.X;
                        courtyardBellCast = courtyardBellClaw.CurrentFrame.NextCastId;
                        courtyardBellIssueSequence = courtyardBellLastSequence = input.CurrentFrameSequence;
                        SendAction(InputActions.SelectGrappleMode, true);
                        SendAction(InputActions.SelectGrappleMode, false);
                        courtyardBellIssued = true;
                        SendMouse(MouseButton.Left, true, player, courtyardBellTarget.WorldAnchor);
                        CourtyardBellSnapshot("opening-K-issued");
                    }
                }
                else
                {
                    if (input.CurrentFrameSequence > courtyardBellLastSequence)
                    {
                        courtyardBellLastSequence = input.CurrentFrameSequence;
                        if (input.CurrentFrame.ClawPressed)
                        {
                            courtyardBellEdges++;
                            courtyardBellEdgeSequence = input.CurrentFrameSequence;
                            TestAssert.True(courtyardBellEdges == 1 && input.CurrentFrame.KeyboardActions &&
                                input.KeyboardAimDirection.Dot(courtyardBellPlanned) > .999f &&
                                !input.CurrentFrame.AttackPressed && !input.CurrentFrame.ShieldHeld && !input.CurrentFrame.PrimaryPressed,
                                "keyboard courtyard opening samples exactly one real K/octant without J/L or legacy primary");
                            SendAction(InputActions.PrimaryAction, false);
                            SendAction(InputActions.Claw, false);
                            courtyardBellKeyReleased = true;
                            CourtyardBellSnapshot("opening-K-sampled-released");
                        }
                    }
                    TestAssert.True(!courtyardBellInvalidReceipt && courtyardBellClaw.CurrentFrame.Failure == MechanicalClawFailure.None &&
                        KeyboardRouteInputDriver.Current.ClawEdges == courtyardBellRawEdges + 1 &&
                        courtyardBellAdapter.ApplicationCount <= courtyardBellApplications + 1 &&
                        courtyardBellClaw.CurrentFrame.NextCastId >= courtyardBellCast &&
                        courtyardBellClaw.CurrentFrame.NextCastId <= courtyardBellCast + 1,
                        "keyboard courtyard opening never fails, repeats K/cast, or applies a second interaction");
                    if (courtyardBellReceipt && courtyardBellReleased && courtyardBellKeyReleased &&
                        Engine.GetPhysicsFrames() > courtyardBellReceiptPhysics &&
                        openingBell.CurrentState == BellBackLaborerState.Exposed &&
                        openingBell.GetNode<Hurtbox>("Hurtbox").DamageReceiverPath == new NodePath("../Health"))
                    {
                        TestAssert.True(courtyardBellEdges == 1 && courtyardBellEdgeSequence > courtyardBellIssueSequence &&
                            courtyardBellReceiptSequence >= courtyardBellEdgeSequence &&
                            courtyardBellAdapter.ApplicationCount == courtyardBellApplications + 1 &&
                            courtyardBellClaw.CurrentFrame.NextCastId == courtyardBellCast + 1 &&
                            !input.CurrentFrame.ClawPressed && !input.CurrentFrame.AttackPressed && !input.CurrentFrame.ShieldHeld &&
                            !Input.IsPhysicalKeyPressed(Key.J) && !Input.IsPhysicalKeyPressed(Key.K) && !Input.IsPhysicalKeyPressed(Key.L),
                            "keyboard courtyard opening independently observes one same-cast adapter receipt then real Health-exposed Bell before J");
                        courtyardBellComplete = true;
                        threadCasts++;
                        SendAction(InputActions.SelectAttackMode, true);
                        SendAction(InputActions.SelectAttackMode, false);
                        CourtyardBellSnapshot("opening-independent-exposed");
                    }
                }
                wasInStrikeRange = false;
                await PhysicsFrames(tree, monitor, 1);
