                        $"beam_aim={rear.AimDirection} front={front} foreign={courtyardForeignSources}/{courtyardForeignSafe:R} " +
                        $"danger={encounterDanger.SourceActorId}/{encounterDanger.AttackId}/{encounterDanger.Phase} " +
