                    GodotObject.IsInstanceValid(lowerControlTarget) && lowerControlTarget.GetInstanceId() == lowerControlTargetId &&
                    lowerControlAdapter.ApplicationCount <= lowerControlApplications + 1 && !lowerControlFault &&
