                steamBellLastDanger = encounterDanger;
                steamBellDangerSequence = input.CurrentFrameSequence;
            }
            bool steamMissileKeyboard = (tree is RunRealtimePrologueProbe || headlessNormalPlan) && KeyboardRouteInputDriver.Current != null &&
                steamSentryDiagnostic && group.CurrentBatch == 2 && group.LiveActorCount == 1 &&
                actor is FurnaceMissileGunner && actor.SceneFilePath == CanyonEncounterCatalog.MissileScene;
            Task10SteamMissileDecision steamDecision = steamMissileKeyboard
                ? Task10SteamMissileKeyboardDecision(player, (RangedWeaponEnemy)actor, combat, energy, shield,
                    encounterDanger, strikeRange, frame, nextAttackFrame, rangedThreatLeaves) : default;
            bool skitterEligible = skitterPolicy && skitterCanCounter && strikeRange &&
                frame >= nextAttackFrame && !combat.IsAttacking && modes.CanAffordAttack && modes.CanBeginAttack;
            if (skitterEligible != skitterCounterEligible)
