            if (KeyboardRouteInputDriver.Current != null && skitterPolicy && !skitterThreat &&
                ((CanyonSkitter)actor).CurrentFrame.AttackTimeline.Phase != AttackPhase.Recovery)
            {
                // WASD is shared with shield aim. The old pointer strategy could stand
