                    bool lureNeutral = MathF.Abs(player.Velocity.X) <= 2f && MathF.Abs(input.Current.MoveAxis) <= .001f &&
                        !Input.IsPhysicalKeyPressed(Key.A) && !Input.IsPhysicalKeyPressed(Key.D);
                    if (input.CurrentFrameSequence > gearLureSequence)
