                        mixedPreviewPose == player.GlobalTransform && mixedPreviewVelocity == player.Velocity &&
                        mixedPreviewAim == input.KeyboardAimDirection &&
                        mixedPreviewAnchor.IsEqualApprox(mixedClawTarget.WorldAnchor);
