                        mixedOwnPrepJumps = mixedClawMotor.AcceptedJumpCount; mixedOwnPrepDashes = mixedClawMotor.AcceptedDashCount;
                        mixedOwnPrepEdges = KeyboardRouteInputDriver.Current.ClawEdges;
