                    (mixedPostShotSchedule ? mixedClawShotSeen && (!mixedLiveEnrolled || publishedOwnPreview)
                        : mixedClawShotSeen || publishedOwnPreview))
                {
                    mixedClawWindowPhysics = Engine.GetPhysicsFrames();
