                    if (mixedLiveEnrolled) CaptureMixedClawBaseline();
                    mixedClawEdges = KeyboardRouteInputDriver.Current.ClawEdges;
                    mixedClawSequence = input.CurrentFrameSequence;
                    mixedClawCastId = mixedClaw.CurrentFrame.NextCastId;
